    "body": "​\n상동역 도보 30초거리 초역세권 샵인샵 원장님 구합니다.\n​\n종목: 반09, 속눈썹, smp 가능\n위치 : 상동역 1번출구쪽 (7호선) 도보 30초, 무료 주차 지원\n제공 집기 : 베드 1개, 의자, 조명, 벽거울, 담요, 행거, 정수기, cctv\n사업자 등록 X\n​\n------------------------------------------------------------------\n​\n[샵인샵]\n​\n1) 샵인샵 1개월 계약시\n보증금 50 월세 50(관리비 포함)\n​\n2) 샵인샵 3개월 계약시\n보증금 50 월세 45(관리비 포함)\n​\n​\n[베드쉐어] - 시간제 X\n​\n1) 베드쉐어 1개월 계약시\n보증금 50 월세 40(관리비 포함)\n​\n2) 베드쉐어 3개월 계약시\n보증금 50 월세 35(관리비 포함)\n​\n​\n------------------------------------------------------------------\n​\n* 프라이빗한 개인 단독룸\n* 출퇴근시간 터치 없음\n* 7호선 라인이라 서울, 인천분들도 많이 방문 주십니다.\n* 상동역 바로 앞에 위치해있고 건물 자체가 매우 커서 입점된 상권들이 많습니다.\n* 엘레베이터는 비상용 포함 총 6개\n* 주차장은 지하1~2층까지 넓게 있어서 주차하기 좋습니다.\n* 샵 청소 주기적으로 하면서 청결함 유지합니다.\n​\n📞공일공 4구55 7육5육\n​\n시간 상관없이 편하게 문자로 부탁드립니다!\n보는대로 바로 답장드리겠습니다",
