    "body": "안녕하세요^^\n​\n방학동 도깨비 시장 길목 1층에서\n​\n알차게 운영해 온 1인 뷰티샵입니다.\n​\n신랑 직장 발령으로 인해\n​\n타지역 먼곳으로 이사일정이 확정되면서\n​\n아쉬운 마음으로 다음 원장님을 모셔요~\n​\n​\n​\n♡방학동 신동아아파트 4단지 앞에 위치하고\n​\n도깨비 시장으로 들어가는 1층 길목이라\n​\n유동인구 많고 동네 단골 장사하기 좋아요.\n​\n기존 단골 고객을 확보하고 시작하실 수 있구요^^\n​\n​\n​\n♡월세와 고정비 지출이 적어서 부담 없어요.\n​\n보증금1000-월세50\n​\n관리비 없구요, 전기세,수도세는 3만원 이하.\n​\n권리금:300만원\n​\n​\n​\n♡소자본으로 1인샵 시작해보고 싶으신 분\n​\n환영합니다.(ㅂㅇㄱ,smp,속눈썹 등)\n​\n개인용품 소지하시면 바로 운영 가능해요.\n​\n​\n​\n♡12월 중순~하순으로 날짜 협의해드려요.\n​\n조명,에어콘 설치 되어 있구요,\n​\n따로 인테리어 하실거 없어요.\n​\n(고객님들이 가게에 오시면\n​\n카페같다고 좋아하세요^^)\n​\n현장 오시는건 언제든 환영합니다.\n​\n편하게 연락주세요~\n​\n​\n​\n♡소자본 1인 샵.\n​\n첫 출발로 최적!!!\n​\n고정비 적게 내며 알짜로 운영하실\n​\n원장님께 강력 추천합니다!!!\n​\n​\n​\n♡필요하시면 4년간 쌓아온\n​\n고객님들 명단 그대로\n전화번호 넘겨드리고 갈게요.\n​\n가게폰 명의이전 가능해요.\n​\n어차피 전 너무 먼 지역으로 가는거라\n​\n기존번호가 소용 없거든요.\n​\n실제로 보시면 훨씬 예뻐서 맘에\n​\n드실거예요~^^\n​\n​\n​\n​\n010-2276-8253\n​\n​\n​\n​\n​",
