    "body": "분당 서현역에서 속눈썹관련 샵인입점 원장님 연락주세요\n​\n제가 개인사정상 다른일이 있어 샵에는 자주 출근하지 않아요.\n헤드스파 기기가 있는 창가쪽 사진상 룸을 사용하시면 되시고,\n추후 제가 헤드스파쪽을 사용하게 될시 다른 단독룸을 사용할수\n있게 일정 조정 해 드릴수 있습니다.\n​\n이용 조건\n​\n- 사업자등록 가능\n​\n- 출퇴근 시간 자유\n​\n- 온열베드 구비(본인 시술물건과 소모품은 직접 지참)\n​\n- 기계식 주차장 이용 가능\n​\n- 고객 주차 2시간 무료\n​\n- 현재 샵인으로 산전산후원장님, 반** 원장님 입점이므로 중복은\n불가합니다.\n​\n*​입점 조건\n​\n​- 보증금 200만 원 / 월세 60만 원\n​\n- 관리비 1/N 분담\n​\n- 3개월부터 시작 ,연장시 서로 합의하에 갱신계약.\n​\n연락은 이쪽으로 주세요.\n​\nhttps://open.kakao.com/o/syXoA7fe\n발리블루스/경기님의 오픈프로필\nopen.kakao.com\n​\n​\n​",
