    "summary": "임신 및 출산으로 샵 양도합니다 ! 상가주택건물 약 16평샵입니다! 샵인에서 확장하시거나, 샵 운영하시면서 샵인 들이고싶은 분께 추천드려요 속눈썹전문샵이고, ㅂㅇㄱ, 피부 운영했고, 얼마전까지 네일 샵인 들어와서 운영했습니다:) ​ 스탠드 에어컨 23년식으로 시원하고, 두 벽면이 창문으",
    "body": "임신 및 출산으로 샵 양도합니다 !\n상가주택건물 약 16평샵입니다! 샵인에서 확장하시거나,\n샵 운영하시면서 샵인 들이고싶은 분께 추천드려요\n속눈썹전문샵이고, ㅂㅇㄱ, 피부 운영했고,\n얼마전까지 네일 샵인 들어와서 운영했습니다:)\n​\n스탠드 에어컨 23년식으로 시원하고,\n두 벽면이 창문으로 되어있어서 환기시키기도 좋습니다.\n룸은 총 3개이고, 1개는 상담실로 사용했고\n룸 2개는 각 베드 1개씩 넣고 그 사이 가벽을 뚫어\n동시시술도 가능하게 되어있습니다.\n그 중 룸 1개는 피부실로 사용해서 세면대 있고,\n탈의해도 밖에서 안보이게 커텐 신경써서 달아놨어요.\n수납 및 장은 기존제품아니고 목공소에서 직접맞춰\n엄청 튼튼합니다\n용죽지구 주차 복잡한데 여긴 건물에 주차 가능하시고, 건물에 만차 시 건물 앞 골목에 주차 가능합니다.\n화장실도 내부에 있어서 너무 좋아요!\n​\n버스정류장도 도보 약 2-3분이라\n평택역이나 다른 곳에서 오시는 분들도 꽤 많으세요.\n상가주택 건물 2층이고 엘베있습니다.\n아래1층은 국수집, 나머지 건물은 다 가정집이라\n조용해요!\n손님이 방문했을때 아늑한 느낌이 나도록\n인테리어 진행했고, 인테리어에 큰 돈 쓰기 부담스러우시거나 화사한 샵 원하시는 초보분들 등등 연락주세요 !\n​\n채팅주시면 정확한 위치 안내드리겠습니다.\n​\n방문 원하시면 연락주시고 저랑 시간 맞춰서\n방문하시면 될 것 같아요!\n​\n권리금 500만원(협의가능)\n보증금/월세 1000만/70만,관리비5만(부가세별도)\n엘리베이터,도어락O\n추가 관리비 평균 7-8만원(전기세)\n수도연결 O\n주차 가능\n​\n*입주일은 협의 후 조정가능\n​\n양도 물품\n테이블,의자,신발장,슬리퍼,베드2개,시술의자,이불,베게,소독기,수납장,옷걸이, 쇼파 등\n​\n와이파이+단말기 양도 원하시면 양도 가능\n​\n​\n개인물품은 가져갈거고, 혹시 양도받는 물건중에\n원치않으시는 품목 있으면 치워드릴게요!\n​\n문의는 010.833사.구일23 여기로 주세요!!",
