    "summary": "오즈브로우에서 샵인샵 원장님의 연락을 기다려요~ 오즈원장은 반영구와 아카데미를 운영중입니다. 샵인 원장님은 독립된 공간을 사용하시면 됩니다. ​ ** 기존 원장님 26년 12월까지 계실 예정이라 1월부터 계약 가능해요. ** ​ 입구로 들어오면 공용 대기공간과 세면대, 냉장고가 있고 그",
    "body": "오즈브로우에서 샵인샵 원장님의 연락을 기다려요~\n오즈원장은 반영구와 아카데미를 운영중입니다.\n샵인 원장님은 독립된 공간을 사용하시면 됩니다.\n​\n** 기존 원장님 26년 12월까지 계실 예정이라 1월부터 계약 가능해요. **\n​\n입구로 들어오면 공용 대기공간과 세면대, 냉장고가 있고\n그 안쪽으로 분리된 단독 공간이 있습니다.\n배드 2개 사용 가능한 공간입니다.\n​\n▶ 입구 앞 공간 대기실로 사용가능\n▶ 냉장고 세면대 공용\n▶ 주차 90분 지원 (이후 유료)\n▶ 베드 /웨건 /조명 /수납장 /테이블 /행거 /선풍기 /전기장판 /이불 사용가능\n​\n★ 샵인샵 사업자등록 가능\n★ 보증금 300만 / 월세 40만 / 관리비 5만\n★ 1년 계약\n​\n📍추천해요\n속눈썹 연장 펌\n공방\n왁싱 (오픈 천장 / 샤워실 없음 으로 바디 왁싱은 어려울 것 같아요 )\n네일 (네일은 공간만 제공합니다)\n샵인샵은 보증금과 월세를 최소화 할 수 있기 때문에\n시작하는 원장님들이나, 아이가 있어 파트타임으로 일하고 싶은 분들에게 좋아요.\n​\n혼자만의 공간이 아니기 때문에\n서로에 대한 배려과 예의가 반드시 필요하겠죠.\n오즈브로우는 점심 시간이 따로 없습니다.\n샵인샵 원장님은 편하게 식사하셔도 됩니다.\n( 냄새나는 음식은 안되요. ㅜㅜ)\n출퇴근 편하게 하셔도 됩니다. (오즈원장도 그렇게 합니다 ^^)\n에어컨(히터겸용)은 천장에 설치되어 있고\n시즌마다 가동시간이 달라요.\n​\n오셔서 직접 보시고 결정하시면 좋을 것 같아요★\n​\n010 5909 5596\n오즈브로우 동탄눈썹문신\n경기도 화성시 동탄구 동탄순환대로12길 8 2층 204호\n​",
