    "summary": "※ 선착순 마감 될 수 있습니다 ​ 저희 샵은 한 번 입주하시면 대부분 연장하실 만큼 자리, 동선, 시술 환경에 대한 만족도가 매우 높습니다. ​ 그래서 마감 후에는 공석이 거의 나지 않습니다. ​ 관심 있으시면 지금 바로 연락 주세요 😊 ​ ​ - 위치 ​ 역삼역 6번출구 도보 3–5",
    "body": "※ 선착순 마감 될 수 있습니다\n​\n저희 샵은 한 번 입주하시면 대부분 연장하실 만큼 자리, 동선, 시술 환경에 대한 만족도가 매우 높습니다.\n​\n그래서 마감 후에는 공석이 거의 나지 않습니다.\n​\n관심 있으시면 지금 바로 연락 주세요 😊\n​\n​\n- 위치\n​\n역삼역 6번출구 도보 3–5분, 접근성 최고\n​\n​\n- 조건\n​\n보증금 300 / 월세 55 / 관리비 5\n6개월 단위 계약 (계약금 보증금의 10프로 선불)\n​\n-1인실 프라이버시 가능\n베드 · 조명 · 트레이 완비\n→ 바로 시술 가능\n​\n​\n- 공용공간 자유 이용\n40평 뷰티샵\n파우더룸 · 대기석 · 음료바 · 커피\n직원실 · 냉장고 등 모두 편하게 사용 가능\n​\n​\n- 자율 출퇴근\n​\n예약 있을 때만 오셔서 사용하시면 됩니다\n​\n​\n- 주차\n​\n건물 옆 공영주차장\n30분 2,000원 이용 가능\n​\n​\n사업자는 불가합니다 :)\n​\n​\n-샵인샵 문의 방법\n​\n01036503445 샵인 문의로 밑에 같이 작성 후 문자 주시면 빠른 답변 드리겠습니다\n​\n•성함\n•연락처\n•경력사항(최소 3-4개월 이상)\n•시술 인스타 아이디\n*추가 문의사항 있으신 경우 말씀 해주세요",
