    "body": "안산 상록수역 도보 5분거리 초역세권에 위치한 속눈썹샵입니다.\n속눈썹, ㅂ09 제외 네일, 왁싱, 붙임머리, 메이크업 등 모든 종목 가능합니다.\n같이 윈윈하며 운영하실 원장님 모십니다 ^^\n​\n​\n- 문이 있는 독립적인 방으로 프라이빗한 시술 가능. 방음 좋아요.\n- 답답하지 않은 엄청 널찍한 방.\n- 베드 필요한 종목은 베드 무료 대여 가능\n- 서랍장, 에어컨, 옷걸이, 거울, 트롤리, 조명, 씨씨티비 등 기본 제공\n- 출,퇴근 터치 없음.\n- 주변 병원, 식당 밀집 상권으로 유동 인구가 많음. (신규 유입 꾸준, 당일 예약 많음.)\n- 주변에 뷰티샵 자체가 거의 없음.\n- 경비원 두 분으로 안전한 건물.\n- 무료 주차 + 공영주차장 바로 맞은 편.\n- 상록수역 도보 5분 거리 위치.\n- 샵 주변 인프라 매우 좋음!\n- 40/120 (관리비 포함, 전기세는 일정 금액 초과 시에만 부과.)\n- 부담 적은 6개월 단위 계약.\n​\n​\n빨리 자리 잡고 싶으신 분! 좋은 기회 놓치지 마시고 작은 궁금한 점도 연락주세요~!\n(가벼운 문의는 전화 보다 문자 남겨주세요.)\n​\n공일공-2525-삼영구삼",
