    "body": "안녕하세요. 줄리아뷰티입니다.\n가든파이브에서 8년간 샵을 운영해오면서,\n새롭게 시행되는 문신사법에 따른 영업시설 기준에 맞춰 확장 이전을 계획하게 되어 현재 매장을 임대 내놓습니다.\n​\n* 위치 : 송파 문정동 가든파이브 현대아울렛\n* 임대 조건 : 보증금 2,000만원 / 월세130(협의가능)\n* 자동문, 통창 구조\n*깔끔한 내부 인테리어\n* 기존 집기 및 시설 판매\n​\n* 외부 일정으로 비어 있어서 단기임대 / 베드대여 가능\n* 0103019삼삼팔팔\n​\n뷰티샵은 물론 사무실, 예약제 매장, 쇼룸, 스튜디오 , 피규어샵, 쇼핑몰, 악세서리판매업 , 애견용품등 다양한 용도로 활용하기 좋은 공간입니다.\n​\n​\n* 백화점 고객 화장실, 주차장 편리하게 이용 가능\n* 백화점 주차장 이용 가능\n* 별도의 화장실 청소 및 관리 부담 없음\n* 여름에는 시원한 에어컨, 겨울에는 따뜻한 난방으로\n사계절 쾌적한 환경\n* 고객 방문과 응대가 편리한 백화점 내 입지\n* 같은층 바로옆으로 로운샤브샤브, 애슐리등 식당 및 다양한 매장으로 유동인구 풍부, 최근 대형교회입점\n​\n관심 있으신 분들은 편하게 연락 주세요.\n직접 방문하셔서 매장도 둘러보실 수 있습니다.\n​\n좋은 분과 인연이 닿기를 바랍니다.\n감사합니다.\n​\n​\n​\n​\n이미지\n​\n​\n네일 테이블 카운터. 집기류 판매\n*2000 사이즈 테이블 판매완료\n*발라젤 100종\n*네일 테일블 + 카운터\n*전동베드 블랙 190사이즈\n*갈색 전동베드\n​\n@@@@단기임대 및 대여 별도문의@@@@\n​\n​\n​",
