    "body": "안녕하세요! 김포시 운양동에 위치한 100% 예약제 여성전용 에스테틱 입니다.\n​\n현재 숍 내 여유 공간(독립된 메인 룸)이 있어, 함께 시너지를 내며 즐겁게 일하실 샵인샵 원장님을 모십니다.\n​\n✨ 1. 모집 업종 (기존 업종 중복 제외)\n​\n기존 운영 업종: 피부 관리, 바디 케어 (해당 업종 제외)\n​\n모집 희망 업종: 헤어/두피 케어(헤드스파), 속눈썹(펌/연장), 왁싱 등 뷰티 관련 업종\n(※ 여성전용 숍으로 운영 중이므로, 여성 고객 대상 시술 및 여성 원장님만 입점 가능합니다.)\n​\n​\n💰 2. 임대 조건\n​\n보증금 / 월세: 300만 원 / 50만 원 (관리비 포함)\n계약기간은 6개월 / 이후에 합의후 연장\n​\n🏠 3. 공간 및 시설 안내\n​\n전용 공간: 독립된 룸 1개 단독 사용 (프라이빗한 1:1 시술 가능)\n​\n공용 공간: 깔끔하게 정돈된 대기 공간 및 탕비실 공동 사용\n​\n건물주(임대인)분께 전대차 및 별도 사업자 등록 동의를 이미 다 받아두었습니다.\n사용하실 메인 룸이 독립된 공간이라 원장님 명의로 정식 영업신고와 개인 사업자등록증 발급이 100% 가능합니다.\n​\nPrevious image\nNext image\n​\n📍 4. 매장 위치 및 우대 사항\n위치: 경기도 김포시 운양동 (운양역 인근, 접근성 우수)\n​\n​\n​\n📞 입점 문의 및 방문 상담\n​\n실제 룸 크기와 매장 분위기를 직접 보시는 것을 추천해 드립니다.\n​\n시술 중에는 통화가 어려울 수 있으니, 아래 연락처로 문자로 남겨주시면 확인 즉시 연락드리겠습니다!\n​\n-연락처: 010-4867-2688\n​",
