    "summary": "안녕하세요? 항상 문의가 많은 제 샵의 베드쉐어 공간에 한분 자리 났습니다. 강남 선릉역 역 바로 앞이에요. 대기 중이셨거나 신규로 찾는 분들 등등 연락주세요 ​ 조건 )2인 이상 사용 베드쉐어공간 :사업자등록 불가, 전동베드사용, 카트제공, 부자재(니트릴장갑, 베게시트, 물티슈 외) ",
    "body": "안녕하세요?\n항상 문의가 많은 제 샵의 베드쉐어 공간에\n한분 자리 났습니다. 강남 선릉역 역 바로 앞이에요.\n대기 중이셨거나 신규로 찾는 분들 등등 연락주세요\n​\n조건 )2인 이상 사용 베드쉐어공간\n:사업자등록 불가, 전동베드사용, 카트제공, 부자재(니트릴장갑, 베게시트, 물티슈 외) — 베드쉐어이용시 가능조건 (보증금 200/월세50 /관리비 포함)\n​\n*^시간제는 종목에 따라 비용 다르게 적용합니다.\n(시간당 1.5만~)\n** 사업자등록 원할경우, 상담후 계약 조건 변경 **\n​\n✔️자율출입운영제로 이용시간제한없음\n(베드쉐어시엔 어플이용 날짜와 시간예약해야함)\n✔️전동베드사용, 카트제공, 부자재(니트릴장갑, 베게시트, 물티슈 외) — 베드쉐어이용시 가능조건\n✔️서비스바 이용 (원장님 외 고객님까지 서비스 제공)\n-프리미엄 원두로 내린 아메리카노, 라떼, 마끼아또등\n셀프제조가능\n-각종 티, 스낵, 뷰티영양제(유산균, 콜라겐), 캔디등\n✔️테헤란로 도로변 선릉역 100미터 도보 2분거리로\n주차는 선불 구매시 할인주차 50% 적용 (지하3층~6층까지 빌딩주차)\n자세한 내용 🔎 네이버검색하시거나, 톡 문의주세요.\n카톡문의 📳 celine0522\n카톡문의 후 방문 예약해 주세요~",
