    "body": "안녕하세요 ~!!\n강남구청역(7호선,분당선) 1분거리 아파트상가입니다^^\n​\n불경기에 오픈보다 샵인샵 고민해보세요^^\n​\n제성격은 극은 아니구요. ENTP 성향의 자타공인 둥글둥글 성격의 소유자입니다. 지인들도인정함 ㅎㅎ.\n스케줄공유앱으로 서로스케줄 공유 하면되구요.\n​\n출퇴근 전혀 터치없습니다.\n자유롭게하세요^^\n주말도 사용제한 없구요.\n​\n네일아트 샵인샵 과 베드쉐어 하실 원장님 모집합니다.\n관리비 포함\n네일아트 샵인샵 200/60 (재료완벽구비,몸만오심되여)\n베드쉐어 150/45 ( 본인장비 보관가능)\n​\n현재도 100프로 예약제로 하고있슴.\n​\n우리샵 장점\n1. 7호선과 분당선으로 교통 매우편리함 .\n2. 주변 아파트가 5000세대라 상권이 좋음.\n3. 지역특성상 고객분들 완전 젠틀.\n4. 윈텍전문가구 및 재료사용 가능. 편리해요.\n5. 주인장 성격 둥글(같은 원장님으로 서로존중)\n6. 100% 예약제라 예약있을때만 나와서 일할수있슴\n7. 네이버 예약창 가능.\n8. 주차1시간 무료.\n​\n더궁금하신점은 편하게 문의 주세요~!!\n010-4884-7687\n​",
