    "body": "결혼준비로 지역을 이동하게되어\n아끼는 샵을 양도합니다ㅠㅜㅜㅜㅠㅠ🥹\n​\n📍임대 정보\n13-14평\n* 보증금 : 2,000만원\n* 월세 : 143만원(부가세 포함)\n* 관리비 : 10~30만원대(최대)\n* 권리금 : 300만원\n(라인레일조명+공간분리가벽+커텐+천장에어컨+음료냉장고+수도공사로 세면대 사용 가능 등\n원하시는 집기들 두고갈게요!)\n* 벽에 약간의 오염들은 부분 페인트칠만 하시고\n재료만 들고오셔서 바로 운영 가능합니다.\n* 2027년 2월 입주 가능합니다.\n(더 빨리 원하시는 분은 연락주세요!!)\n​\n🤍 샵 정보 🤍\n​\n* 광교중앙역 인근으로 접근성 우수\n* 오피스텔과 함께 있는 상가라 유동인구가 꾸준함\n* 건물 내 뷰티샵들이 많이 입점해 있어 시너지 효과\n🌟근린생활시설 등록으로 미용업 운영 가능\n* 천장형 냉난방 겸용 에어컨 설치 완료\n* 엘리베이터 있음\n* 공용 화장실 깨끗하게 관리\n* 건물 내 주차 가능\n* 주차 공간이 매우 넓어 고객분들도 편하게 이용 가능\n​\n🤍 내부 구조 🤍\n​\n* 공간이 2개의 룸으로 분리되어 있어\n* 1인샵 운영은 물론 샵인샵도 가능\n* 수강과 시술을 동시에 진행하기에도 좋은 구조입니다.\n* 큰 룸은 베드 3대까지 배치 가능한 넓은 공간입니다.\n* 안쪽 작은룸에 환기가능한 문이 설치되어 있습니다.\n​\n🤍 추천드리는 분 🤍\n​\n* 속눈썹, 왁싱, 피부관리 등 뷰티샵 운영 예정이신 분\n* 수강까지 함께 운영하고 싶으신 분\n* 넓은 공간을 찾고 계신 원장님\n* 프라이빗 운영 가능\n​\n관심 있으신 분들은 편하게 문의 주세요. 자세한 사진과 추가 정보도 보내드리겠습니다. 😊\n​\n카카오톡 오픈채팅을 시작해 보세요.\n링크를 선택하면 카카오톡이 실행됩니다.\n​\n광교중앙역 뷰티샵 양도\nhttps://open.kakao.com/o/sMnSFTBi",
