    "summary": "예전 사진이라 베개가 안보이는데 베개도 있고 이불도 있어요. ​ 베드쉐어 하실분 계신가요 1시간 만원 3시간 2만원 ​ 단,포트폴리오 작업하실분만요 영업매출 X ​ 영업매출하실거면 비율제 직원하실분~ 7:3 가능해요. ​ 비율제 직원하시면 플레이스에 예약창 추가해드릴거고요 편하게 예약받",
    "body": "예전 사진이라 베개가 안보이는데 베개도 있고\n이불도 있어요.\n​\n베드쉐어 하실분 계신가요\n1시간 만원\n3시간 2만원\n​\n단,포트폴리오 작업하실분만요\n영업매출 X\n​\n영업매출하실거면 비율제 직원하실분~\n7:3 가능해요.\n​\n비율제 직원하시면 플레이스에 예약창 추가해드릴거고요\n편하게 예약받으시고 출퇴근 터치 일절없습니다.\n​\n​\n정기적으로 베드쉐어시 스케줄공유어플써서 빈 시간 편하게 보실수있게 하겠습니다\n매번 안물어보실수 있게요!",
