    "body": "📣📣다음 달부터 들어오실 분 구합니다‼️\n​\n위치:다산 선형공원 근처\n월세:보증금 200/55 (관리비 포함)\n​\n✨시간 상관 없이 편하게 이용 가능\n✨휴지 등등 공용이라 편하게 써도 되세요\n✨6개월 단위 계약\n✨사업자 등록 가능합니다✨\n✨세면대 있음\n🅿️주차 3시간 무료\n​\n피부 샵 안에 한 공간을 편하게\n이용 가능합니다!\n​\n공간 밖에 개인 상담 테이블과 단말기\n놓을 공간을 제가 다 준비 해놨어요!\n​\n피부샵 원장님께서 친절하셔서\n에어컨 사용이나 등등 아예\n터치가 없습니다:) 👍\n​\n저는 반영구와 속눈썹펌을 운영했고\n​\n안에 베드 등등 인테리어 소품을 다 제가\n구매해서 꾸몄습니다:)😊\n​\n이대로 양도인수 받고 싶으시다면\n저에게 금액을 지불하고 받으셔도 좋고\n아니면 그냥 방을 비우고 다시 꾸며도 가능하십니다.\n​\n제가 꾸민 상태로 양도 받으신다면\n아마 준비하실건 사업자밖에 없으실 정도로 편하실겁니다!!!😊\n​\n월세를 제외한 내부 인테리어,재료\n양도 금액은 따로 안내드리겠습니다!\n​\n010-8삼11-91오1로 메세지 주세요🤎",
