    "summary": "✔️사업자 가능 ✔️관련 자격증 필수 ✔️최소 계약 단위 : 1년 ​ ​ 📍 왁싱 샵인샵(or피부 가능) •즉시입점가능 •200/50 단독룸. 룸 내 샤워부스 및 수전 있음. •제공집기 등: 샤워부스, 룸 내 수전, 전동베드(온열매트), 시술의자, 디자인의자, PDT, 붙박이싱크서랍장(",
    "body": "✔️사업자 가능\n✔️관련 자격증 필수\n✔️최소 계약 단위 : 1년\n​\n​\n📍 왁싱 샵인샵(or피부 가능)\n•즉시입점가능\n•200/50 단독룸. 룸 내 샤워부스 및 수전 있음.\n•제공집기 등: 샤워부스, 룸 내 수전, 전동베드(온열매트), 시술의자, 디자인의자, PDT, 붙박이싱크서랍장(2.4m), 소독기, 시술조명,뷰티카트 대1, 트롤리1, 행거.\n​\n(*왁싱 경우 겨울 비수기에도 여행수요로 꽤 괜찮은 편 입니다.)\n​\n​\n​\n📍단독룸 샵인샵\n•즉시입점가능\n•120/40 단독룸.\n•입점가능종목: smp,입술반영구(눈썹x),속눈썹펌연장\n•제공집기: 베드(온열매트,침구), 시술의자, 수납장, 행거, 3단트롤리\n​\n​\n​\n📍공통사항\n☑️개인 재료만 가져 오시면 바로 시술 가능한 상태 입니다.\n•총 30평으로 대기공간 넓고, 탕비실, 내부 화장실 구비.\n☑️사업자 가능. 네이버플레이스 셋팅 가능. 사업자 가능한 샵인샵이 흔하지 않습니다. 나중에 이전하실때에도 쌓인 것들이 큰 도움 되실거에요.\n☑️3층/3층 주차불가. 대신 곳곳에 공영주차장이 많습니다. 가게 3분거리 공영있음.\n☑️저희는 뷰티토탈샵 이며 네일, 왁싱 등 여러 원장님들과 함께하고 있습니다. 출퇴근 터치없고 본인 스케줄 따라 근무하시면 됩니다.\n☑️샵 위치는 1호선 의정부역 가장 번잡한 로데오 중앙으로 주변에 신세계백화점, 지하상가, 의정부제일시장 등 번화가에 위치해 있습니다.(1호선 의정부역 앞/경전철 의정부중앙역 도보5분이내) (정확한 주소는 방문하시는 분에 한하여 알려드립니다!)\n☑️24년 봄 인테리어 했기에 깔끔하며 오픈 초기 비용 부담되시는 원장님에게 좋은 기회라고 생각합니다.\n•입점하셨던 원장님들 대부분 오래 계시기도 했고 또 만족해하셨습니다. 각자 사정으로 떠나실때에는 아쉬워하시며 잘지내다가셨습니다.\n•저희 샵 위치가 좋고 시설이 깔끔하여 노력하신만큼 기본이상은 벌어가는 좋은 자리 입니다.\n​\n•더 자세한 사항은 아래 오픈 카톡으로 연락 주시고 저희 가게 오셔서 이야기 나누시면 될것같습니다.\n감사합니다.\n​\n☑️의정부 샵인샵 문의(의정부역로데오)\nhttps://open.kakao.com/o/sMcbjV8g\n​\n​\n(메이크업, 붙임머리 파트는 연락을 많이 주시는데 여건상 어렵습니다.. 죄송합니다)\n​\n​\n​",
