    "summary": "​ ​ 안녕하세요 4년 운영 후 확장 이전으로 샵 내놓습니다 다들 자리 운이 있다고 할 정도로 이곳에서 자리 바로 잡아 매출이 계속 늘어 4년 정도 잘 운영해왔고, 주변 사장님들도 너무 잘 대해주셔서 많이 아쉽지만 같은 뷰티업하시는 원장님이 오셨으면 좋겠습니다. ​ 처음 샵 운영하실 분",
    "body": "​\n​\n안녕하세요\n4년 운영 후 확장 이전으로 샵 내놓습니다\n다들 자리 운이 있다고 할 정도로 이곳에서 자리 바로 잡아 매출이 계속 늘어 4년 정도 잘 운영해왔고,\n주변 사장님들도 너무 잘 대해주셔서 많이 아쉽지만\n같은 뷰티업하시는 원장님이 오셨으면 좋겠습니다.\n​\n처음 샵 운영하실 분들께서 정말 부담없이 사용하기 너무 좋을 공간입니다!\n인테리어 따로 손댈 곳 별로 없고\n몸만 들어오시면 적은 금액으로 바로 운영 가능한 상태에요\n​\n넓게 빠진 17평이라 샵인이나 여러 종목으로 운영하시기도 좋습니다.\n실내 화장실도 넓게 있어 쾌적하고 쓰기 편합니다\n고객님들도 샵이 깨끗하다고 좋아하셨어요!\n실제로 보시는게 훨 깨끗하고 좋아요\n​\n바로 근처 유명 카페, 식당, 지하철역, 버스정류장 있어 접근성도 좋고\n근처 원룸도 많아 지나가며 많이들 방문해주세요\n제일 중요한 주차도 가능해 주차 걱정이 없어 좋습니다!\n그리고 건물 주인분도 터치 일절 없으시고 도움 요청시 너무 잘 도와주세요 :)\n덕분에 저도 4년 잘 있었습니다\n​\n저는 여기에서 자리 잡고 확장 이전까지해요\n주변 상가 사장님들께 물어보셔도 됩니다\n원룸도 많아 타겟 잘 잡으면 저처럼 자리 금방 잡으실거에요\n찾아보시면 이 월세에 주차 되는곳, 상가 주인이 괜찮은 곳 진짜 잘 없어요\n​\n보증금: 1000/ 월세 45 ( 협의 가능 )\n권리금 : 100만원\n​\n010 48사삼 1구공1 여기로 문자남겨주세요!\n​\n​",
