    "body": "[일산] 지축역 인근. 삼송 원흥 구파발 원장님 모셔요.\n📍지축역 인근\n​\n▶️ 계약 기간 (1년 / 3•6•9개월 가능)\n협의가능 , 베드 쉐어 경우 하루 6만원\n▶️ 보증금 /월세 : 30만원 / 38만원 (관리비포함)\n​\n▶️ 사용 공간 :\n가벽 단독 룸 사용 , 대기공간 사용, 수도시설 있음\n▶️ 사용 용도 : 피부미용,속눈썹 펌 ,페이스왁싱\n▶️문의 : 010-776오-204구 (문자 문의)\n뷰앤잡에서 보고 문의 주신다고 말씀해주세요.\n(▫️사업자는 불가 합니다 )\n​\n혼자 창업 시작하기 부담스러우셨던 분들 함께 하셨으면 좋겠습니다.\n저는 평일 운영 시간이 짧아 ,\n오후 부터는 편히 사용 하시기 좋으 실 거에요. ^^",
