    "summary": "🌿 건대입구역 뷰티샵 베드쉐어 원장님 모집합니다 🌿 ​ 안녕하세요 :) 서울 건대입구역 인근에서 함께 성장해 나갈 뷰티 원장님을 모집합니다. ​ 📍 위치 • 건대입구역 6번 출구 도보 2분 • 2호선 · 7호선 더블 역세권 • 건국대학교 및 건대 상권 인접 • 대중교통 이용이 편리한 위",
    "body": "🌿 건대입구역 뷰티샵 베드쉐어 원장님 모집합니다 🌿\n​\n안녕하세요 :)\n서울 건대입구역 인근에서 함께 성장해 나갈\n뷰티 원장님을 모집합니다.\n​\n📍 위치\n• 건대입구역 6번 출구 도보 2분\n• 2호선 · 7호선 더블 역세권\n• 건국대학교 및 건대 상권 인접\n• 대중교통 이용이 편리한 위치\n​\n🤍공간\n• 따뜻하고 깔끔한 베이지톤 인테리어\n• 편안한 분위기의 뷰티 작업 공간\n• 고객님을 맞이하기 좋은 감성적인 로비\n• 3인 2베드 / 단독베드 형태로 사용 (열선베드구비)\n• 대부분 신생 원장님들이 함께하고 있어 실제로는 혼자 사용하는 시간이 많은 편입니다.\n​\n📌 모집 분야\n• ㅂㅇㄱ\n• 속눈썹펌\n• 속눈썹연장\n• SMP\n​\n🧺 편의를 위한 기본 시설 및 소모품 제공\n• 개인 트롤리 제공\n• 물 제공\n• 냉난방기 / 선풍기 / 난로 구비\n• 화장솜 / 베개커버 / 물티슈 / 휴지 등\n고급형 일회용품 제공\n​\n💰 이용 조건\n[베드쉐어]\n• 보증금 31만원 / 월세 31만원 (추가 비용 없음)\n[샵인샵] - 단독베드 사용\n• 보증금 40만원 / 월세 40만원\n• 한 달 단위 계약 가능\n• 출퇴근 시간 자유\n• 개인 트롤리 및 사용하신 베드만 깔끔하게 정리해주시면 됩니다.\n• 사업자 / 전대차 불가\n​\n🌱 이런 원장님께 추천드려요\n• 모델 작업을 하며 샵을 알아보고 계신 분\n• 초기 창업 비용이 부담스러우신 분\n• 큰 비용 부담 없이 내 공간에서 시작해보고 싶으신 분\n• 자유로운 분위기에서 편하게 작업하고 싶으신 분\n​\n​\n사진만 보고 결정하기보다는\n직접 샵에 방문하셔서 공간을 둘러보신 후 결정하시는 것을 추천드려요 :)\n​\n궁금하신 점이나 방문 문의는\n📞 010-2074-0652\n편하게 연락 주세요 🤍\n​\n좋은 인연으로 함께할 원장님을 기다리고 있습니다☺️\n​\n​\n​\n​\n​\n​\n​",
