    "summary": "📍 안산 중앙동 네일 샵인샵 원장님 모셔요 ❤️ ​ ✨ 초역세권! 중앙역 도보 5분! 안산 중앙동 메인 상권에 위치한 샵인샵입니다. 확장이전 하면서 전체 새로 인테리어 한 공간이에요❣️ 역과 가까워 고객님들께 위치 안내하기도 편하고, 접근성까지 좋은 자리예요☺️ ​ 😳 안산에서 리클라이",
    "body": "📍 안산 중앙동 네일 샵인샵 원장님 모셔요 ❤️\n​\n✨ 초역세권! 중앙역 도보 5분!\n안산 중앙동 메인 상권에 위치한 샵인샵입니다.\n확장이전 하면서 전체 새로 인테리어 한 공간이에요❣️\n역과 가까워 고객님들께 위치 안내하기도 편하고,\n접근성까지 좋은 자리예요☺️\n​\n😳 안산에서 리클라이너 를 갖춘 네일 시술 공간!\n샵인샵인데 리클라이너 네일샵이 가능하다고..!?\n일반적인 네일샵과 차별화된 시술 환경!\n고객님들께 더욱 편안하고 특별한 시술 경험을 제공할수있습니다😌\n리클라이너를 활용한 차별화된 공간으로\nSNS 홍보 및 매장만의 경쟁력을 갖추기에도 좋답니다❤️\n​\n⏰ 24시간 자유롭게 이용 가능!!\n샵인샵인데 출퇴근 터치…? NO!!!!\n출퇴근 시간 제한 없음\n24시간 자유롭게 사용 가능\n서로 예약이 있을 때만 매장 방문\n불필요한 간섭 없이 본인 예약에 맞춰 자유롭게 이용하시면 됩니다🫶🏻\n​\n✨ 모든 집기 새 제품! 첫 사용하실 분을 기다려요.\n현재 준비된 집기 모두 새 제품으로, 첫 사용자를 모십니다😎\n-리클라이너 소파\n-전동 시술 테이블\n-페디 단상\n-시술 의자\n-페디 시술의자\n-수납 선반 등\n매장 전체적으로 밝고 깔끔하게 꾸며놓았고,\n예쁜 포토존까지 마련되어 있어요✨\n​\n☕ 공용 편의시설도 모두 구비!\n커피머신, 냉장고, 카운터, 정수기, 세면대 등 전체 사용 가능\n개인적으로 사용하시는 재료나 집기만 가져오시면 돼요☺️\n​\n🙋🏻‍♀️ 이런 분들께 추천드려요!\n•이제 막 창업을 시작하려는데 높은 월세가 부담스러우신 분\n•리클라이너 네일샵을 꿈꾸셨던 분\n•연습 공간이나 모델 시술 공간이 필요하신 분\n•저렴하면서도 역과 가까운 작업 공간을 찾으시는 분\n•출퇴근 간섭 없이 자유롭게 일하고 싶으신 분\n•초기 시설 비용 부담 없이 바로 시작하고 싶으신 분\n​\n💰 입점 조건\n보증금 200만 원\n월세 40만 원\n관리비 별도\n기본 계약 1년\n6개월 단기 계약 가능 (월세 +3만 원)\n계약 연장 여부 협의 가능🥰\n사업자 및 영업신고 가능\n​\n※ 관리비는 매달 실제 발생하는 건물 관리비를 기준으로\n공간 면적 비율에 따라 분담합니다.\n네일룸 관리비 분담 비율: 31.18%\n예시) 전체 관리비가 20만 원일 경우\n관리비 총 20만 원 × 31.18% &#x3D; 62,360원\n​\n​\n🏢 위치 및 기타 안내\n안산 중앙역 도보 5분 (초역세권!)\n중앙동 메인 상권\n엘리베이터 있음\n매장 내 주차 불가 (인근 공용주차장 이용 가능)\n​\n저도",
