    "ts": 1794211475057,
    "summary": "​ (제가 사진을 잘 못찍어서 ㅠㅠ 실물이 훨씬 예쁜 샵입니다.) ​ ​ 저희 샵은 붙임머리를 전문으로 하는 샵이고 대표원장이 사업장이 두곳이기때문에 샵에 일주일에 2회정도 출근합니다. ​ 현재 일하는 직원은 대표원장 및 점장님 두 분이 계시나 해당 예약시간에만 시술하고 바로 퇴근하는 ",
    "body": "​\n(제가 사진을 잘 못찍어서 ㅠㅠ 실물이 훨씬 예쁜 샵입니다.)\n​\n​\n저희 샵은 붙임머리를 전문으로 하는 샵이고 대표원장이 사업장이 두곳이기때문에 샵에 일주일에 2회정도 출근합니다.\n​\n현재 일하는 직원은 대표원장 및 점장님 두 분이 계시나 해당 예약시간에만 시술하고 바로 퇴근하는 시스템으로\n자주 마주칠일이 없어 사람사이 불필요한 친목등이 불편하신 원장님 굉장히 편하게 근무하실 수 있습니다!\n​\n*또한 대표원장/점장님 각자 일하는 방이 나뉘어져 있어 일하면서 동선이 겹칠일이 없게 인테리어 해놨습니다!\n동시에 시술예약이 잡혀도 일반 미용실에 샵인으로 있는 느낌이 아닐거예요~\n​\n일하시는 분들이 다들 성향이 좋으셔서 근무하기 좋으실거예요 :)\n건물 내 화장실이 새로공사해서 깨끗하고 좋습니다.\n​\n​\n출퇴근 전혀 터치 없음.\n월세만 안밀리고 잘 내시면됨!\n​\n​\n​\n1.모집 분야\n​\n*홀 - 네일파트\n- 네일테이블 2개 / 페디좌석/벽선반까지 준비되어 있는 넓은 홀\n- 사업자 등록 불가능\n- 보증금/월세(관리비 포함)\n1) 3개월 : 보증금 150만원, 월세 50만원\n2) 6개월 : 보증금 300만원, 월세 50만원\n1년이상 하실경우 보증금,월세 조율 가능\n(관리비 없음)\n​\n​\n​\n2.제공사항\n​\n-음료 및 스낵바 본인 및 손님제공 편하게~\n-천장형 에어컨/히터\n​\n​\n​\n3.이런분이 오셨으면 좋겠습니다!\n​\n-본인 시술공간 깔끔하게 청소하실 분\n-매장 내 흡연금지\n-개인 고객으로 인한 불편사항 및 컴플레인 책임 가능하신 분\n-공용공간을 함께 사용하는 만큼 성격이 까칠하고 예민하신분은 정중히 사양합니다.\n​\n​\n4.입점 문의 양식\n​\n-성함과 성별\n-대략적인 나이 (예) 20대 후반\n-연락처\n-입점 희망날짜\n​\n​\n5.지원방법\n010-8팔9구-8오4삼으로 문자나 전화 부탁드립니다!\n(시술중 통화가 힘들어서 문자남겨주시면 좋겠습니다)\n​\n​",
