    "body": "안녕하세요 :)\n서울 건대입구역에서 함께 성장해 갈 뷰티 원장님 모십니다 !\n​\n위치 : 서울 건대입구역 도보 2분내\n건대입구역 도보 2분내 위치 / 1층이고 샵 도보 10초내 공원과 공영주차장 有\n건대입구 서울 메인 호선인 2호선과 7호선을 동시에 물고있어 손님이 찾아오기에 용이\n건국대학교 대학생 등 유동인구 多\n​\n금액 : 보증금 33 / 월세 33 (추가비용X)\n넓은 단독룸(4평) / 3인 2배드\n나머지 두분이 신생원장님이셔서 거의 혼자 사용 (단한번도 작업겹치거나 불편했던적 X)\n한달 단위 계약 가능 / 출퇴근 자유 / 샵청소 등 일절터치X / 사업자불가\n​\n추가정보\n내부 대리석 화장실 / 트렌디한 인테리어 / 단독룸사용\n개인수납장 트롤리 제공, 커피얼음정수기, 냉난방기, 공청기, 제습기, 선풍기, 난로 등 구비\n화장솜, 베개커버, 물티슈 등 모든 일회용품 고급형으로 제공\n​\n샵위치, 금액, 내부시설 등 서울에서 여기보다 좋은 조건의 샵이 있을까싶어요 !\n샵 방문해서 직접 눈으로 보시는걸 추천드립니다\n기타 자세한 문의는 010-4201-2340 연락 부탁드립니다\n감사합니다 :)\n​",
