    "body": "​\n안녕하세요 12월부터 저와 함께 쉐어하면서 사용하실 원장님 모십니다!\n​\n⋅ 스케줄(공유)베드 50/25 (3개월 or 6개월 단위 계약/사업자등록 불가)\n⋅ 속눈썹, 페이스왁싱, ㅂㅇㄱ 베드대여 필요한 업종 (샤워불가)\n⋅ 사용하실 재료/웨건은 직접 가져오셔야 합니다\n⋅ 별도 관리비 없습니다\n⋅ 깨끗하게, 매너있게 사용하실 분 → 사용 후에는 베드•선반 정리(바닥에 떨어진 색소나 래쉬 등), 사용하신 물건만 깔끔하게 정리해주시면 됩니다\n⋅ 흡연자 X\n​\n​\n** 사용 가능 시간:\n평일: 오전 9시 ~ 오후 6시까지\n주말 및 공휴일: 오후 7시 이후 (제 휴무일엔 자유롭게 이용 가능하세요!)\n​\n** 제가 현재 투잡하고 있어 평일 낮에 사용 안하는 시간대가 많아 혼자 편하게 이용하실 수 있고, 월 1~2회 정도 평일 낮시간 사용할 수 있습니다.\n(대부분 평일 19~22시, 주말 및 공휴일 10~18시 사용합니다)\n​\n​\n월세 부담없이 샵 오픈 전으로 모델 포트폴리오 작업 및 모델 시술 필요하신 분께 적합할 것 같습니다!\n( 사업자 등록 및 사업자 명의 영업은 불가합니다 )\n​\n​\n아래 문의 양식과 함께 오픈채팅으로 문의주세요 :)\n성함 / 나이 / 연락처 / 종목 / 자격증 여부\n​\nhttps://open.kakao.com/o/s9adcJJi\n​\n​",
