    "summary": "📍 홍대 샵 양도합니다 ​ 보증금 1,000 / 월세 130만원 (부가세 별도) 청소비 2만원 권리금 3,000만원 ​ ​ 6개월 된 신축급 매장 창문까지 교체한 깔끔한 매장으로 현재 상태 그대로 바로 영업 가능하며, 따로 손볼 곳 없이 깔끔하게 관리되어 있습니다. ​ 시술실 / 수강실",
    "body": "📍 홍대 샵 양도합니다\n​\n보증금 1,000 / 월세 130만원 (부가세 별도)\n청소비 2만원\n권리금 3,000만원\n​\n​\n6개월 된 신축급 매장\n창문까지 교체한 깔끔한 매장으로\n현재 상태 그대로 바로 영업 가능하며,\n따로 손볼 곳 없이 깔끔하게 관리되어 있습니다.\n​\n시술실 / 수강실 / 탕비실 / 인포 / 대기공간\n전체 올인테리어로 갖춰져 있어요.\n​\n바닥 보일러까지 설치되어 있어\n겨울에도 따뜻하게 사용할 수 있습니다.\n​\n📍 홍대입구역 3번 출구 도보 4분\n앞이 확 트여 있어 유동인구와 워킹 손님도 많은 위치입니다.\n​\n서울에서 이 정도 역세권 위치 + 월세 + 공간 컨디션을 갖춘 매장을 찾으신다면 좋은 조건이라고 생각합니다.\n​\n요즘 자재비와 인테리어 비용이 많이 올라\n현재와 같은 퀄리티로 새로 인테리어를 하려면\n3,000만원 이상의 비용이 들어갈 수 있는 매장입니다.\n​\n속눈썹 / 피부 / 네일 등 미용업종 가능하며\n건물주님 터치도 일절 없습니다.\n​\n1층 주차자리 있으며\n모두의주차장 앱을 통해 이용 가능합니다.\n​\n현재 수강과 세미나 진행으로\n더 넓은 공간으로 확장 이전하게 되어\n6개월 만에 확정 이전으로 양도합니다.\n​\n※ 개인적으로 사용할 집기 제외\n배드 1개, 가전, 수강실 테이블은 가져갑니다.\n​\n관심 있으신 분은 편하게 문의 주세요.\n​\n💬 홍대 샵 매매 문의\nhttps://open.kakao.com/o/sZKzpx\n​",
