    "body": "안녕하세요 개봉동에 위치한 토탈샵 스파블룸입니다 .\n(단독룸, 사업자 등록 가능)\n​\n왁싱, 속눈썹, 네일, 붙임머리 입점이 되어있어요.\n​\n피부/ 전신/ ㅂㅇㄱ/ smp / 두피 / 체형 기타 등등 모두 가능합니다.\n​\n50평 규모, 지하1층, 룸7 , 탕비실, 준비실, 화장실(남/여), 세탁실, 환기시설 등\n모든 시설 최상급으로 되어있습니다.\n​\n단독룸 보증금 200 / 월세 47만원 (관리비 포함)\n(11월18일부터 가능)\n​\n세탁실 , 손님 대기실 등 시설 공동으로 사용가능하세요\n(전기,수도,인터넷,청소비용 등등 모두 포함)\n​\n출퇴근 자유롭게 가능하시며, 터치없이 자유롭게 운영 가능하세요\n자리 잡으실 수 있도록 최대한 도와드려요.\n​\n기타 궁금하신 점 있으시면 언제든 문자/전화주세요\n010 8272 145삼\n​\n​\n방문 원하시면 미리 연락부탁드려요\n감사합니다\n​\n​",
