    "summary": "매장 기본정보 - 군자역 (5,7호선) 도보 3분거리 위치 - 오피스텔 건물 2층 상가 - 18평 / 룸 4개로 만들어져있어서 직원두거나, 샵인 가능 (전대차x) - 외부 화장실 - 근린생활시설 - 현재업종 : 뷰티샵 (속눈썹, 합법화될 예정인 종목, 수강도 진행했어요!) - 입주가능일",
    "body": "매장 기본정보\n- 군자역 (5,7호선) 도보 3분거리 위치\n- 오피스텔 건물 2층 상가\n- 18평 / 룸 4개로 만들어져있어서 직원두거나, 샵인 가능 (전대차x)\n- 외부 화장실\n- 근린생활시설\n- 현재업종 : 뷰티샵 (속눈썹, 합법화될 예정인 종목, 수강도 진행했어요!)\n- 입주가능일 : 27년 1월말~2월초\n: 현재 샵인 원장님들은 2월초까지 계약되어있으며,\n인수하실 원장님께서 샵인까지 이어받는다고 하시면 현재 계시는분들은 계약연장 희망하십니다.\n샵인분들도 같이 매장청소도 해주시고.. 너무 좋으신분들만 계세요 ㅠㅠ!\n​\n- 간판 설치가능/ 대로변 아주잘보임 (현재 간판 설치안되있어용!)\n: 간판없지만 위치가 워낙 좋다보니 네이버 플레이스보고 예약률 높았습니다!\n​\n​\n임대조건\n- 보증금 : 2,000만원\n- 월세 : 130만원 + 13만원(부가세) 총 :143만원\n- 관리비 : 보통 30만원 후반 / 전기세는 10만원대\n- 권리금 : 1,500 만원 - 1,300만원으로 인하합니다. 매너있게 거래하실분들만 연락주세요.\n​\n- 기계식주차 가능\n: 1시간 무료, 이후 시간당 3천원 부과\n- 샵주, 샵인 모두 주차 가능 (1대 4만원, 2대 6만원 비용 달라짐)\n​\n​\n​\n매장 장점\n​\n- 뷰티샵을 운영하시거나, 샵인 들여서 내 샵 운영하시려는분들께 적합!\n: 샵인분들 월세로 샵 전체적인 월세나 관리비 납부해왔음\n​\n- 접근성 좋은 역세권으로 손님 찾아오시기 좋음 (지하철역 2개 환승구간으로 접근성 매우용이)\n​\n- 천장형 냉난방기로 매년 청소해왔고 3년정도는 청소안해도된다고 점검받음 (개별냉난방)\n​\n- 3년간 꾸준히 안정적인 매출 유지해온 좋은 목\n​\n- 샵이 워낙 깔끔하고 위치가 좋아서 샵인 한번도 안구해진적 없음\n​\n- 모든 집기 두고갑니다.\n바로 들어오셔서 영업 가능하시고, 샵인분들이 있기 때문에 초보분들이 들어오셔도\n월세걱정없이 벌어가실 수 있어요!\n​\n- 블루투스, 담요, 노트북, 단말기는 챙겨갑니다~\n​\n​\n정말 놓치기싫은 샵인데..\n둘째 출산 및 육아로 인해 어쩔수 없이 내놓아요..\n오시면 바로 계약하실만큼 샵 너무 구조도 잘뺐고 예뻐요!\n(사진보다 실제로 보시는게 훨씬 넓습니다.)\n​\n실제로 보시는걸 더 추천드립니다~\n관심있으신분들은 편하게 연락주세요!\n​\n010- 6623-7625 입니다.\n​\n시술, 수업중엔 통화 어려우므로 문자주세요~\n​\n​\n[대기공간]\n대기공간\n룸 1\n룸 2\n​\n룸 3\n룸",
