    "summary": "안녕하세요 :) 이츠제이 청주점에서 네일 공간을 운영하실 원장님을 찾고 있어요. ​ 저희는 청주 상당구 중고개로 250에 있는 토탈뷰티샵이에요. 3층 단독 건물에서 헤어, 피부관리, 바디관리, 반영구를 운영하고 있고, 네일은 별도로 마련된 공간에서 운영하실 수 있어요. ​ 네일 공간은 ",
    "body": "안녕하세요 :) 이츠제이 청주점에서 네일 공간을 운영하실 원장님을 찾고 있어요.\n​\n저희는 청주 상당구 중고개로 250에 있는 토탈뷰티샵이에요. 3층 단독 건물에서 헤어, 피부관리, 바디관리, 반영구를 운영하고 있고, 네일은 별도로 마련된 공간에서 운영하실 수 있어요.\n​\n네일 공간은 이렇게 준비돼 있어요.\n​\n- 네일 전용 공간과 인테리어가 갖춰져 있어요.\n- 네일 가구는 저희가 준비해 드려요. 평소 쓰시는 개인 집기와 시술 재료를 가져오시면 운영을 시작하실 수 있어요.\n- 건물 앞뒤에 전용 주차 공간이 있어 원장님과 고객님 모두 이용하실 수 있어요.\n​\n처음 샵을 열려고 알아보는 중인데 인테리어나 가구 비용이 부담되셨던 분, 또는 지금 샵을 운영 중이지만 다른 뷰티 업종이 함께 있는 공간으로 옮겨보고 싶으셨던 분이라면 편하게 연락 주세요.\n​\n경력 연수는 크게 따지지 않아요. 혼자 시술하고 고객 응대까지 하실 수 있다면, 첫 샵 운영을 준비하시는 분도 환영합니다 :)\n​\n수익은 비율제로 정산하고, 세부 조건은 상담 때 안내드려요. 몇 가지 운영 방안을 말씀드릴 테니 들어보시고 본인에게 맞는 방향을 편하게 상의하시면 됩니다.\n​\n아직 결정 전이셔도 네일 공간만 먼저 보고 가셔도 괜찮아요.\n다른 뷰티 업종으로 입점을 생각 중이신 원장님도 편하게 문의 주세요.\n​\n이츠제이 청주점\n문의\n대표원장 010-8727-6910\nPrevious image\nNext image\n​",
