    "body": "✨ 샵인샵 입점 원장님 모집\n​\n​\n안녕하세요 :)\n인천 논현동 소래포구에 위치한 속눈썹전문샵입니다.\n​\n이번에 확장 이전하면서 새롭게 인테리어한 깔끔하고 쾌적한 공간에서 함께하실 샵인샵 선생님을 모집합니다.\n​\n새 건물이라 주변에 아직 공실이 많은 편이지만, 현재 네이버 플레이스 지역 1위를 기록하고 있으며 꾸준히 예약과 고객 유입이 늘어나고 있는 매장입니다.\n​\n혼자서 처음 시작하시거나 기존 고객을 보유하고 계신 원장님 모두 편하게 문의 주세요!\n​\n🏠 공간 안내\n​\n* 확장 이전한 새 건물, 깔끔한 신규 인테리어\n* 독립된 1인 시술 공간\n* 시술 베드 1개 제공\n* 트롤리 1개 제공\n* 의자 1개 제공\n* 쾌적한 대기 공간 및 공용 카운터\n* 소파, 정수기, 냉장고 구비\n* 고객 세안이 가능한 세면대 구비\n* 깨끗한 공용 화장실\n* 건물 주차 가능 및 주차 공간 여유\n​\n💼 입점 조건\n​\n* 보증금 100만 원\n* 월세 25만 원 (관리비 n분의1)\n* 사업자 등록 가능\n* 전대차 계약 가능\n* 간판 부착 가능 (퇴실 시 원상복구 및 철거 필수)\n​\n💅 입점 가능 종목\n​\n속눈썹 시술을 제외한 모든 뷰티 관련 종목 가능합니다.\n​\n예시)\n​\n* 네일\n* 피부관리\n* 왁싱\n* 마사지\n* 헤어\n* 메이크업\n* ㅂㅇㄱ 등\n​\n좋은 인연으로 오래 함께하실 분이라면 언제든 편하게 연락 주세요 :)\n*방문 하기로 하시고 약속 시간 안지키실 분들은 연락 사양하겠습니다.\n​\n📩 문의는 01082326240 문자로 문의주세요!\n​",
