    "summary": "수유역 1번 출구에서 도보 약 5분 거리에 위치한 1층 샵입니다. 역세권 입지에 비해 고정비 부담도 적어 1인샵을 시작하시려는 원장님께 추천드립니다 :) ​ 역과 가까워 접근성이 좋고, 맞은편은 번화한 상권이지만 매장 주변은 주택가라 조용하고 쾌적한 환경입니다. 채광이 좋아 낮에도 내부",
    "body": "수유역 1번 출구에서 도보 약 5분 거리에 위치한 1층 샵입니다.\n역세권 입지에 비해 고정비 부담도 적어 1인샵을 시작하시려는 원장님께 추천드립니다 :)\n​\n역과 가까워 접근성이 좋고, 맞은편은 번화한 상권이지만 매장 주변은 주택가라 조용하고 쾌적한 환경입니다.\n채광이 좋아 낮에도 내부가 밝으며, 약 3년간 직접 운영하면서 인테리어와 시설을 깔끔하게 관리해 왔습니다.\n​\n예약제 1인샵으로 독립적이고 프라이빗한 운영이 가능하며,\n20~30대부터 40~60대까지 다양한 연령층의 고객님들이 방문하고 계십니다.\n​\n오랜 기간 운영하면서 고객 응대에 큰 어려움 없이 편안하게 영업해 온 매장입니다.\n​\n​\nPrevious image\nNext image\n​\n​\n📍 매장 기본 정보\n- 위치 : 수유역 1번 출구 도보 5분 거리\n- 평수/층 : 6.4평 / 1층\n- 외부 화장실\n- 근린생활시설\n- 현재 업종 : 뷰티샵 / 1인샵 / 예약제 운영\n- 입주 가능일 : 협의 가능\n- 간판 설치 가능\n* 간판 없이 운영했지만 지나가다 배너를 보고 문의주시는 분들도 많습니다.\n​\n​\n💰 임대 조건\n- 보증금 : 500만원\n- 월세 : 50만원\n- 관리비 : 없음\n* 임대인분이 간이과세자라 부가세 없음\n- 권리금 : 1,000만원\n​\n​\n💡관리비 및 공과금\n- 수도세 : 4,000원~9,000원대 / 2개월에 한 번\n(지하 상가와 반반 부담)\n- 전기세 : 봄·가을 2~3만원대 / 여름·겨울 5만원대\n(가장 많이 나왔을 때도 7만원 정도였으며, 1회 있었습니다.)\n​\n🚘 주차 무료, 상가 앞 1대 주차 가능\n​\n​\n🏠 매장 장점\n✔ 수유역 1번 출구 도보 5분, 접근성 좋음\n✔ 1층 매장 + 좋은 채광\n✔ 역세권으로 유동인구가 많은 편\n✔ 건너편은 번화가, 매장 쪽은 주택가라 조용하고 한적한 분위기\n✔ 20~30대 고객층이 주를 이루는 상권\n✔ 약 3년간 운영하며 큰 문제 없이 안정적으로 운영\n✔ 임대인분이 친절하시고 소통이 원활해 편하게 운영 가능\n✔ 냉·난방기 2024년 하반기 교체\n✔ 간판 설치 가능\n✔ 상가 앞 주차 1대 가능\n​\n​\n📹 시설 및 비품\n- 내부 CCTV 2개\n- 외부 CCTV 1개\n- SKT 인터넷 사용 중\n- 냉·난방기 / 발 난로\n- 실외 철제 배너 거치대\n- 레일 조명\n- 피부 평베드 1개 (얼굴 홈 있음) + 의자\n- 상담 테이블 의자 2개\n- 냉장고\n- 트롤리\n- 청소기\n- 휴대폰 거치대 (시술 촬영용)\n",
