    "body": "안녕하세요 : )\n이사문제로 금천구 시흥사거리에 있는 1인 속눈썹샵 양도 합니다 !\n1. 매장 정보\n- 위치 : 서울 금천구 시흥사거리 도보5분(금천구청역근처)\n- 평수/층 : 8평 / 1층\n- 내부 화장실\n- 근린생활시설\n- 현재 업종 : 뷰티샵 / 1인샵 / 예약제 운영\n- 입주 가능일 : 협의 가능\n​\n2. 임대 조건\n- 보증금 : 1000만원\n- 월세 : 60만원 / 세금포함 66만원\n- 관리비 : 월 2만원\n- 권리금 : 200만원 (고객정보 미포함)\n모든 물품 정리시 100만원/필요한 물품만 협의가능\n3. 주차(1대 고정)\n- 주차 무료, 상가 앞, 낮시간대는 건물주자창도 이용가능\n​\n5. 매장 설명\n✔ 시흥사거리 먹자골목 도보 5분, 접근성 좋음\n✔ 광명소하, 안양석수도 가까워서 많이 오세요\n✔ 한블록 안쪽은 번화가, 샵은 안쪽이라 소음없이 조용함\n✔ 20~30대 고객층이 주를 이루는나, 40-50대 고객도 많은 편\n✔ 임대인분이 친절하시고 소통이 원활해 편하게 운영 가능\n​\n6. 시설 및 비품\n- KT 인터넷 사용 중\n- 벽걸이에어컨(바닥난방)\n- 실외 철제 배너 거치대 주차금지 표지판\n- 조명 스탠드조명\n- 테이블 보조테이블\n- 안내데스크\n- 토스 터널 단말기\n- 청소기\n- 홈캠(새것)\n- 세면대 수전 거울\n- 커튼\n- 행거\n- 실내화거치대\n- 유팡 소독기\n- 액자 큰거 2개\n- 공기청정기\n- 냉장고\n- 싱크대 상.하부장(수납걱정 없음)\n- 전신거울\n- 2인 쇼파\n- 기타 소모품 포함\n​\n트롤리,시술조명,베드,가모 만 있으시면 바로 영업가능!\n원하시는 물품만 조정 가능합니다\n​\n관심 있으신 분들은 편하게 연락 주십시오.\n궁금하신 부분은 최대한 자세히 안내드리겠습니다 :)\n​\n시술 중에는 통화가 어려워, 오픈채팅방으로 문의주시면 감사하겠습니다.\nhttps://open.kakao.com/o/s8Qike0d",
