    "ts": 1793587749500,
    "summary": "더블역세권 강남 양재 샵인샵 원장님 모셔요 ** 글이 아직 있다면 구인중입니다!! 구인되면 구인완료라고 수정할게요** ​ 안녕하세요 붙임머리, 퍼스널컬러, 속눈썹 연장 펌, 반영구 샵인샵 원장님 모십니다. 고객 안받고 연습도 가능하구요. ​ 서로 같이 윈윈하는게 상생에 도움되니 단골도 ",
    "body": "더블역세권 강남 양재 샵인샵 원장님 모셔요\n** 글이 아직 있다면 구인중입니다!! 구인되면 구인완료라고 수정할게요**\n​\n안녕하세요 붙임머리, 퍼스널컬러, 속눈썹 연장 펌, 반영구 샵인샵 원장님 모십니다.\n고객 안받고 연습도 가능하구요.\n​\n서로 같이 윈윈하는게 상생에 도움되니 단골도 많아서 손님 밀어드릴 수 있습니다.\n유동인구가 많은 상가라서 요즘같은 시대에 워크인이 꽤 많습니다.\n​\n샵 위치는 강남역 양재역 더블역세권 가능한 상가입니다.\n강남역이 조금더 가까워요.\n버스도 굉장히 많구요.\n상권이 너무 좋습니다.\n​\n오피스, 대단지아파트, 주택가 등 고객층 다양합니다.\n무료로 손님 주차 가능합니다.\n​\n경대, 베드, 트롤리, 조명, 시술의자 등 필요한 기본 가구 준비되어있습니다.\n재료만 가져오세요.\n​\n출퇴근 자유롭게 하셔두 되고 터치 아예 없습니다. 완전 노터치!!!!!\n24시간 열려있는 건물이라 일하시는데 시간제약도 없습니다.\n​\n단독룸은 아니지만 다른자리랑 구역이 나눠져 있어서 편하실거에요. 원하시면 파티션 치셔두 됩니다.\n​\n기본 6개월 계약이며, 전대차 어렵지만 네이버 플레이스 되어있어서 네이버 예약 원하시면 받으실 수 있게 열어드립니다.\n(한달단위 베드쉐어도 가능 / 월세 다릅니다.)\n​\n제가 강의도 나가고 해외출장도 있어서 샵 비우는 일이 많습니다. 애초에 이것저것 신경쓰는 스타일이 아니라서 편하게 매출하실 수 있어요. 오시는 원장님들마다 대부분 2년씩은 계시면서 오픈해나가셨어요.\n​\n- 샵인샵\n100 / 55~60 (관리비 포함 금액, 추가비용 일절 없음)\n처음 2개월은 자리 잡는데 도움되시라고 월세 55 해드려요. 3개월차부터 60 입니다.\n*두가지 종목시 월세 ↑별도 문의주세요\n​\n- 한달단위 베드쉐어는 월 70 입니다.\n​\n문의 010-구일41-팔육40\n​\n장사하는 곳은 기운이 중요한거 아시죠 ^^\n그동안 함께했던 샵인 원장님들 매달 천만원 이상 잘되신 분들이 많아요\n저도 신규 최고매출을 갱신했을만큼 기운이 너무 좋은 곳이에요.\n좋은 분 오셔서 함께했음 좋겠습니다!\n작업 중엔 통화가 어려우니 문자 부탁드려요 :)\n​\n베드 쓰시는 원장님은 경대 빼고 베드로 바꿔서 이용가능합니다",
