    "body": "​\n[용인 보정동] 17년 운영! 약 60평 복합뷰티샵 샵인샵 원장님 모집\n​\n2026년 12월 초 리뉴얼 오픈 예정!\n​\n17년간 운영해 온 헤어아밀리가 프리미엄 미용실, 염색방, 24시간 무인카페가 함께하는 복합뷰티공간으로 새롭게 오픈합니다.\n​\n기존 단골 고객과 다양한 업종의 고객 유입을 기대할 수 있는 공간입니다.\n​\n■ 모집 업종\n​\n피부관리 / 스포츠 마사지 / ㅂㅇㄱ / 붙임머리 / 메이크업·업스타일\n​\n※ 네일샵 입점 완료\n​\n■ 입점 조건\n​\n- 독립형 시술 공간 약 3.5평\n- 보증금 300만 원 / 권리금 200만 원\n- 월세 80만 원\n- 관리비 전체 매장 관리비의 12% (월 약 20만 원 내외, 변동 가능)\n- 개별 사업자 독립 운영\n​\n■ 초기 창업 비용 부담 최소화!\n​\n- 기본 인테리어 완비\n- 냉난방기 전체 신규 교체\n- 개인 시술 장비와 제품만 준비하면 입점 가능\n- 고객 대기공간 및 공용시설 이용\n​\n■ 관리비에 포함되는 혜택\n​\n- 전기·수도·냉난방 비용\n- 고객 최대 5시간 무료 주차 (주차비 포함)\n- 고객 접객용 커피·차·다과 무료 제공\n- 청소 여사님 공용공간 청소 지원\n- 공용시설 유지관리\n​\n※ 개인 시술실 내부 및 시술도구 관리는 각 원장님 담당\n​\n■ 입점 원장님 특별 혜택\n​\n- 17년간 확보된 미용실 단골 고객층\n- 미용실·염색방·무인카페 고객의 자연스러운 유입 기대\n- 공용 대기공간 및 편의시설 이용\n- 아밀리 라운지 무인카페 충전금 100% 추가 적립\n​\n※ 무인카페 10만 원 충전 시 총 20만 원 이용 가능\n​\n※ 무인카페는 원장님 개인 이용이나 VIP 고객 특별 접객 시 선택적으로 이용하는 별도 혜택입니다. 일반 접객용 커피·차·다과는 무료 제공됩니다.\n​\n■ 위치 및 문의\n​\n경기도 용인시 기흥구 보정동 1265-3\n패밀리프라자 2층 (죽전카페거리·단국대 인근)\n​\n입점 문의 : 010-5602-0479\n​\n시술 중 통화가 어려우니 문자 문의 부탁드립니다.\n​\nHAIR AMILY 헤어아밀리",
