    "body": "하남 속눈썹, ㅂㅇㄱ 샵 양도\n​\n미사역 연결되어 있습니다.\n보증금 1000만원 월세 63만원\n관리비 별도\n지하 B1층\n11.8평\n시설,집기 권리금 500만원\n​\n바닥 타일,조명공사 되어 있습니다.\n-전동베드(리모컨,풋페달) 세면대,온수기, 대형거울, 대한 링라이트, 미니 냉장고, 스피커, 커튼 등등 모든 집기류 포함\n​\n첫 매장이시면 오픈 하시고나서 하루(약1시간-2시간)\n네이버 플레이스 세팅해 드려요.\n​\n(오픈하면 자잘하게 나가는 비용 많을텐데 페인트칠도 안하셔도 됩니다.)\n​\n가벽안의 공간과 대기실 조명 다르게 설치 되어있어서\n작업 하시기 좋으실 거예요.\n​\n공간 나누어져 있어서 샵인 샵 하셔도 괜찮을 것 같아요.\n​\n010-칠칠칠2-사681\n​\n문자 남겨주세요!\n​\n주차 자리 넓고 주차하기 편안합니다.\n2시간 무료 주차권 나와요!\n임차인은 주차 한대 무료에요\n​",
