    "summary": "신사역 가로수길 위치 (2000/180) 제작카운터,제작붙박이 시스템에어컨. 고가 샹들리에+테이블 등 필요하신 모든 집기 다 두고갑니다. 들어오셔서 바로 시술 하실 수 있는 컨디션이에요. 샵인 자리 1룸 있고 안쪽 프라이빗 룸 있고 탕비실까지 있어요. 샵인구하시면 강남권 단독룸 6-70",
    "body": "신사역 가로수길 위치 (2000/180)\n제작카운터,제작붙박이 시스템에어컨. 고가 샹들리에+테이블 등\n필요하신 모든 집기 다 두고갑니다.\n들어오셔서 바로 시술 하실 수 있는 컨디션이에요.\n샵인 자리 1룸 있고 안쪽 프라이빗 룸 있고 탕비실까지 있어요.\n샵인구하시면 강남권 단독룸 6-70이라 월세 부담 덜하실거에요.\n관리비도 전기 한여름 한겨울 5-6만원 정도밖에안나오구요.\n이 자리에서 오래했는데 매출도 좋았어요.\n거주지 이사로 샵 이전때문에 계속 고민하다 내놔요ㅠ\n거실이 넓어서 저는 수강공간으로 썼는데\n친구분 두분이서 하셔도 충분히 넉넉하실거에요.\n​\n화장실 건물 관리인이 청결하게 관리해주십니다.\n청소할거없이 편했고 건물주 터치 아예없어요.\n​\n권리금은 협의이나 빠르게 들어오시는분들에게 최대한 맞춰드리겠습니다.\n​\n더궁금하신점은 문자 부탁드려요!\n시술중이라 전화는 어려울수있어요!\n(010-9구34- 사이6일)\n​\n​",
