    "body": "출산 준비중이라 원래도 모실 예정이였지만\n갑자기 고위험 산모가되어 입원중인데 입원을 언제까지 할지 모르겠어서 빨리 올려 봅니다\n제가 입원중에는 샵을 전혀 사용하지 못해요 ㅜㅜ\n해서 더 편히 쓰실수있지않을꺼 싶어요\n​\n제시술룸 , 카운터 제외한 (인물추적 cctv 달려있으니 참고해주세요!)\n대기공간 냉장고 테이블 냉난방기 모두 자유롭게 이용 가능하세요\n​\n​\n사용하실 대기 공간입니다.\n​\n​\n사용하실 시술룸 입니다\n​\n​\n​\n기존에 피부종목으로 잠시 사용하시던 원장님 집기 모습입니다.\n*사진속 베드,배드커버 무상 제공 의자는 가져오셔야해요~\n​\n​\n​\n​\n​\n​\n​\n사용하실 공간 입구 사진입니다\n​\n​\n​\n​\n​\n​\n​\n​\n제 시술룸과 카운터 입니다. 이곳은 사용 하실수 없습니다\n​\n​\n​\n​\n​\n가게 입구에 2인 상담테이블+냉난방기 앞 대기2인 가능한 좌석 있어요\n​\n​\n*월세 35\n*관리비 10\n*휴지,종이컵,생수,종량제,공용공간 청소 무상제공 (남편이 2주 한번씩 방문해서 채워드릴예정입니다)\n*기본 3개월 단위 계약\n​\n​\n​\n종목 상관없이 모시고 자격증은 있어야합니당!\n다만 사업자 안되서 당근,네이버,명함등에 ‘주소 직접노출’하실수 없습니다 ㅠㅠ 간접노출이나 상담시 안내 가능하세요~!! ex)대야동 비둘기공원인근,대야동 홈플러스 맞은편\n​\n오픈전 소소하게 준비 원하시는 새내기 원장님들 포함 경력직 혹은 동네이전 뭐 기타 등등 원장님들 문의주세요!\n​\n깔끔히 사용하시기만 하시면 되용!!!\n​\n​\n카카오톡 오픈채팅을 시작해 보세요.\n링크를 선택하면 카카오톡이 실행됩니다.\n​\n샵인\nhttps://open.kakao.com/o/ssnyhHUi\n​\n다인실 입원중에 있으니 10시전에 연락주세요~\n샵은 남편이 보여줄수있어요!\n평일 8시 이후\n주말 조율\n​\n​\n​\n​",
