    "summary": "안녕하세요 :) 부천역 도보 4분 거리에 위치한 샵입니다. 11월 25일부터 12월 10일까지 편하게 사용할 수 있는 베드 쉐어 공간을 활용하실 원장님 찾고 있습니다! ​ -위치 : 부천역 근처 ​ -기간 : 11월 25일부터 12월 10일 ​ -이용관련 : 속눈썹 연장/펌 연습이 필요",
    "body": "안녕하세요 :)\n부천역 도보 4분 거리에 위치한 샵입니다.\n11월 25일부터 12월 10일까지 편하게\n사용할 수 있는 베드 쉐어 공간을 활용하실 원장님 찾고 있습니다!\n​\n-위치 : 부천역 근처\n​\n-기간 : 11월 25일부터 12월 10일\n​\n-이용관련 : 속눈썹 연장/펌 연습이 필요하신 분, 연습 목적만 가능 등\n영업x\n​\n-시간 기간 : 11월25~ 12월 10일 날짜,시간 언제든 가능하세요\n(시간 조정 후 문의 주세요)\n​\n-요금 : 기본요금 시간13,000원\n2주 동안 풀로 이용 시 가격 조정해 드립니다.\n​\n-주차 가능\n​\n-온열베드, 의자 , 상담공간 제공 됩니다\n기타 개인 재료는 직접 가져오셔야 해요.\n​\n예약 및 문의 방법\n문의하실 때 아래 내용도 함께 알려주시면 감사하겠습니다.\n​\n성함 또는 활동명:\n연락처:\n희망 날짜 및 시간 :\n이용 인원:\n​\n좋은 인연으로 함께할 원장님 기다리겠습니다. 감사합니다!\n(공간 사진 원하시면 보내드립니다.)\n​\n010 - 오칠오일 - 5749 로 연락주세요 ~^^\n​\n​",
