    "ts": 1793259559963,
    "summary": "🤍 선릉역 네일 샵인샵 원장님 모집 🤍 ​ 안녕하세요. 저희 샵에서 네일 샵인샵으로 함께하실 새로운 원장님을 모집합니다. ​ 현재 함께하고 계신 네일 원장님께서는 약 2년 6개월 동안 저희와 좋은 인연을 이어오셨는데요. ​ 그동안 꾸준히 성장하신 끝에 이번에 더 넓은 공간으로 확장 이전",
    "body": "🤍 선릉역 네일 샵인샵 원장님 모집 🤍\n​\n안녕하세요.\n저희 샵에서 네일 샵인샵으로 함께하실 새로운 원장님을 모집합니다.\n​\n현재 함께하고 계신 네일 원장님께서는\n약 2년 6개월 동안 저희와 좋은 인연을 이어오셨는데요.\n​\n그동안 꾸준히 성장하신 끝에\n이번에 더 넓은 공간으로 확장 이전하시게 되었습니다.\n​\n오랜 시간 함께했던 원장님의 새로운 출발을 진심으로 응원하며,\n비워지는 공간에서 새롭게 시작하실 원장님을 기다리고 있습니다. 🤍\n​\n​\n📍 선릉역 바로 앞, 도보 30초!\n​\n샵을 운영하다 보면 위치가 얼마나 중요한지 느끼실 거예요.\n지하철역에서 걸어서 5~10분 정도만 떨어져 있어도\n한여름 무더위나 추운 겨울에는 은근히 부담스럽잖아요.\n​\n저희 샵은 선릉역 출구 바로 앞 건물에 위치해 있어 도보 약 30초면 도착할 수 있습니다.\n특히 지하철역과 건물이 직접 연결되어 있어 비가 오거나 눈이 오는 날에도\n편하게 방문할 수 있다는 점이 큰 장점이에요.\n​\n원장님의 출퇴근은 물론, 고객님들도 계절이나 날씨에 크게 구애받지 않고 방문하기 좋은 위치입니다.\n​\n건물 내 주차도 가능해 차량을 이용하시는 고객님들도 편하게 방문하실 수 있어요.\n​\n​\n💅 샵인샵 입점 조건\n​\n• 보증금 100만 원\n• 월세 80만 원\n• 별도 관리비 없음\n• 계약기간 6개월 또는 1년 선택 가능\n• 입점 조건 협의 가능\n​\n🤍 공간 및 이용 안내\n​\n• 네이버 지도 개별 업체 등록 가능\n• 리클라이너 의자에서 네일 작업 가능\n• 기존 원장님이 사용하시던 집기는 새로운 집기로 교체 예정\n​\n​\n독립적인 네일샵 창업을 준비하고 계시거나,\n초기 창업 부담을 줄이면서 본인만의 고객을 관리하고 싶은 원장님께 좋은 기회가 될 것 같습니다.\n​\n특히 고객님들이 찾아오기 편한 위치에서 시작하고 싶은 분이라면\n직접 방문하셔서 입지를 확인해 보셨으면 좋겠어요.\n​\n각자의 업무와 운영 방식을 존중하며, 서로 배려하는 분위기에서\n오랫동안 좋은 인연을 이어갈 수 있는 분을 기다리고 있습니다.\n​\n처음부터 입점을 결정하지 않으셔도 괜찮습니다.\n사진만으로는 공간을 충분히 확인하기 어려우니\n직접 방문하셔서 위치와 공간을 둘러보시고 천천히 결정하셔도 좋아요.\n샵 구경만 하셔도 괜찮으니 편하게 연락 주세요. 🤍\n​\n​\n📩 입점 문의 및 방문 예약\n​\n010-3160-7696\n문의는 문자로 부탁드립니다.\n​\n​\n​",
