    "summary": "인천 부평 문화의거리 건너편 대로변 3층 왁싱샵 내 샵인 원장님 모십니다! 지하상가 출구 5초거리 교통편 좋고 유동인구 많아요. ​ 신규 고객님 중 70%는 지도 보고 방문하셨어요! 위치 아주 좋은데 지방으로 이사하게 되어 내놓습니다ㅠㅠ ​ ​ 관리비 포함 100/50 ​ 계약기간 최소",
    "body": "인천 부평 문화의거리 건너편 대로변 3층\n왁싱샵 내 샵인 원장님 모십니다!\n지하상가 출구 5초거리 교통편 좋고 유동인구 많아요.\n​\n신규 고객님 중 70%는 지도 보고 방문하셨어요!\n위치 아주 좋은데 지방으로 이사하게 되어 내놓습니다ㅠㅠ\n​\n​\n관리비 포함 100/50\n​\n계약기간 최소 6개월\n​\n왁싱, ㅂㅇㄱ 제외\n피부 속눈썹 등 문의주세요\n​\n​\n​건물주 전대차 허락 안 해줘서 사업자불가해요😢\n독립된 공간이라 이전 원장님들은 제 사업자로\n개인 플레이스 승인받으셨어요!\n​\n​\n가벽 아닌 닫히는 단독룸이라 영업은 편하실겁니다.\n방 내부 냉난방, 베드, 웨건 있으니\n집기만 가져오시면 바로 영업 가능하세요.\n​\n이전 속눈썹 샵 운영중이었는데 필요하신 물품\n협의하에 저렴히 구매도 가능합니다.\n​\n샵 내부 개인 화장실도 있고 세탁기도 있어서\n피부하시는 분들도 아주 좋으실꺼에요\n​\n출퇴근 터치 일절 없고 샵 영업시간 내(11-21)\n개인적으로 자유롭게 영업하시면 됩니다!\n​\n고객층 탄탄히 10년째 한곳에 머문 왁싱샵이라\n중간에 폐업할 일도 없어요\n​\n저는 거의 시술중일때가 많아 영업 편하실거예요\n잘 정착하셔서 서로 손님도 소개하고 윈윈해요🫶🏻\n​\n​\n​010-9964-1337\n시술중 통화 어려우니 문자로 주시면 감사드리겠습니다. 😀",
