    "summary": "전) 속눈썹, smp 원장님 공간 ​ 요즘 경기가 많이 안좋죠?? 그래서 샵인 월세 대폭 인하하려고 하니 의욕이 넘치시는 원장님이 이 공간 사용하셨으면 좋겠습니다. 원장님들이 궁금한게 있으면 서슴없이 물어봐주세요. 도움이 될만한게 있으면 도우면서 지낼까 합니다. (그래서 최소 3개월 ~",
    "body": "전) 속눈썹, smp 원장님 공간\n​\n요즘 경기가 많이 안좋죠??\n그래서 샵인 월세 대폭 인하하려고 하니 의욕이 넘치시는 원장님이 이 공간 사용하셨으면 좋겠습니다.\n원장님들이 궁금한게 있으면 서슴없이 물어봐주세요.\n도움이 될만한게 있으면 도우면서 지낼까 합니다.\n(그래서 최소 3개월 ~6개월이상 하실 분을 원해요.)\n​\n✔️개인 샵 창업 전\n✔️투잡으로 작업 공간 필요하시거나\n✔️포트폴리오/모델 작업 공간 필요하신 원장님\n내 샵처럼 편하게 이용하세요.\n​\n종목: 속눈썹, smp, 반영구 가능\n플레이스 x\n​\n위치 : 상동역 (7호선)도보 3분, 주차가능\n​\n(신중동, 부천분들 말고도 인천(삼산동, 부개동) 쪽 분들도 부평보다 더 가까워서 잘 오세요)\n​\n크기 및 집기 : 약 16평, 베드 총 3개, 상담테이블, 냉장고, 싱크대, cctv\n​\n2023년 11월에 리모델링 했어요.\n​\n전체 화이트 톤으로 매우 깔끔합니다.\n​\n상동에서 가장 핫한 먹자골목에 위치한 큰 건물입니다.\n​\n상동역, 먹자골목 근처로 입지 가장 좋고,\n​\n대로변 쪽으로 위치해서 구석지거나 어두운 느낌 전혀 없어요.\n​\n주변 주차가능한 건물이 없어서 찾기 어려운 주차가능 매물입니다.\n​\n샵인의 경우(단독룸)\n(사진 속 공간)\n​\n보증금 100 월세 30(관리비 포함)\n​\n사업자 등록 x, 원장님 주차등록 가능, (고객 주차권 1시간권 250원, 2시간권 300원 구매가능)\n​\n베드+베드커버+시술의자+수납장\n공동사용 : 신발장(실내화), 전신거울, 헹거(옷걸이), 냉장고, 간식 수납장등등\n​\n​\n​\n베드 쉐어는 보증금 30만원, 월 20로 구합니다.\n20시간 이하로 사용 할 것 같으시면 시간당으로도 가능하세요.(시간당 1.5만원)\n​\n(베드는 총3개로, 베드 쉐어는 따로 신청 들어올 시 해당타임 미리 말씀드릴거에요)\n​\nv 주차가능\n​\nv 7호선, 도보 3분.\n​\nv 상동에서 가장 핫한 먹자골목 주변.\n​\nv 작은 골목 사이사이 아니고 큰 대로변 방향.\n​\nv 로비에 싱크대도 있어서 수도사용 편하세요.\n​\nv 모든 집기 사용 가능.\n​\nv 출퇴근 시간 터치 없습니다.\n(사용 시간: 오전 10시 ~ 오후 9시)\n​\nv 혼자 사용하시는거라 내 샵처럼 사용하시고 청소, 분리수거 하시면 됩니다.\n​",
