    "body": "힘든시기에 보증금 관리비없이 월30만원 개인 고정룸\n베드쉐어나 샵인 원장님 모십니다\n​\n분명 단점과 장점은 있습니다 끝까지 잘 읽어보시고 꼭 필요하신 원장님들 연락주세요\n​\n​​단점은 사업자는 힘듭니다 그리고 상권이 사당과 강남을 오가는 중간에있다보니 대중교통은 좋지만 차가 혼잡해 차량이많고 동네가 건너편에는 방배동 옆에는 시장이고 뒤쪽은 주거지와 아파트로 유동인구가 많아 주차는 하실수가없습니다.그러나 인근에 유료주차장이있고 고객님들 대부분 이쪽 지역을 잘 아시기 때문에 이해하시고 대중교통을 이용하시며 그게 더 편하다고 하십니다\n​\n샵은 지하1층이지만 사용하시는 원장님과 고객님 모두 쾌적해서 전혀 지하느낌이 안나신다 하십니다 그만큼 샵청결부터 관리가 잘 되어있습니다\n​\n​​장점은 개인 고정룸으로 룸안에 베드,시술의자,책상,트롤리,개인조명,옷걸이,개인사물함으로 제품은 모두 샵에 두시고 출퇴근하시면 될 정도로 시술하시기 편하고 홀에는 자동 커피머신부터 소독기,냉장고로 공용사용입니다 그리고 화장실도 샵내부에있어 사용하시기 편합니다\n​\n​처음 3개월 계약후 그다음부터 한달씩 연장하실수있습니다\n사용시간은 오전11시부터 저녁11시까지이고 자유출퇴근입니다 단점보다 장점이 훨씬 많은 샵이니 개인샵을 나가기전에 포트폴리오나 고정고객이 확보가 필요하신 원장님들은 많은 문의 주세요\n​\n​01099716186 문자 주세요\n문의주실때 거주지역/종목/입주예정 같이 문자주세요~\n​\n​\n​",
