    "body": "🌿 명지국제신도시 뷰티샵 양도합니다\n​\n현재 운영 중인 샵 양도합니다 :)\n네이버 플레이스 상위권 뷰티샵입니다\n​\n📍 위치\n명지국제신도시 (자세한 위치는 연락주세요)\n​\n🏠 매장 정보\n• 약 11평\n• 층고가 높은 구조로 답답하지 않고 개방감 있어요\n• 실제로 보시면 11평보다 공간이 넓게 느껴지는 구조입니다.\n• 건물 내 화장실 있음\n• 주차 가능\n• 에어컨 설치되어 있음\n• 관리비 약 6~8만원\n​\n💰 조건\n• 보증금 1,000만원\n• 월세 630,000 (부가세 별도)\n• 권리금 문의주세요(조정합의가능)\n​\n✨ 시설 및 비품\n• 카운터 1개\n• 시술 베드 2개 의자2개\n• 세면대 1개\n• 에어컨\n• 고객 대기 쇼파\n• 상담테이블\n• 그 외 매장 시설 및 비품 전체 양도 가능\n※ 컴퓨터는 양도 품목에서 제외됩니다.\n​\n💇🏻‍♀️ 업종\n미용업 전반 가능하며 업종 변경도 가능합니다.\n​\n현재 구조 그대로 뷰티샵으로 운영하셔도 좋고,\n간단한 부분 인테리어만 하시면 네일샵 등 다른 뷰티 업종을 함께 운영하는 형태로도 활용하기 좋은 공간입니다.\n​\n공간이 분리되어 활용도가 좋아서\n실제로 매장을 보시면 11평보다 넓게 느껴지실 거예요 :)\n​\n🤍 기존 고객도 충분히 확보되어 있습니다.\n인수하시는 분께 기존 고객을 최대한 자연스럽게 이어받을 수 있도록 고객 안내 및 인계 가능합니다.\n​\n따로 처음부터 고객을 모집해야 하는 부담을 줄이고\n인수 후 바로 운영하실 수 있는 샵입니다.\n​\n📌 바로 인수 가능합니다.\n​\n1인샵을 새롭게 시작하시는 분,\n네일·속눈썹·왁싱 등 뷰티업종을 함께 운영하고 싶으신 분께 추천드립니다.\n​\n관심 있으신 분은 댓글 또는 01034013692\n자세한 내용 안내드리겠습니다 🤍",
