    "summary": "안녕하세요. 개인적인 사정으로 인하여 샵을 정리하게 되었어요. 선뜻 큰 돈 주고 창업하시기 부담스러우신분~ 오래되지 않은 깨끗한 건물이에요. 창업하실때 인테리어 걱정 많이 되시잖아요. 저도 처음에 욕심내지 않고 깔끔한 정도로만 해서 바로 일 시작하고 돈 버셔서 조금씩 더 추가하셔도 좋을",
    "body": "안녕하세요.\n개인적인 사정으로 인하여 샵을 정리하게 되었어요.\n선뜻 큰 돈 주고 창업하시기 부담스러우신분~\n오래되지 않은 깨끗한 건물이에요.\n창업하실때 인테리어 걱정 많이 되시잖아요.\n저도 처음에 욕심내지 않고 깔끔한 정도로만 해서\n바로 일 시작하고 돈 버셔서 조금씩 더 추가하셔도 좋을것 같습니다^^\n​\n통창에 천고가 높아 오시는 분들마다\n뻥뚫린 뷰와 하늘 보시고 좋아들하세요~\n저도 오래 일해도 답답함이 없이 너무 좋았어요!\n통창이라 밝은데 해는 직접 들어오지 않아 커텐은 따로 안했습니다. 필요도 없고, 통창의 장점을 더 부각시켰어요!\n​\n천장에 시스템 냉난방기가 있어요.\n화장실도 가까이 있고 깨끗합니다.\n​\n보증금500/ 월50\n시설비(권리금) 400\n관리비는 쓰시는거에 따라 다르겠지만 저는 보통12만원대 정도로 나왔어요.\n평수 8평정도\n16층 중 9층입니다.\n​\n베드 2개+의자(베개, 블랭킷, 전기매트 각각 있어요)\n서랍장\n트롤리\n카운터\n테이블/의자\n미니냉장고\n신발장 벽에 깔끔하게 고정시켰어요.\n(베드빼고는 다 새제품이에요)\n​\n반영구재료와 링라이트는 가져갑니다.\n​\n주차장 지하1~3층까지 있고\n한대 등록가능,\n방문 2시간 무료에요.\n이후 30분당 250원에 정산할수 있습니다.\n​\n반영구, 속눈썹 바로 시작하실분 연락주세요!!\n010-9284-0779\n​\n​\n​",
