    "summary": "🤍 청주 가경동 뷰티샵 샵인샵 원장님 모십니다! ​ 12월부터 입점 가능하신 원장님을 찾습니다! ​ 2년 가까이 함께했던 속눈썹 원장님께서 좋은 기회로 개인 샵을 오픈하시게 되어 새롭게 함께하실 원장님을 모십니다☺️ ​ 기존 원장님도 이곳에서 꾸준히 성장하셔서 현재는 본인 샵을 오픈해 ",
    "body": "🤍 청주 가경동 뷰티샵 샵인샵 원장님 모십니다!\n​\n12월부터 입점 가능하신 원장님을 찾습니다!\n​\n2년 가까이 함께했던 속눈썹 원장님께서\n좋은 기회로 개인 샵을 오픈하시게 되어\n새롭게 함께하실 원장님을 모십니다☺️\n​\n기존 원장님도 이곳에서 꾸준히 성장하셔서\n현재는 본인 샵을 오픈해 잘 운영하고 계세요!\n​\n저 역시 함께 성장하실 좋은 원장님을 만나고 싶어요🤍\n​\n📍 샵 위치 및 환경\n​\n* 청주 가경동 32평 뷰티샵\n* 청주 터미널 차량 5분 거리\n* 사대부고등학교 인근\n* 개별 시술 공간 제공 가능\n* 베드 사용 가능\n* 개별 사업자 등록 가능\n​\n💰 입점 조건\n​\n* 보증금 200만 원\n* 월세 35만 원 + 전기세 1/2 부담\n* 또는 월세 40만 원 (전기세 포함)\n​\n🤍 이런 원장님께 추천드려요!\n​\n* 속눈썹 / 메이크업 / 붙임머리 / SMP 등\n* 같은 뷰티 종목도 협의 가능\n* 자유로운 출퇴근을 원하시는 분\n* 개인 샵 오픈 전 고객층을 쌓고 싶으신 분\n* 서로 배려하며 함께 성장하고 싶으신 분\n​\n🌷 샵 운영 안내\n​\n저는 현재 반영구, 왁싱, 속눈썹을 운영하고 있으며\n9월 출산 후 11월부터 복귀 예정입니다.\n​\n2027년 1월부터 약 1년간은\n주 2~3일 정도만 출근할 예정이라\n제가 상주하지 않는 날이 많아\n비교적 자유롭게 공간을 사용하실 수 있어요!\n​\n출퇴근 시간이나 운영 방식에\n크게 간섭하지 않습니다.\n​\n함께 사용하는 공간인 만큼\n기본적인 청결과 배려만 지켜주시면 됩니다☺️\n​\n성격 둥글둥글하고 원만하신 원장님,\n오래도록 좋은 인연으로 함께하실 분이면 좋겠어요!\n​\n📩 입점 문의 : 010-5846-3279\n​\n편하게 연락 주세요🩵\n​",
