    "summary": "​ 정성껏 꾸민 저의 1인샵을 함께 사용하실 원장님을 찾습니다. ​ 약 6평의 아늑하고 깔끔한 공간이에요. ​ 일반적인 베드쉐어와 달리 예약하신 시간에는 1인샵 전체를 단독으로 사용하실 수 있습니다. ​ 고객 상담부터 시술, 포트폴리오 촬영까지 편하게 이용하실 수 있도록 공간과 시설을 ",
    "body": "​\n정성껏 꾸민 저의 1인샵을 함께 사용하실 원장님을\n찾습니다.\n​\n약 6평의 아늑하고 깔끔한 공간이에요.\n​\n일반적인 베드쉐어와 달리 예약하신 시간에는 1인샵 전체를 단독으로 사용하실 수 있습니다.\n​\n고객 상담부터 시술, 포트폴리오 촬영까지 편하게 이용하실 수 있도록 공간과 시설을 갖춰두었어요.\n​\n무엇보다 정해진 요일에 맞춰 고객을 받는 게 아니라, 내 고객 예약에 맞춰 원하는 날짜와 시간을 선택할 수 있다는 점이 가장 큰 장점이에요.\n​\n아직 개인샵 오픈이 부담스럽거나, 좋은 환경에서 차근차근 고객을 늘려가고 싶은 원장님께 추천드려요.\n​\n공간 안내\n​\n✔ 마곡역 인근 / 약 6평\n✔ 프라이빗 시술 공간 및 베드\n✔ 고객 대기 및 상담 테이블\n✔ 트롤리, 개인 수납공간, 수전,링라이트\n✔ 촬영용 거치대 및 포트폴리오 촬영 가능\n✔ 와이파이, 냉난방, 전자레인지\n✔ 커피머신, 생수 및 기본 편의시설\n​\n공용 공간의 정기적인 청소는 제가 직접 관리합니다.\n​\n원장님들께서는 시술 후 사용하신 자리와 도구만 깨끗하게 정리해 주시면 돼요. :)\n​\n이용 안내\n​\n• 모집 대상 : 속눈썹 펌·연장 원장님\n• 모집 인원 : 2명\n• 보증금 : 100만 원\n• 월 이용료 : 50만 원\n• 관리비 : 3만 원\n• 계약 기간 : 기본 3개월\n• 이용 방식 : 요일 제한 없는 자유 예약제\n• 예약 : 2시간 단위 / 하루 최대 4시간\n• 주차 : 원장님 이용일 기준 2시간 지원\n• 고객 주차 : 최대 2시간 30분 / 1,000원\n​\n공간은 함께 사용하지만, 예약하신 시간만큼은 각자의 샵처럼 편안하게 사용하셨으면 좋겠어요.\n​\n서로의 고객과 공간을 존중하며, 깔끔하고 기분 좋게 함께하실 원장님을 기다립니다.\n​\n궁금하신 점이나 공간 방문을 원하시면 편하게 연락 주세요. :)\n​\n010-5612-4725\n​\n입점은 관련 영업 요건 및 공간 사용 가능 여부 확인 후 진행합니다.\n​",
