    "summary": "안녕하세요! 부산 북구 화명동에 위치한 피부 전문 샵입니다. 화명동아시는분들읔 아시겠지만 지도로만봐도 세대가 어마어마합니다:) 사람들이 애초에많아요! 함께 시너지 내며 기분 좋게 성장해 나가실 여성 원장님을 모집합니다. ​ 입지 최상에 유동인구가 많아 초보 원장님이나 소자본 창업/확장 ",
    "body": "안녕하세요!\n부산 북구 화명동에 위치한 피부 전문 샵입니다.\n화명동아시는분들읔 아시겠지만 지도로만봐도\n세대가 어마어마합니다:) 사람들이 애초에많아요!\n함께 시너지 내며 기분 좋게 성장해 나가실 여성 원장님을 모집합니다.\n​\n입지 최상에 유동인구가 많아 초보 원장님이나 소자본 창업/확장 이전하시는 분께 더없이 좋은 조건입니다.\n​\n편하게 연락해 주세요!\n[ 매물 상세 정보 ]업종/종목: ㅂㅇㄱ, SMP, 속눈썹 등 (피부 외 뷰티 전 종목 가능 / 여성 원장님)\n위치: 부산 북구 금곡대로 238 (1층 상가)\n도보 유동인구 많고 접근성 최상인 자리입니다.\n보증금 / 월세: 50만 원 / 23만 원 (관리비 포함! 가성비 최고)베드쉐어 원하실 경우 조건 협의 가능합니다.\n해당층: 1층 / 1층\n​ 기본 시설: 베드, 체어 및 기본 집기 완비 (몸만 들어오셔서 영업 시작 가능)\n​ 입주 가능일: 즉시 입주 / 협의 가능\n​ [ 이런 원장님께 적극 추천합니다! ]\n초기 고정비(월세/보증금) 부담을 대폭 줄이고 시작하고 싶으신 분\n유동인구가 많고 도보 접근성이 뛰어난 1층 매장을 찾으시는 분\n샵인샵으로 부담 없이 고정 고객층을 확보해 나가고 싶으신 분\n📲 문의 연락처: 010-5489-4762\n(시술/관리 중일 때가 많아 문자로 먼저 [성함/희망종목/희망입주일] 남겨주시면 빠르게 확인 후 연락드리겠습니다! 자세한 위치는 문자 주시면 안내해 드려요.)\n​",
