    "ts": 1792995475973,
    "summary": "대전 둔산동 베드쉐어 원장님 모집합니다 🤍 (여성 원장님만 가능) ​ 연습이나 포트폴리오를 위한 시술 공간이 필요한 원장님께 베드 한 자리를 빌려드립니다. ​ 📍 위치 대전 서구 둔산동, 5층 갤러리아타임월드에서 도보 약 5분 거리로 둔산동 중심에 위치해 있습니다. ​ 이런 분께 잘 맞",
    "body": "대전 둔산동 베드쉐어 원장님 모집합니다 🤍\n(여성 원장님만 가능)\n​\n연습이나 포트폴리오를 위한 시술 공간이 필요한 원장님께 베드 한 자리를 빌려드립니다.\n​\n📍 위치\n대전 서구 둔산동, 5층\n갤러리아타임월드에서 도보 약 5분 거리로 둔산동 중심에 위치해 있습니다.\n​\n이런 분께 잘 맞아요\n· 연습할 공간이 필요한 초보 원장님\n· 모델 시술이나 포트폴리오 촬영을 준비 중인 원장님\n· 큰 보증금이나 별도 샵을 구하기 부담스러운 원장님\n​\n🛏️ 제공 공간 및 비품\n· 베드 1개, 의자 1개, 트롤리 1개\n· 이불, 베개, 일회용 베개포\n· 데스크 수납공간 한 칸\n· 종목에 맞게 필요한 물품을 가져와 자유롭게 세팅 가능\n​\n🛋️ 함께 사용하는 공간\n· 고객 대기실\n· 정수기 및 티 스테이션\n· 인터넷 및 와이파이\n· 복도 남녀 구분 화장실\n· 건물 내 기계식 주차장\n​\n🔑 이용 안내\n· 제 영업시간이나 휴무일에 맞추지 않고 각자 일정에 따라 이용하실 수 있어요.\n· 월요일부터 일요일까지 요일 제한 없이 이용 가능합니다.\n· 영업시간 제한이나 휴무일 제한은 없습니다.\n· 고객 및 예약 관리는 각자 직접 해주시면 됩니다.\n· 각자 다른 상호와 브랜드로 활동하는 형태입니다.\n· 개별 사업자등록은 하지 않는 조건입니다.\n​\n💰 입점 조건\n· 보증금 30만 원\n· 월 이용료 30만 원\n· 별도 관리비 및 수도요금 없음\n· 전기요금은 이용 인원 기준으로 1/n 분담합니다. 기본 1/3입니다.\n​\n현재 제가 임신 중이라 샵을 비우는 시간이 많은 편이지만\n같은 공간을 함께 사용하는 만큼, 이용 시간이 겹칠 때 서로 배려하며 깔끔하고 조용하게 사용해주실 분을 찾고 있습니다.\n연습이나 포트폴리오 작업을 위한 공간이 필요하셨다면 편하게 문의 주세요 🤍\n공간 사진과 자세한 위치, 이용 관련 안내는 채팅으로 보내드릴게요.\n​\n​\n​\nhttps://open.kakao.com/o/sZd5WuMi\n대전 샵인샵\nopen.kakao.com\n​",
