    "body": "​\n​\n업종종목 : 왁싱.피부\n(속눈썹.문신도 하셔도되요)\n​\n소재지 : 오산 원동 이마트부근\n​\n매물가격 : 200/50\n​\n권리금 : 없음\n​\n실평수 : 2.5평\n​\n해당층 / 전체층 : 2층\n​\n입주가능일 : 8월 25일\n​\n문의 연락처 : 010-4773-1513\n​\n-- 매물 상세설명 --\n​\n​\n​\n🌿 오산 원동 토탈뷰티샵\n왁싱 샵인샵 원장님 모십니다\n​\n권리금 ❌ / 독립룸 + 샤워실 완비\n​\n안녕하세요 :)\n오산 원동 이마트 인근에 위치한 토탈뷰티샵입니다.\n​\n헤어 · 네일 · 왁싱을 함께 운영하는 공간으로\n8월 중순 오픈 예정이며,\n샵 안에서 왁싱실을 독립적으로 운영하실 원장님을 모십니다.\n💛속눈썹.반영구. 등등 룸에서 하실수 있는건 다 하셔도 되세요(저는 헤어.네일만 합니다)\n​\n​\n✨ 독립적인 왁싱 공간\n​\n혼자 편하게 사용하실 수 있는 독립 룸과 샤워실이 마련되어 있어 왁싱샵 운영에 필요한 공간을 갖추고 있습니다.\n​\n반영구 원장님은 반영구 합법화 되며 설치 하여야할 수전2개 소독실도 가능 하십니다.\n​\n왁싱을 주종목으로 운영하시면서\n속눈썹 · 반영구 등 다른 뷰티 종목을 함께 운영하시는 것도 가능합니다.\n​\n🏠 매장 시설\n​\n2층 단독 상가\n출입문 바로 앞 엘리베이터\n매장 내부 남·여 화장실\n독립 룸 + 샤워실\n공용 식사 및 탕비 공간\n세탁기 · 건조기 구비\n1년 단위 계약 가능\n💰 조건\n​\n보증금 200만원 / 월세 50만원\n수도 · 전기 · 인터넷.cctv.정수기.티바.관리비 월 5만원\n​\n권리금 없음\n​\n실평수 약 2.5평\n입주 가능일 : 8월 25일\n​\n📍 오산 원동 이마트 인근\n📞 문의 : 010-4773-1513\n​\n​",
