    "body": "부평역 도보 5분,\n뷰티샵 샵인샵 모집\n​\n사진보다 실제 공간이 더욱 넓으며,\n직접 방문하시면 더욱 만족하실 수 있습니다.\n​\n✔ 즉시 입주 가능 (입주일 협의 가능)\n이용 가능 업종\n왁싱 제외 모든 뷰티 업종 가능\n사업자 불가\n최소 6개월 계약\n​\n바로 계약 가능\n룸 총 3개, 2개 공실\n​\n바로 계약하시면\n첫 달 월세 35만원 으로 해드려요.\n​\n📌 기존 고객층을 보유한 원장님\n​\n보증금 50만 원 / 월세 40만 원\n전기요금 50% 부담 (실사용 기준 월 1~3만 원 내외)\n​\n📌 창업 초기 또는 신규 오픈을 준비 중인 원장님\n​\n보증금 50만 원 / 월세 40만 원\n포트폴리오 작업 또는 창업 초기 원장님에 한해 가능\n​\n제공 시설\n​\n슬라이딩 도어로 독립적인 프라이빗 공간\n무료 주차 가능\n출퇴근 시간 제한 없음 (단, 새벽 시술은 불가)\n베드\n시술 의자\n트롤리\n이케아 선반\n전신거울\n수납장\n재료만 준비하시면 바로 운영 가능합니다.\n​\n저는 예약이 있는 시간에만 샵을 이용하기 때문에, 대부분의 시간 동안 편안하고 자유롭게 공간을 사용하실 수 있습니다.\n​\n실제 공간을 직접 보시면 더욱 만족하실 거라 자신합니다. 궁금한 사항이나 방문 문의는 언제든 편하게 연락 주세요. 😊\n​\n카카오톡 오픈채팅을 시작해 보세요.\n링크를 선택하면 카카오톡이 실행됩니다.\n​\n부평 샵인샵\nhttps://open.kakao.com/o/s07gz4Ff",
