    "summary": "강남 논현역 7번 출구 도보 3분 거리! 현재 튼살 커버 전문샵으로 운영 중인 샵에서 샵인샵으로 함께하실 원장님을 모집합니다. ​ ✔️ 종목, 업종이 겹쳐도 계약 가능 ✔️ 출퇴근 자유롭게, 편안한 샵 운영 가능 ​ 📍 공간 및 시설 안내 실평수 약 26평의 넓고 깔끔한 공간입니다. 총",
    "body": "강남 논현역 7번 출구 도보 3분 거리!\n현재 튼살 커버 전문샵으로 운영 중인 샵에서 샵인샵으로 함께하실 원장님을 모집합니다.\n​\n✔️ 종목, 업종이 겹쳐도 계약 가능\n✔️ 출퇴근 자유롭게, 편안한 샵 운영 가능\n​\n📍 공간 및 시설 안내\n실평수 약 26평의 넓고 깔끔한 공간입니다.\n총 3개의 룸이 있으며, 모든 룸에 창문이 있어 채광, 개방감 좋고 환기도 잘 됩니다.\n​\n- 각 룸별 개인 냉·난방기 완비\n- 룸별 사물함, 트롤리 구비\n- 상담용 테이블 및 의자 구비\n- 각 룸 방문 잠금장치 설치\n- CCTV 설치로 보안 관리\n- 출입문 잠금장치 운영 (안에서 열어줘야 들어올 수 있어요!)\n- 안내데스크 이용 가능\n- 대기공간 로비 이용 가능\n- 온열 기능이 있는 미용 베드 구비 (전동 베드 X)\n​\n★ 개인 공간에서 독립적으로 관리와 상담을 진행하고 싶은 원장님께 추천드립니다.\n​\n​\n💰 룸별 임대 조건\n▪️ 작은방\n보증금 100만 원 / 월세 50만 원\n3개월 계약 시 월 45만원\n​\n▪️ 중간방\n보증금 100만 원 / 월세 60만 원\n3개월 계약 시 월 55만원\n​\n▪️ 큰방 ( 계약완료 )\n보증금 100만 원 / 월세 70만 원\n​\n※ 모든 월세는 관리비 포함 금액입니다.\n​\n​\n🙌 이런 원장님을 기다립니다!\n강남권에서 샵인샵 또는 베드 쉐어를 알아보시는 분\n초기 고정비 부담을 줄이고 샵을 운영하고 싶으신 분\n(마케팅, 홍보 등 샵 운영 관련 정보 공유도 가능해요)\n공간을 내 샵처럼 깔끔하게 사용해 주실 분\n서로의 공간과 운영 방식을 존중하며 함께 지내실 원장님 환영입니다. 😊\n​\n​\n📌 계약 전 확인 사항\n사업자등록 불가\n주차 불가\n​\n​\n📩 문의 및 방문 상담\n연락처: 010-오육공칠-9420\n상담 및 작업 중에는 통화가 어려울 수 있습니다.\n문자로 문의 내용을 남겨주시면 확인 후 답변드리겠습니다.\n편하게 문의 주세요!\n​",
