    "body": "​\n함께 공간을 꾸려나가실 네일 또는 속눈썹 원장님을 모십니다\n​\n위치 및 공간 안내\n- 구불당 단독주택 단지 내 1층\n- 매장 앞 주차 가능\n- 현재 왁싱샵 운영 중\n- 네일 / 속눈썹 각 존 입점 가능\n- 각각 사업자 등록 가능\n- 현재 공실로 즉시 입주 가능\n​\n네일\n- 1년 계약 : 보증금 200만 원 / 월 50만 원\n- 2년 계약 : 보증금 200만 원 / 월 40만 원\n​\n구비 품목 : 네일·패디 의자, 네일장, 수납장\n※ 네일 테이블과 작업 의자는 입점하시는 원장님께서 직접 준비해 주셔야 합니다\n​\n관리비 안내\n- 공용 관리비 없음\n- 전기세는 입점 원장님과 N분의 1로 부담\n- 별도 공용 관리비 없이 이용 가능합니다\n​\n현재 공실이라 입점 준비가 되어 있으신 원장님은 즉시 입주도 가능합니다.\n​\n서로 기본적인 예의를 지키고, 각자의 시술 공간을 깨끗하게 관리해 주신다면 편안하게 함께하실 수 있을 것 같아요.\n​\n사진이나 글만으로 판단하시기보다는 직접 방문하셔서 공간을 확인해 보시는 걸 추천드립니다\n​\n📞문의 : 010-4913-7400\n문자로 연락 주시면 확인 후 빠르게 답변드리겠습니다.\n​\n※ 현재 왁싱샵 운영 중으로 왁싱 등 동종 업종은 입점 불가",
