    "summary": "🔥 [경기광주 능평동] 권리금 700만 원! 시설 갖춰진 속눈썹샵 양도합니다 💕 ​ “속눈썹샵 창업, 처음부터 인테리어 하지 마세요! 이미 갖춰진 공간에서 시작하세요✨” ​ 안녕하세요 :) 경기 광주 능평동에서 운영 중인 속눈썹샵을 양도합니다. ​ 뷰티샵 창업을 준비하다 보면 상가부터 ",
    "body": "🔥 [경기광주 능평동] 권리금 700만 원! 시설 갖춰진 속눈썹샵 양도합니다 💕\n​\n“속눈썹샵 창업, 처음부터 인테리어 하지 마세요! 이미 갖춰진 공간에서 시작하세요✨”\n​\n안녕하세요 :)\n경기 광주 능평동에서 운영 중인 속눈썹샵을 양도합니다.\n​\n뷰티샵 창업을 준비하다 보면 상가부터 알아보고, 인테리어 공사에 집기 구매까지… 생각보다 많은 시간과 비용이 들어가죠.\n​\n처음부터 모든 것을 새로 준비하기보다, 갖춰진 시설을 활용해 내 샵을 시작하고 싶은 원장님께 추천드리고 싶어요. 🩷\n​\n✨ ✔ 인테리어 및 집기 포함!\n​\n이미 속눈썹샵으로 운영하던 공간이라 뷰티샵 창업을 계획하시는 분이라면 더욱 관심 있게 보실 만 합니다.\n​\n✔️ 인테리어 및 집기 포함 양도\n✔️ 처음부터 공간을 꾸미는 부담을 줄일 수 있는 기회\n✔️ 기존 시설을 활용해 오픈 준비 시간 절약 가능\n✔️ 속눈썹샵은 물론, 공간 활용이 가능한 뷰티업종을 고려하시는 분께 추천\n​\n💰 양도 조건 안내\n​\n📍 위치 : 경기 광주 능평동\n🏠 업종 : 속눈썹샵\n💵 권리금 : 700만 원 (협의 가능)\n🔑 보증금 : 1,000만 원\n📌 월세 : 100만 원 (관리비 포함)\n🪑 양도 포함 : 인테리어 및 집기\n📅 양도 사유 : 이전 및 확장\n​\n✨ 이런 원장님께 추천드려요!\n​\n✔️ 속눈썹샵 창업을 준비 중이신 예비 원장님\n✔️ 인테리어 공사와 집기 구매에 들어가는 부담을 줄이고 싶으신 분\n✔️ 기존 뷰티샵을 이전하거나 새로운 공간을 찾고 계신 원장님\n✔️ 내 스타일에 맞게 공간을 활용해 새롭게 시작하고 싶으신 분\n​\n창업할 때 가장 큰 고민 중 하나가 바로 초기 세팅이죠.\n​\n상가를 계약하고 인테리어를 시작하면 비용도 비용이지만 오픈까지 준비할 것도 정말 많습니다.\n​\n인테리어와 집기가 갖춰져 있어 창업 준비의 부담을 덜 수 있다는 점이 가장 큰 장점이에요.\n​\n권리금은 협의 가능하니 관심 있으신 분은 편하게 문의 주세요. 😊\n​\n📩 좋은 매물은 직접 확인해 보시는 게 가장 정확합니다!\n​\n내부 시설과 집기 구성이 궁금하시거나 양도 조건을 자세히 알고 싶으신 원장님은 부담없이 편하게 연락 주세요\n​\n공10-5125-7007\n​\n사진과 상세 내용을 안내해 드리겠습니다.\n​\n5년넘게 운영하면서 단골고객님 및 신규 유입 많아요\n무엇보다 주차 편하구요\n인품좋은 임대인이셔서 운영시 불편함이 없었습니다.\n​\n좋은 인연으로 이어질 분을 기다리겠습니다. 💗",
