    "body": "속눈썹샵이며,\n​\n현재 네일,ㅂㅇㄱ 샵인원장님 계십니다\n​\n네일원장님께서 출산으로 인해 네일샵인구합니다\n​\n27년 1월 7일 들어오실 수 있어요\n​\n미리 공고올립니다\n​\n사업자불가\n​\n비사업자로 플레이스가능\n​\n(현재 네일원장님도 제가 알려드린방법으로 플레이스 하시는중)\n​\n​\n​\n3개월 계약시 100/50\n​\n6개월 계약시 100/40\n​\n관리비포함이며, 개인차량 주차비용은발생합니다 약2만원후반대\n​\n​\n​\n010 2353 삼삼육구\n혹시 재료 필요하신분이계시면\n​\n팔고가신다네요\n​\n디피되어있는젤들은 기간임박하거나 지난것들이고\n​\n여분들은 기한넉넉하구요\n​\n젤,기초젤,파츠,세신드릴등 일괄 70입니다.\n​\n필요없으시다면 샵인들어오실때 위에사진처럼 집기들만 있을예정입니다.",
