    "body": "업종종목 : 네일\n​\n​\n소재지 : 5호선 목동역 3분내거리\n​\n​\n매물가격 : 네일 : 보증금 200/35(관리비포함)\n​\n권리금 : 권리금없으며, 나가실때도 동일합니다\n실평수 : 약4~5평 각방으로 드립니다.\n​\n해당층 / 전체층 : 2층/4층\n​\n입주가능일 : 언제든지 가능합니다\n​\n문의 연락처 : 010-3814-4133\n(문자 주세요!)\n​\n​\n-- 매물 상세설명 -\n​\n목동역 1번출구 에서 가깝습니다\n​\n목동역 도보3분이내 역세권 위치입니다.\n​\n현재 피부관리,왁싱 운영중이며 기존 네일선생님\n계약만료로 인해 새로운 샵인선생님을 구합니다\n네일 선생님 한 분 구합니다.\n출퇴근 터치 일절 없습니다.\n각방으로 드립니다\n​\n✔️모던한 인테리어\n✔️네일룸 옵션 : 가구다있습니다. 몸과 재료만 갖고오셔서 하면 됩니다.\n대기공간 , 세탁기 등 같이 사용 가능하고,\n음료, 다과 등 자유롭게 이용하시면 됩니다.\n​\n✔️서로배려하며, 같이성장하실 샵인선생님😊\n​\n주변아파트단지들이 많고 지하철역도가까워서 아파트광고 및 전단지 효과보기 좋습니다\n​\n사업자는 불가합니다.\n네이버 플레이스는 요건충족시 가능합니다\n​\n가게 차리는 비용 최소2500만원☝️자리좋은곳은 4000만원☝️\n가게차려도 손님이없으면 꽝이죠, 자리잡기 만만치않아요\n요즘같은경기에는 부담이적게 운영해보세요\n부담이적은 샵인으로 손님들 모아서 챙겨가세요~\n궁금하시면 매장 보러오세요~\n​\n​\n​",
