    "body": "100/35 관리비포함\n네일이나 속눈썹 원장님 모십니다\n다른샵인원장님 한분더계시고 성격조으십니다\n​\n​\n기존네일원장님 2년넘게 계셨구요\n목디스크 건강이슈로 네일을 아예 접으시고 쉬신다고합니다\n그래서 물건을 모두 양도 하고 싶으시다고해요~\n​\n속눈썹하시는분은 베드하나 제공됩니다!\n​\n​\n모두 100만에 넘기신다고 합니다~\n전동드릴?이랑 소독기만들고 들고 들어오심된되용~\n010 8484 2803 으로 문자나 저나주시면됩니다\n​\n이케아 테이블 / 1개\n이케아 서랍장 6칸 / 1개\n이케아 의자 / 2개\n이케아 트롤리 / 1개\n패디 의자 세트 / 1개\n젤네일 진열대 / 1개\n큐브 스탠드 조명 / 1개\nAncess 조명 / 1개\n링조명 / 1개\n미라클 유선 흡진기 / 1개\n아르마 유선 흡진기 / 1개\n키스 젤램프 / 2개\n비트 세척기 / 1개\n손받침대 / 1개\n온장고 / 1개\n​\n키스 젤네일 100컬러 세트\n메이유어 시럽젤 40종\n요거트젤 물방울 세트\n요커트젤 발레리나 세트\n프롬더네일 셀러브리티 세트\n디보크 화이트나이트 세트\n디보크 그해여름 2 세트\n디젤 드라이로즈 세트\n오로라퀸 글리터 여러개\n개별로 구매한 젤들도 많아요~\n​\n다양한 파츠랑, 파우더, 연장용 팁, 탑젤, 베이스젤, 파츠글루, 젤리무버, 젤클리너, 알코올, 아트진열대, 스티커도 등 ~\n​\n​\n​",
