    "summary": "애정으로 운영하던 두정역 근처 샵 내놓습니다. ​ ​이사 문제로 정들었던 샵을 정리하게 되어 글 올립니다. ​ 두정역 근처라 다른 지역 손님들도 찾아오기 편하다고 좋아하셨고, 건물 바로 앞에 버스정류장도 있어서 유동인구랑 교통은 정말 괜찮은 자리예요. ​ ​ ​ ​근처에 대형 아파트 단",
    "body": "애정으로 운영하던 두정역 근처 샵 내놓습니다.\n​\n​이사 문제로 정들었던 샵을 정리하게 되어 글 올립니다.\n​\n두정역 근처라 다른 지역 손님들도 찾아오기 편하다고 좋아하셨고, 건물 바로 앞에 버스정류장도 있어서 유동인구랑 교통은 정말 괜찮은 자리예요.\n​\n​\n​\n​근처에 대형 아파트 단지도 있고, 뒤쪽으로는 원룸이랑 오피스텔이 끼고 있어서 단골 확보하시기 좋을 거예요.\n​\n대부분 물건은 놓고 갈꺼라 오셔서 바로 운영가능합니다!\n​\n​\n​\n​구조: 관리룸 4개 / 탕비실 1개\n보증금: 1000/80\n평수: 19평\n권리금은 유선 문의주세요!\n주차 가능\n​\n​특징: 현재 룸 1개는 샵인샵 운영 중이라 임대료 부담 덜면서 시작하실 수 있습니다.\n​\n​ 상세한 내용이나 권리금 궁금하신 분들은 연락주시면 자세히 설명해 드릴게요!\n샵보시고 마음에 드시면 권리금 많이 조율해드릴꺼에요\n연락주세요^^\n010-55구팔-7344\n​\n​",
