    "body": "🔶️강남 논현역 도보1분 초역세권 뷰티샵 양도합니다🔶️\n논현역 9번 출구 도보1분 초역세권\n보증금 1,200만원 / 월세 130만원\n관리비 없음 / 소액 시설 권리금 있음 협의 가능\n​\n▪️ 근린생활시설 (간이사업자 가능)\n▪️ 약 10평\n▪️ 2룸 구조라서 샵인샵 가능한구조\n▪️ 입주날짜 협의가능\n​\n✔️ 권리금 포함 내역\n▪ 100만원 상당의 온열가능 전동베드 1개\n▪ 일반 온열 평베드 1개\n▪ 시술 의자 1개\n▪ 냉난방기(새것설치했음)\n▪ 카운터, 서랍장 등 집기 모두\n▪ 전자렌지, 냉장고, 프린터\n▪ 식물, 화분, 도자기, 액자\n※개인 물품 및 시술 트레이 정도만 가져가며\n그 외 매장에 있는 집기 및 인테리어는 대부분 그대로 두고 갑니다.\n​\n현재 속눈썹매장으로 운영 중이며\n인테리어가 모두 되어 있어 별도 공사 없이 바로 영업 가능합니다. 1인 뷰티샵으로 사용하기 좋은 공간입니다.\n​\n특히 공간이 2룸으로 분리되어 있어 샵인샵 운영이 가능합니다.\n현재도 1년 내내 샵인샵을 함께 운영하고 있으며\n샵인샵 비용으로 월세의 약 절반 정도를 충당하고 있어\n고정비 부담을 줄이면서 운영하기 좋은 매장입니다.\n​\n또한 매장 내부에 단독 화장실이 있어\n공용 또는 외부 화장실을 불편해하시는\n여성 고객분들을 응대하기에도 큰 장점이 있습니다.\n​\n논현역에서 도보 1분 거리라 처음 방문하시는 고객분들도 찾아오기 쉽고, 주변에 회사와 상업시설이 밀집해 있어 유동인구가 많은 상권입니다.\n​\n✔ 논현역 도보1분 초역세권\n✔ 월세 130만원 / 관리비없음\n✔ 뷰티샵 인테리어 완비\n✔ 내부 단독화장실\n✔ 2룸 구조 / 샵인샵 가능\n✔ 대기실 수도 별도 연결\n✔ 냉난방기 및 집기 포함\n✔ 권리금 협의 가능\n​\n계약은 건물 전속 부동산을 통해 안전하게 진행합니다.\n현재 영업 중인 매장이라\n구체적인 위치 및 권리금은 문의 주시면 안내드겠습니다 :)\n📞문의 : 010-2370-0533\nPrevious image\nNext image\n​",
