    "summary": "그동안 좋은 인연으로 함께해 주신 원장님께서 출산을 앞두고 계셔서 공석이 생겼습니다. 새롭게 함께하실 샵인샵 선생님을 모시게 되었습니다. ​ 각각의 사업장이니 서로 배려하고 존중하며 편안한 분위기 속에서 함께할 수 있으신 원장님들께서 문의주셨으면 좋겠습니다. ​ ​ 망원역 2번출구 도보",
    "body": "그동안 좋은 인연으로 함께해 주신 원장님께서 출산을 앞두고 계셔서 공석이 생겼습니다.\n새롭게 함께하실 샵인샵 선생님을 모시게 되었습니다.\n​\n각각의 사업장이니 서로 배려하고 존중하며 편안한 분위기 속에서 함께할 수 있으신 원장님들께서 문의주셨으면 좋겠습니다.\n​\n​\n망원역 2번출구 도보5분거리 위치\n보증금120만 월40만 , 추가금 일절 없어요!\n사업자 원할시 보증금120만 월45만 추가금없습니다!\n​\n제메인은 속눈썹연장입니다.\n개인사업이니 물론 터치 전혀없고요 날짜 시간 자유롭게 ㅂㅇㄱ, 속눈썹펌 연장, smp , 왁싱, 에스테틱 등 원장님의 장기를 맘껏뽐내세요\n​\n개인방은 아니지만 고급진 커튼으로 분리해놨고\n사진상 없는 다른방이 또 있어 식사를하셔도 되고 쉬셔도되세요 :)\n​\n- 베드는 2개이고 커튼으로 분리되어있습니다- 총3명의 원장이 공유어플을 통해 진행하니 베드쉐어라고 생각하시면 되요!!!\n거의 고정적으로 주사용 베드쓰시더라고요- 제가 샵에 출근하는 날이 매우 적어 타원장님들께서 손님놓친적 없습니다\n- 건물내 주차안되요 주변 공영주차장 1분거리에 있어요\n- 사업자 원하실시 3개월뒤 가능하세요 제가 메이크업으로 내서 다른업종으로 하시면 되셔요\n- 스마트플레이스 만드실때 제 사업자필요하시던데 당연히 해드립니다!\n- 샵계약은 3개월,6개월 원하시는 쪽으로 계약하세요\n-26년 12월 5일 부터 가능하세요\n​\n010 2112 9690\nGENIEBROW: 지니브로우\nhttps://open.kakao.com/o/smb8nu5f\n​",
