    "summary": "​ ​ 실제로 보는게 훨씬 예쁜 공간입니다 : ) ​ ⭐️최대한 빨리 들어오실 원장님⭐️ ​ 처음 샵인을 시작해보시는 원장님들도 부담없이 자리 잡기 좋은 공간입니다 : ) 경험삼아 시작해 보시기에도 좋은 기회일 것 같아요 ◡̈ ​ * 네이버 플레이스 등록 가능 ​ 인테리어는 이미 예쁘게",
    "body": "​\n​\n실제로 보는게 훨씬 예쁜 공간입니다 : )\n​\n⭐️최대한 빨리 들어오실 원장님⭐️\n​\n처음 샵인을 시작해보시는 원장님들도\n부담없이 자리 잡기 좋은 공간입니다 : )\n경험삼아 시작해 보시기에도\n좋은 기회일 것 같아요 ◡̈\n​\n* 네이버 플레이스 등록 가능\n​\n인테리어는 이미 예쁘게 되어 있어서\n따로 손보실 부분 없이 바로 사용하시면 되고,\n창가가 바로 있어서 자연광이 좋아\n사진도 정말 잘 나옵니다 : )\n​\n방문하시는 분들도 공간 예쁘다고\n많이 좋아해 주시는 분위기예요🥰\n​\n시끌벅적한 샵이 아니라\n대체로 차분하고 조용한 분위기라\n편하게 사용하시기 좋습니다 !\n​\n위치도 대로변에 있고 지하철역이랑 가까워서\n접근성이 정말 좋아요.\n​\n룸은 약 2평 정도 되는 단독룸이라\n테이블, 수납장 등 아주 충분히 배치 가능하고\n실제로 보시면 사진보다 더 넓습니다 !\n​\n🅿️ 주차 지하 7층까지 가능\n고객님 1시간 30분 무료주차 가능\n​* 월주차 한대 무료 등록 가능 *\n​\n처음 시작하셔서 경력 쌓거나 하시는 원장님들이\n사용하기 좋으실 것 같아요!\n​\n📲 문의는 카톡으로\n카톡 : ds0504\n​\n상가주소 : 신중동역 3번출구 도보4분 (위치좋음)\n모집종목 : ㅂㅇㄱ / 속눈썹 연장\n계약기간 : 3개월~연장\n보증금/월세 : 50 / 45\n관리비 : 월세에포함\n제공시설집기 : 베드 / 테이블 / 의자\n해당층/전체층 : 3층\n문의(댓글/쪽지/문자) : 카톡 ds0504\n​",
