    "summary": "🤍 피부관리 선생님 모십니다 🤍 ​ 안녕하세요 현재 원장 외 네일 실장님 총 2인으로 네일,속눈썹 등등 토탈 뷰티샵으로 운영중인데 손님들이 피부는 왜 안하냐고 마사지 관련 등등 피부를 너무 찾으셔서...😢 ​ 저희 샵은 분위기가 참 좋습니다! 고객님들이 대부분 너무 착하시고 유머러스 하",
    "body": "🤍 피부관리 선생님 모십니다 🤍\n​\n안녕하세요 현재 원장 외 네일 실장님 총 2인으로\n네일,속눈썹 등등 토탈 뷰티샵으로 운영중인데\n손님들이 피부는 왜 안하냐고 마사지 관련 등등\n피부를 너무 찾으셔서...😢\n​\n저희 샵은 분위기가 참 좋습니다!\n고객님들이 대부분 너무 착하시고 유머러스 하셔서\n편안한 분위기에서 고객님들과 인연을 쌓아 갈 수 있으셔요💕\n​\n본인의 예약 일정에 맞춰 유연하게 출퇴근 하고픈 분,\n특히나 혼자 시작하기 막막하신 분들이나 오래 쉬어 다시 커리어를 쌓고 싶은분들, 높은 초기 비용과 고정비가 부담 되시는 분들께 좋은 기회가 될 수 있을 것 같아요😊 저희 손님 밀어드리고 같이 홍보해 드려요\n​\n궁금한 점 편하게 물어보시구 둘러보러만 오셔도 괜찮습니다😉\n시설 및 세부운영 조건은 편하게 문의 주시면 알려드리겠습니다\n​\n✨️보증금 50 / 25\n비품이용 및 전기세 수도세 등등 포함 이용금액\n현재 전동베드 1대 , 온열베드 1대 있습니다\n평수가 20평대가 넘어서 실물로 보시면 룸이 꽤 커서 만족하실 거에요 ㅎㅎ 주차는 가게 앞에 바로 가능합니다\n010.삼공5이.2060\n​\n인스타:리즈뷰티 치면 파란로고 나옵니다\n​\n입점하시게 되면 피부선생님은 무료로 네일 또는 속눈썹연장이나 펌 필요시 시술해 드려요 ㅎㅎ\n베드 대여만도 하니 편하게 문의주세요 ㅎㅎ\n단독 룸 입니다\n​\n​",
