    "body": "업종종목 : 네일아트\n​\n소재지 : 왕십리 한양대 마장\n​\n매물가격 : 100/90\n​\n권리금 : 3,500\n​\n실평수 : 8\n​\n해당층 / 전체층 : 1층 주차가능\n​\n입주가능일 : 협의\n​\n문의 연락처 : 010-8008-2015\n​\n-- 매물 상세설명 --\n📢 네일샵 양도합니다 🤍\n개인 사정으로 운영 중인 네일샵을 양도합니다.\n인테리어부터 바닥 및 기본 시설까지 갖춰져 있어, 새롭게 인테리어를 하거나 큰 준비 과정을 거치지 않고 바로 영업을 시작하실 수 있는 샵입니다 :)\n✨ ​\n✔️ 인테리어 및 바닥 시설 완비\n✔️ 기본적인 샵 시설이 갖춰져 있어 초기 창업 비용 절감 가능\n✔️ 공간 분리 커튼 설치 및 시술 베드 구비\n✔️ 네일 시술뿐 아니라 속눈썹 펌 시술도 가능\n✔️ 네일과 속눈썹을 함께 운영하고 싶으신 분들께 추천!\n권리금 3,500\n인테리어와 시설을 새롭게 준비하는 데 드는 비용과 시간을 줄일 수 있으며, 기존 시설을 활용해 바로 운영하실 수 있습니다.\n샵 운영에 필요한 기본적인 환경이 갖춰져 있어 네일샵 창업을 준비하시는 분이나 기존 네일·속눈썹 고객을 함께 확보하며 운영하고 싶으신 분들께 좋은 기회라고 생각합니다.\n📸 사진은 샵 초창기에 촬영한 사진으로, 현재 내부 모습과 일부 차이가 있을 수 있습니다.\n관심 있으신 분들은 편하게 문의 주세요 🤍",
