    "body": "업종 네일 (속눈썹,왁싱(샵인) / 에스테틱(샵인)\n주소 강남구 역삼동 (2호선, 수인분당선 선릉역 도보3분)\n해당층 / 전체층 : 2층/4층 주차1대 가능\n권리금 1500\n매물가격 / 월세 2000/286(관리비포함)/수도전기별도\n(샵인월세 -140)\n실평수 20평\n입주가능 / 날짜 9-10월 예정 협의가능\n연락처 010-9319-1126\n​\n​\n​\n네일3인테이블, 페디2인단상, 데스크, 온장고, 소독기, 조명, 시스템에어컨(샵인공간에도 벽걸이에어컨1대), 대기석, 테이블, cctv, 세탁기, 미니건조기, 탕비실-냉장고, 전자레인지, 식탁, 정수기(약정끝 명의 넘겨드려요), 화장실 엄청 넓습니다! 주차자리 1대 가능해요!!\n​\n각종 집기 다 넘겨드려요, 재료는 협의 가능합니다!\n​\n선생님 두분과 저 3인으로 운영했고,\n신규 유입 잘되고 고정손님 잘 잡혀있습니다!\n​\n저희도 원래 뷰티샵이었던 자리를 인수해서 이곳에서 4년가량 운영했으나, 이사 및 출산으로 인해 아쉽게 샵을 정리 하려 합니다\n​\n인테리어 깨끗하게 잘 되어 있고 속눈썹 샵인샵 원장님 오픈부터 4년째, 피부샵인샵 원장님 현재 1년 이상 함께 하고 계세요\n​\n근처에 회사가 많고 주택가도 있어서 역삼, 선정릉에서도 많이 찾아오세요! 2~30대 젊으신분들이고 아트 많이 하세요\n​\n맞은편, 옆건물에 네일샵있어도 자리가 잘 잡혀 있는 샵입니다!\n​\n샵인샵 월세로 주변 샵 대비 월세도 많이 세이브 돼요\n건물주와 협의되어 샵인샵까지 각자 사업자등록 되어있습니다\n​\n권리금은 저희가 내고 들어온 딱 그만큼만 받을 거라\n찔러보실 분들은 정중히 사양합니다\n​\n문자 주시면 샵 사진, 플레이스나 인스타 더 보여 드릴 수 있고 실제로 샵 보러오시면 권리금 비싸다 생각 하시지 않을 거에요~!\n​\n시술 중일 수 있으니 문자로 먼저 연락 부탁드립니다!",
