    "body": "안녕하세요,\n수원시청역 가구거리 속눈썹샵 매매 합니다.\n​\n사업자 등록 가능하며, PC와 개인물품을 제외한 전체 물품 매매 진행하려고 합니다.\n자세한 내용은 아래 확인 부탁드리겠습니다~\n​\n1. 매장 정보\n- 위치 : 수원시청역 1번 출구 도보 7분 거리\n- 평수/층 : 6.4평 / 3층\n- 내부 화장실\n- 근린생활시설\n- 현재 업종 : 뷰티샵 / 1인샵 / 예약제 운영\n- 입주 가능일 : 협의 가능\n​\n2. 임대 조건\n- 보증금 : 500만원\n- 월세 : 55만원 / 세금포함 60.5만원\n- 관리비 : 월 10만원\n- 권리금 : 150만원 (고객정보 미포함)\n​\n3. 관리비 및 공과금\n- 티비수신료 : 4,000원-7,000원대\n- 가스료 : 6,000원-15,000원대\n​\n4. 주차\n- 주차 무료, 상가 앞 및 지하 주차장 센서 카드키 이용\n​\n5. 매장 설명\n✔ 수원시청역 1번 출구 도보 5분, 접근성 좋음\n✔ 역세권으로 유동인구가 많은 편\n✔ 건너편은 번화가, 3층으로 외부소음 인입량 적음\n✔ 20~30대 고객층이 주를 이루는 상권이나, 40-50대 고객유동 많은 편\n✔ 약 5년간 운영하며 큰 문제 없이 안정적으로 운영\n✔ 임대인분이 친절하시고 소통이 원활해 편하게 운영 가능\n​\n6. 시설 및 비품\n- KT 인터넷 사용 중\n- 냉·난방기 / 발 난로\n- 실외 철제 배너 거치대\n- 조명\n- 피부 평베드 2개 + 의자 + 베드이불커버 + 베드비닐커버\n- 접이식 테이블 스툴\n- 이불 + 베게\n- 책상\n- 트롤리\n- 청소기\n- 세면대 수전 거울\n- 커튼\n- 행거\n- 신발장\n- 소독기\n- 액자 거치대\n- 기타 소모품 포함\n​\n7. 제외 품목\n- 노트북 밑 본체\n- 모니터\n- 블루투스 스피커\n- 트롤리\n- 단말기\n- 공기청정기\n- 프린터\n​\n관심 있으신 분들은 편하게 댓글 주십시오.\n궁금하신 부분은 최대한 자세히 안내드리겠습니다 :)\n​\n시술 중에는 통화가 어려워, 오픈채팅방으로 문의주시면 감사하겠습니다.\n​\nsusu\nhttps://open.kakao.com/o/sKSho41d",
