    "body": "(대구남구 앞산네거리.현충로역부근) !찾아요!!룸방샵인원장님구합니다!\n​\n​\n➿️➰️샵인샵➰️➿️\n​\n2번룸급구(당장입주가능)\n✔️1년이어려울시에는\n(최대8개월이구요.그뒤로.6개월씩연장입니당\n퇴실시에는.미리3개월전말씀해주셔야되구요\n통보안됩니다!!!!!)\n​\n개인샵오픈.운영으로.\n입주하실.룸샵원장님을\n찾습니다(오래오래있으실분~)\n지역은대구에요(대명동.남도초등학교근처)\n현충로역1번출구.도보5분거리.(앞산네거리)\n버스정류장.있구요.\n주차가능하시공~\n출근자유\n퇴근은pm10까지(최대)\n뻘근날영업하셔두되시고\n​\n여름(풀에어컨빵빵)\n겨울(난방.아주따뜻하게)\n​\n별그램홍보해드리공\n당ㄱ링크잇으시면.도와드려요\n​\n우리샵의혜택은\n노터치입니다\n입주해있으신.원장님들과.인사주고받기^^\n네일입구메인자리♡\n저희샵은.남자네일선생님계셔요^^\n여자분.남자분^^최근\n네일샵원장님들두분이입주해주셔서^^\n샵이아주뜨겁습니다^^\n서로서로윈윈되니.\n빠르게입주바랍니당♡\n그리고젤중요한사항\n보300월35만\n이외에별도추가없습니다.\n월세외에는.안받아용^^\n1년위주계약합니다.\n중도영업중이시다가\n갑작스럽게\n나가시는경우에는(본인사정)\n서로매너상.지켜주시구요\n​\n미리3개월전.통보해주시고\n자세한건.상담으로하면될듯합니다\n​\n(전대차x)(카드단말기ok)(ㄴㅇㅂㅍㄹㅇㅅ.X)\n(이글잘보시고.문의주세요.)\n입주하실분만.메세지부터\n매너문자주시고.통화상담하고.\n방문여부하시면될듯합니다.\n저희샵은.\n집기는다잇구요\n재료만.들고들어오심될듯해용\n필요하신.집기잇으시면\n구비하시고.인테리어셀프가능하니.\n오셔서.생각해보시면될듯합니다\n​\n언제든지방문가능합니당\n연락주세요\n0 10.5 0ㅣ9.오오오3.입니다.\n메세지가빠르세용\n전화보다\n부재시에는.메세지꼭주세요룸방입주하실분연락주세요!!!\n(ㅂㅇㄱ.연장.펌.smp.왁싱.피부.가능합니다)\n저희샵은.입주해잇는.원장님과.저와.\n종목이겹치셔두.입주해도괜찮다하시는분들만\n문의주세요.\n​\n사진상의.침대배드는있어요\n트레이랑.의자만.구비하심되시고~재료만\n셋팅하심될듯해용\n룸안에는.따로꾸며주심되요~\n감사합니다\n​\n​\n​\n일단문의주시고\n메세지남겨주시면\n빠르게.연락드릴께요.",
