    "summary": "서울 송파구 문정동에서 2021년부터 안정적으로 운영해 온 속눈썹 전문샵 양도합니다 ​ 문정역과 지하 통로로 바로 연결되어 있어 눈, 비 오는날에도 손님들이 오가기 매우 편리하며, 건물 자체가 깔끔하고 주차장까지 잘 되어 있어 방문 만족도가 높은 공간입니다. ​ 5년 동안 애정을 갖고 ",
    "body": "서울 송파구 문정동에서 2021년부터 안정적으로 운영해 온 속눈썹 전문샵 양도합니다\n​\n문정역과 지하 통로로 바로 연결되어 있어 눈, 비 오는날에도 손님들이 오가기 매우 편리하며,\n건물 자체가 깔끔하고 주차장까지 잘 되어 있어 방문 만족도가 높은 공간입니다.\n​\n5년 동안 애정을 갖고 가꿔온 매장이라 단골고객님도 많이 잡혀있지만\n타 지역으로 이사를 가게되어 가게를 내놓게 되었습니다.\n​\n모든 인테리어, 가구, 가전, 기본 집기를 그대로 넘겨드리기 때문에 추가 공사나 준비 없이 몸만 오셔서\n첫날부터 바로 영업 가능합니다. 요즘 인테리어 비용도 많이 인상되었는데 부담없이 가게 오픈하실수있어요\n​\n주변 아파트, 오피스텔, 오피스가 많아서 유동인구도 많고 가게 지하 통로가 연결되어있어\n복잡하지 않고 찾기 쉬우며 위치가 정말 좋습니다\n​\n또 바로 옆에 대형 프렌차이즈 커피점과 편의점이 있으며,건물 지하에 대형 헬스장이 있어서\n워크인 고객님들도 많습니다 자리가 정말 좋아서 직접 위치 보시면 더더욱 만족하실꺼예요\n​\n​\n🏢 매물 기본 정보\n* 위치: 문정역 도보 5분거리\n* 업종: 속눈썹 / 뷰티샵 (동일 업종 강력 추천)\n* 면적: 8.5평, 1층\n* 임대 조건: 보증금 1,000만원 / 월세 100만원 (부가세 별도)\n* 권리금: 500만원 (시설비, 집기 포함)\n* 관리비 : 15만원 ~ 20만원\n* 주차 1대 등록 가능 / 고객 주차 2시간 무료 (4시간까지 가능)\n​\n✨ 매장의 핵심 장점\n초역세권 지하 연결: 문정역 직통 연결로 접근성이 뛰어나 단골 및 신규 고객 유입에 최적입니다.\n깔끔한 건물 관리: 건물 내부 및 주차 시설, 화장실 등이 매우 깨끗하게 관리되고 있습니다.\n​\n📦 포함 집기 내역 (풀세팅)\n시술 베드 2개, 시술 의자 2개, 안내데스크, 의자, 수납장 3개, 사물함 2개, 세면대, 거울, 냉장고, 전자레인지, 거울, 신발장, 대기실테이블+의자, 오방난로 등\n​\n​\n​\n편하게 연락 주세요!\n​\n010 22팔6 9사오오\n​\n시술 중에는 통화가 어려워서 문자 남겨주시면 연락 드리겠습니다!",
