    "summary": "광주 충장로 뷰티샵 양도합니다! ​ ​ 문화전당역앞에 위치하고 있어서 위치아주 좋습니다. ​ 시설 완비되어 있어서 계약후 바로 영업 가능하세요! ​ 속눈썹 반영구 네일 등 하시기 가능한 구조입니다 ​ 18평정도이고 창고도 크게 있어서 물품 보관하기 좋습니다 ​ ​ 조건// 보증금 100",
    "body": "광주 충장로 뷰티샵 양도합니다!\n​\n​\n문화전당역앞에 위치하고 있어서 위치아주 좋습니다.\n​\n시설 완비되어 있어서 계약후 바로 영업 가능하세요!\n​\n속눈썹 반영구 네일 등 하시기 가능한 구조입니다\n​\n18평정도이고 창고도 크게 있어서 물품 보관하기 좋습니다\n​\n​\n조건//\n보증금 1000만원\n월세 40만원\n관리비없음\n수도세만 25000원 나와요!\n권리금 00만원 (협의가능)\n현재 반영구, 속눈썹 샵으로 운영중이며 타지역 이전으로 양도합니다.\n​\n타지역으로 이사가게되어서 가게내놓습니다 ㅠㅠ 근처에서 다시오픈하거나 그러는일없으니 안심하셔도되세요\n​\n인테리어 비용 부담없이 바로 시작하고 싶은분들 !\n​\n월세아주 저렴한편으로 처음시작하시는분들이나 초보 원장님들 운영하기 좋으실거라고 생각해요!\n모르시는점있으시면 알려드릴게용^^\n충장로 주변에 이월세 찾기 힘드실거에요\n오래되신 고객들이 대다수라 현재 고객님들도 인계해 드리면 자리잡으시기 어렵진 않을거예요\n주로 손님연령대는 2-30대 분들이 90프로입니다\n​\n제 개인도구들만 가져가고 나머지 집기들은 다 두고 갑니다 개인도구들만 구비되시면 바로 영업가능하세요!\n천장형 시스템냉난방기 달려있구요\n통창으로 햇빛도 환하게 잘들어와요 !\n열선배드4대 있습니다\n소독기,미니냉장고 기타등등 다준비되어 있습니다 ㅎㅎ\n​\n관심 있으신분들 편하게 문의해주세요^^!\n​\n010 4444 3527\n​\n​\n​\n​\n​",
