    "body": "​\n사창동 메인 사거리\n큰길 바로 뒷 길에 위치한 샵이에요\n​\n전대차 계약 하실거고 사업자 가능해용\n​\n​\n보증금150 / 월세35\n관리비 (1/N)\n​\n​\n오른쪽 룸입니다!\n베드 하나 들어가고\n자세한 사진은 문자 주시면 보내드릴게요\n​\n​\n저는 속눈썹을 주로 하고 있어서\n속눈썹연장 및 펌은 불가능합니다\n​\n가능 종목: 붙임머리/ ㅂㅇㄱ/ smp/ 왁싱/ 네일\n​\n010-5858-931o 문자 주세요 ㅎ.ㅎ\n​\n​\n​\n​\n​\n​",
