    "summary": "업종종목 : 속눈썹펌 속눈썹연장 ㅂㅇㄱ ​ 소재지 : 부천 신중동역 ​ 매물가격 : 300/35 (전기료,수도세 포함) ​ 권리금 : 없음 ​ 실평수 : ​ 해당층 / 전체층 : 1층 ​ 입주가능일 : 협의 ​ 문의 연락처 : 공일공 오팔사육 공공팔육 ​ 신중동역 1층 네일샵 샵인샵 원",
    "body": "업종종목 : 속눈썹펌 속눈썹연장 ㅂㅇㄱ\n​\n소재지 : 부천 신중동역\n​\n매물가격 : 300/35 (전기료,수도세 포함)\n​\n권리금 : 없음\n​\n실평수 :\n​\n해당층 / 전체층 : 1층\n​\n입주가능일 : 협의\n​\n문의 연락처 : 공일공 오팔사육 공공팔육\n​\n신중동역 1층 네일샵 샵인샵 원장님 모집\n​\n속눈썹 연장 · 속눈썹 펌 · 반영구\n​\n안녕하세요.\n부천 신중동역 도보 7분 거리에 위치한 1층 네일샵입니다.\n​\n현재 샵 내 독립된 시술 공간에서 함께 운영하실 속눈썹 연장 / 속눈썹 펌 / 반영구 원장님을 모십니다.\n​\n현재 공간은 사진처럼 시술 베드, 조명, 트레이 등 기본 집기와 시술 공간이 이미 세팅되어 있어 개인 시술 재료만 준비하시면 바로 영업을 시작하실 수 있습니다.\n​\n처음 샵인샵을 시작하시는 분도 별도의 인테리어나 큰 초기비용 부담 없이 시작하기 좋은 환경입니다.\n​\n또한 기존 네일 단골 고객층이 있고 속눈썹 관련 문의도 꾸준히 들어오고 있어 네일 고객과의 자연스러운 고객 연계 및 상호 홍보도 가능합니다.\n​\n✨ 입지 및 상권 장점\n​\n역세권: 신중동역 도보 7분 거리\n접근성 최고: 1층 대로변 위치, 버스 정류장 바로 앞\n풍부한 배후 수요: 아파트 대단지 정문 앞 + 초·중·고등학교 인접으로 유동인구 항시 풍부\n​\n기존 고객 확보: 워킹 손님 및 네일 단골 손님들의 속눈썹 시술 문의 다수 (고객 연계 가능)\n​\n✨ 임대 조건\n​\n보증금 / 월세: 300/35\n관리비: 포함 (전기세, 수도세 등 일체 포함으로 추가 비용 없음)\n계약기간 : 처음 계약 1년 후 3개월 단위로 연장가능\n사업자 등록 必 ( 스마트플레이스 , 광고 , 원하시는대로 하시며, 출퇴근 터치 일절없음)\n​\n자리만 빌려드리는 샵인샵이 아니라, 이미 시술 가능한 공간과 기본 집기가 준비되어 있어 재료만 챙겨 오시면 바로 영업하실 수 있습니다.\n​\n시설이나 공간이 궁금하신 분은 편하게 채팅 주세요.\n사진 보내드리고 자세하게 안내해드리겠습니다.\n​\n좋은 인연 기다리겠습니다. 감사합니다.",
