    "key": 1000,
    "keyTxt": "1,000만",
    "at": "2026-10-07",
    "ts": 1791355031103,
    "summary": "안녕하세요 :) 청라 커낼에비뉴 내 상가 1층에 위치한 뷰티샵 양도합니다. ​저희 샵은 출입구가 앞뒤로 두 곳이에요. 하나는 탁트인 호수공원 뷰, 다른 하나는 넓은 상가 광장과 연결되어 있어서 탁 트인 바깥을 보면서 일할 수 있다는게 일단 큰 장점이라고 생각해요 출근-퇴근까지 매일 계속",
    "body": "안녕하세요 :)\n청라 커낼에비뉴 내 상가 1층에 위치한 뷰티샵 양도합니다.\n​저희 샵은 출입구가 앞뒤로 두 곳이에요.\n하나는 탁트인 호수공원 뷰, 다른 하나는 넓은 상가 광장과 연결되어 있어서 탁 트인 바깥을 보면서 일할 수 있다는게 일단 큰 장점이라고 생각해요\n출근-퇴근까지 매일 계속 샵에 있어야 하는데 예전 샵은 앞뒤로 다닥다닥 붙어있는 상가들 사이에서 커튼쳐놓고 어두운 곳에서 힘들게 일했었던 기억이 나서.. 이번 샵은 그 한을 풀어보고자 오롯이 시술자의 입장에서 꾸며놓은 공간입니다.\n남향 + 테라스 덕분에 하루종일 따뜻한 햇살이 비추는 샵이고,\n자연광 때문에 시술사진도 환하고 뽀얗게 나오는데 이것도 장점 중에 하나입니다\n​\n같은 건물에 대형병원이 들어와있고, 바로 위층엔 카페들이 밀집되어있고\n밑층에는 대형 키즈카페, 올리브영, 종로서적이 있어 젊은 엄마층, 학생, 직장인 등 유입층이 다양한 상권이에요 :)\n특히 공원 및 학군이 가까워 등하교길, 산책길 동선상 저희 샵 앞을 지나갈 수 밖에 없는 곳이기에 지나가시다가 워크인 고객 유입이 높은 편입니다.\n가게 앞에 세워둔 배너를 필수로 보면서 지나가야 하기 때문에 초반에 자리잡기 수월하실거에요. 저도 3년전 처음 이곳에 이사와서 걱정이 많았는데 위치가 좋아서 한달도 안되서 금방 자리잡을 수 있었어요 :)\n​\n현재는 1인샵으로 수강을 겸하며 운영 중이지만, 두 개의 독립된 룸과 넓은 메인 공간이 있어\n속눈썹, 반영구 외에도 네일, 왁싱, 피부 등 다양한 업종 또는 샵인샵 형태로도 충분히 활용 가능하실거라 생각해요 ㅎㅎ\n​\n보증금 2000만원, 월세 120만원이고\n초반에 인테리어 시작할때부터 제가 정성들여서 하나하나 만든 샵이라 어느곳보다 예쁘다고 자부할 수 있습니다.\n인테리어는 3200만원정도 들었구요, 권리금은 인테리어+집기까지 모두 포함해서 1000만원 생각하고 있습니다 :)\n​\n집기포함항목은 아래 참고부탁드립니다.\n온수 세면대 / 냉온정수기 / CCTV 3대 / LED 야외전광판\n상담 테이블 상담 의자 대기 스툴\n전동 시술 베드 일반 시술 베드\n시술 의자 시술 조명 트롤리\n수납장 소독기\n인테리어 조명 전신 거울 제품 진열대\n​\n​\n조율 가능합니다.\n01099426225 문자 문의 부탁드립니다.\n​",
