    "summary": "결혼 준비로 타지역으로 가게 되어 너무 아쉽지만, 소중하게 운영해온 샵을 양도하게 되었습니다. ​ 수유역 1번 출구 도보 5분 거리로 접근성이 좋고, 역세권에 위치해 있어 유동인구도 많은 편입니다. ​ 건너편에는 번화한 상권이 형성되어 있고, 샵이 위치한 쪽은 주택가라 상대적으로 조용하",
    "body": "결혼 준비로 타지역으로 가게 되어 너무 아쉽지만,\n소중하게 운영해온 샵을 양도하게 되었습니다.\n​\n수유역 1번 출구 도보 5분 거리로 접근성이 좋고,\n역세권에 위치해 있어 유동인구도 많은 편입니다.\n​\n건너편에는 번화한 상권이 형성되어 있고,\n샵이 위치한 쪽은 주택가라 상대적으로 조용하고 한적한 분위기예요.\n1층이라 접근성이 좋고, 채광도 좋아 낮 시간대에는 내부가 밝고 쾌적합니다.\n​\n현재까지 3년 정도 운영하면서 인테리어와 시설을 깨끗하게 관리해왔고,\n예약제로 운영하는 1인샵이라 조용하고 프라이빗하게 운영하기 좋습니다.\n​\n20~30대가 주 고객층이며, 40~60대 고객분들도 꾸준히 방문하십니다.\n약 3년간 운영하면서 진상 고객도 거의 없었고, 손에 꼽을 정도입니다!\n그만큼 편안한 분위기에서 운영해 온 샵이에요\n​\n역세권임에도 고정비 부담이 크지 않아, 1인 원장님이 알차게 운영하시기 좋은 매장이라고 생각합니다.\n​\nPrevious image\nNext image\n​\n📍 매장 기본 정보\n- 위치 : 수유역 1번 출구 도보 5분 거리\n- 평수/층 : 6.4평 / 1층\n- 외부 화장실\n- 근린생활시설\n- 현재 업종 : 뷰티샵 / 1인샵 / 예약제 운영\n- 입주 가능일 : 협의 가능\n- 간판 설치 가능\n* 간판 없이 운영했지만 지나가다 배너를 보고 문의주시는 분들도 많습니다.\n​\n​\n💰 임대 조건\n- 보증금 : 500만원\n- 월세 : 50만원\n- 관리비 : 없음\n* 임대인분이 간이과세자라 부가세 없음\n- 권리금 : 1,000만원\n​\n​\n💡관리비 및 공과금\n- 수도세 : 4,000원~9,000원대 / 2개월에 한 번\n(지하 상가와 반반 부담)\n- 전기세 : 봄·가을 2~3만원대 / 여름·겨울 5만원대\n(가장 많이 나왔을 때도 7만원 정도였으며, 1회 있었습니다.)\n​\n🚘 주차 무료, 상가 앞 1대 주차 가능\n​\n​\n🏠 매장 장점\n✔ 수유역 1번 출구 도보 5분, 접근성 좋음\n✔ 1층 매장 + 좋은 채광\n✔ 역세권으로 유동인구가 많은 편\n✔ 건너편은 번화가, 매장 쪽은 주택가라 조용하고 한적한 분위기\n✔ 20~30대 고객층이 주를 이루는 상권\n✔ 약 3년간 운영하며 큰 문제 없이 안정적으로 운영\n✔ 임대인분이 친절하시고 소통이 원활해 편하게 운영 가능\n✔ 냉·난방기 2024년 하반기 교체\n✔ 간판 설치 가능\n✔ 상가 앞 주차 1대 가능\n​\n​\n📹 시설 및 비품\n- 내부 CCTV 2개\n- 외부 CCTV 1개\n- SKT ",
