    "body": "** 룸 1 (베드 있음) **\n-보 300 / 임 50\n-보 200 / 임 60\n- 전기료,수도료 X\n​\n** 룸 2 (베드 없음) **\n-보 300 / 임 50\n-보 200 / 임 60\n- 전기료,수도료 X\n​\n📌 사업자 가능, 출퇴근 및 운영 일체 터치 없음, 임대료 지출 증빙 현금영수증 가능(현금영수증 할 시 입대료 부가세 별도), 계약기간은 시작일로부터 1년(계약 연장 추가로 가능), 입주일 협의 가능\n​\n❤️ 유동 인구가 많은 동네라서 동네장사 느낌 보다는 신규 유입 꾸준히 활발하고 돈 잘 쓰는 외국인들도 많이 와서 기존에 계시던 분들도 잘 되서 확장이전 하신다거 하여 올립니당^^\n신사역인데 잠원동 쪽에 가까워 근처에 뷰티샵이 생각보다 없어서 경쟁이 치열한 편도 아니고 단가 높게 받아도 다들 잘만 다니세용\n제 고객님들도 단골이 대부분이고 위치가 좋아 신규유입도 꾸준히 활발하고 네일이랑 속눈썹 같이 하고 싶어하시는 고객님들이 많아 세트메뉴로 예약 받아서 서로 윈윈 했어용^^\n​\n신사역 위치 특성상 강남, 논현, 잠원, 압구정, 반포, 한남, 학동, 양재 등 근처 강남권에서도 많이 오시지만 신분당선 까지 있는 더블 역세권이라 경기도권 에서도 고객들 많이 유입되어서 자리 금방 잡으실 수 있을 거에용☺️\n​\n위치 기준 현 시세 대비 가장 합리적인 샵인 매물 찾으시는 원장님께 최적의 조건 이라고 자부할 수 있습니다!\n​\n근처 성형외과 근무하시는 분들이나 일반 직장인들도 많고 애버비엔비 이용하는 외국인 고객님들도 많아서 홍보도 어렵지 않고 도와드릴게용^^\n​\n처음 시작하시는 원장님들 대부분 샵 운영 관련하여 잘 모르시는 부분들이 많은데 저도 신사에서 샵인샵으로 시작해서 확장이전 했고 자리 잘 잡혀있는 샵이라 서로 윈윈 하면서 소자본으로 시작해 보실 원장님 모십니다☺️\n​\n관심 있으신 원장님 계시면 문자 남겨주세용^^\n010-4팔오2-구구2팔",
