    "summary": "안녕하세요 ~ 민락 2지구 메인자리에 위치하고 있는 토탈 뷰티샵입니다:) ​ 11년째 한자리에서 속눈썹. 네일.왁싱.ㅂㅇ구 토탈로 운영하고있고 규모있는 샵입니다. ​ 상가를 분양받아 매장 이동을 해야해서 자리잡은 자리지만 아쉽게 양도 하려고 합니다. 10월 말쯤까지 양도인이 없으면 철거",
    "body": "안녕하세요 ~\n민락 2지구 메인자리에 위치하고 있는\n토탈 뷰티샵입니다:)\n​\n11년째 한자리에서 속눈썹. 네일.왁싱.ㅂㅇ구\n토탈로 운영하고있고 규모있는 샵입니다.\n​\n상가를 분양받아 매장 이동을 해야해서\n자리잡은 자리지만 아쉽게 양도 하려고 합니다.\n10월 말쯤까지 양도인이 없으면 철거하려하는데\n자리가 너무 아까워서 생각있으신 원장님은\n최대한 협의해드릴테니 연락부탁드립니다~!\n​\n평수는 대략23평정도 되고\n민락2지구에서 가장 오래되고\n오픈당시 인테리어는 6천만원 투자한 샵입니다.\n​\n관리를 잘해와서 와서 보시면 손볼곳없이 그대로 사용하시면 되세요~\n​\n단골이 많은 샵이여서\n고정매출은 걱정안하셔도 되시구요~\n​\n양도받으신 원장님이 자리 잘 잡으실수있게 원하시면 일주일~한달정도는 손님들 인계잘 해드리고\n​\n직원구하실때까지 도와드릴께요 ^^\n​\n네일 +속눈썹 +ㅂㅇ구 연결되어있는 손님 단위가 많아 인수받는 원장님이 모든 시술\n하실수 있는분이면 매출 안정성있게\n버실수있구요. 네일 고객님도 많아\n샵인이나 직원채용해서 운영하시면 도움이 많이 되실꺼예요~\n​\n오픈때부터 토요일은 10시~6시까지 / 일요일 고정 휴무를 해왔던 곳이라\n공휴일 .주말 휴일 원하시는 원장님도 운영하시기 좋으세요~\n​\n바로 인수가능하시고 편하게 샵보러 오셔도 되시니 연락주세요~\n​\n✨️ 샵 정보\n몸만오시면 되세요!\n다 그대로 양도하고 갈께요!\n​\n간략하게\n•룸 4개 . 베드 5개. 네일코너 별도로있고\n패디룸 분리되어있음\n• 락커시설 . 창가 테이블바. 고객대기 자리.\n큰화장대.세면대 등\n•고급스럽고 깔끔한 인테리어로 바로 영업 가능\n​\n​\n-예약손님으로 인해 오픈전 후다닥 찍은 사진이라\n사진으로 못 찍은곳도 있으니 궁금하시면 연락주세요 ^^\n​\n​\n🌈 월세 및 권리금\n•월세 : 보증금 2000 / 120\n•권리금 : 2000 만원 ( 협의가능 )\n​\n010.2968.5252\n*시술중 연락이 어려울수 있으니 문자 부탁드립니다*\n​\n​",
