    "summary": "✨ 부산 사하구 초역세권 샵인샵 원장님 모십니다 :) ​ 네일,에스테틱,반영구,smp,붙임머리 환영합니다😊 (속눈썹/왁싱 제외하고 모든업종 가능) ​ 📍 당리역 1번 출구 바로 앞 3초 ​ 초초역세권입니다 ! 방 2개 가능 ​ ✔ 25평 넓고 쾌적한 샵 ​ ✔ 사업자등록 가능 ⭐️ ​ ",
    "body": "✨ 부산 사하구 초역세권 샵인샵 원장님 모십니다 :)\n​\n네일,에스테틱,반영구,smp,붙임머리 환영합니다😊\n(속눈썹/왁싱 제외하고 모든업종 가능)\n​\n📍 당리역 1번 출구 바로 앞 3초\n​\n초초역세권입니다 !\n방 2개 가능\n​\n✔ 25평 넓고 쾌적한 샵\n​\n✔ 사업자등록 가능 ⭐️\n​\n(네이버 플레이스 마케팅 빠삭합니다. 궁금하시면 편하게 물어보세요 ㅎㅎ)\n​\n✔ 단독 프라이빗룸 제공\n​\n✔ 네일룸: 네일테이블 / 의자 / 패디쇼파 / 서랍장 / 옷행거 제공 (네일 재료랑 온장고만 들고오세요 😊)\n➡️100/40(관리비없음)\n​\n✔ 베드있는 룸: 베드/의자/라이트/옷헹거/서랍장 제공\n➡️100/40(관리비없음)\n​\n✔ 냉장고 / 정수기 / 고객간식 등 비품 공용 사용 가능\n​\n✔ 출퇴근 터치 전혀 없음!!\n​\n✔ 건물 5층 전체 사용으로 조용하고 편하게 이용 가능\n​\n✔ 바로 옆 유료주차장 있음\n​\n✔ 엘레베이터 O\n​\n✔ 청소 아주머니 계심\n​\n샵주인 저는 속눈썹 전문이고\n기존 고객이 많은 편입니다 :)\n​\n저희 샵에 들어오셨던 샵인샵 원장님들은\n​\n감사하게도 다들 자리 잘 잡고 잘되어서 나가셨어요ㅎㅎ\n​\n그리고 제가 가장 중요하게 생각하는 부분!\n​\n사람 스트레스 없는 샵입니다.\n​\n샵주인 제가 아예 친목 분위기가 생기지 않도록 하고 있어요.\n​\n각자 돈 벌고 일하러 온 자리인 만큼\n​\n불필요하게 모여서 이야기하거나 서로 간섭하는 분위기 없이 각자 자기 고객과 자기 일에만 집중할 수 있는 환경을 만들고 있습니다.\n​\n출퇴근할 때 가볍게 인사하는 정도이고ㅎㅎ\n​\n그 외에는 대화도 거의 없이 모두 조용히 일합니다ㅎㅎ\n​\n혹시 활발한 E성향이시면 저희샵이 조금 심심하실 수도 있지만 🤣\n​\n반대로 사람 관계에 에너지 쓰기 싫고,\n​\n조용히 내 일하면서 돈 벌고 싶으신 원장님께는 정말 편하실 거예요!\n​\n저희도 각자 자리에서 굉장히 열심히 일하고 있어서 비슷하게 일에 집중하시는 원장님이 오시면 서로 정말 잘 맞을 것 같습니다 :)\n​\n함께하실 샵인샵 원장님 기다리겠습니다 🙇‍♀️\n​\n010이삼구팔구구오육\n​\n댓글x 확인이 어려워요 꼭꼭 문자로 연락주세요!!\n​",
