    "summary": "경기광주 태전동 샵인샵, 베드쉐어 들어오실분 구합니다! ​ 속눈썹 반영구 제외한 다른종목 모두 가능해요. (피부관리, 두피, smp, 붙임머리, 왁싱 등) ​ ​ 가벽으로 분리된 180 x 300 공간입니다. ​ 베드, 의자, 더블라인 조명, 트롤리 제공 (사진엔 없어도 위 물품 다 제",
    "body": "경기광주 태전동 샵인샵, 베드쉐어 들어오실분 구합니다!\n​\n속눈썹 반영구 제외한 다른종목 모두 가능해요.\n(피부관리, 두피, smp, 붙임머리, 왁싱 등)\n​\n​\n가벽으로 분리된 180 x 300 공간입니다.\n​\n베드, 의자, 더블라인 조명, 트롤리 제공\n(사진엔 없어도 위 물품 다 제공)\n​\n​\n사업자는 내년부터 가능합니다. 지금 X\n​\n​\n샵인샵\n보증금 100\n월세 관리비포함 45\n​\n베드쉐어\n시간당 2만 최소 3시간부터 가능\n하루종일 10만원\n주말(토,일)만 고정 한달 40만원\n​\n​\n01082350238\n문자로 연락주세요 ^^\n​\n궁금한거 편히 물어보셔도 돼요~\n다만 보러 온다고 약속하시고 노쇼! 하는분들 넘 많아서... 꼭 필요하시고 관심있으신 분들 연락 주셨으면 좋겠어요.\n​",
