    "summary": "​ 안녕하세요! 하남 미사지구에서 성황리에 운영 중인 뷰티 토탈샵 입니다. 현재 네일 / 속눈썹펌 / ㅂㅇㄱ 세개의 라인업으로 탄탄한 기존 고객층을 보유하고 있습니다. ​ ​ 📍 모집 분야 -왁싱쌤(샤워실 O) 우대, -스포츠마사지(에스테틱은 네일때문에 시끄러워서 힘드실거예요) -두피s",
    "body": "​\n안녕하세요!\n하남 미사지구에서 성황리에 운영 중인 뷰티 토탈샵 입니다.\n현재 네일 / 속눈썹펌 / ㅂㅇㄱ 세개의 라인업으로 탄탄한 기존 고객층을 보유하고 있습니다.\n​\n​\n📍 모집 분야\n-왁싱쌤(샤워실 O) 우대,\n-스포츠마사지(에스테틱은 네일때문에 시끄러워서 힘드실거예요)\n-두피smp\n*기존 종목(네일, 속눈썹펌)과 중복되지 않는 뷰티 위 세종목 (다른 뷰티종목도 겹치지 않는 선이시라면 문의주세요!)\n​\n➡️샵인샵 조건/제공물품\n•📍 제공 공간: 여닫이문 있는 단독 베드룸 1실 (프라이빗 룸+샤워실), 4평\n​\n•📍 보증금 50만 월세50만/ 관리비및 소모비품비5만\n(관리비+공용 대기실 및 탕비실 소모비품비 포함)\n: 출퇴근 터치No! 아침,저녁,새벽 상관X, 자유롭게 이용하세요!\n​\n•📍 제공되는 집기류(필요없는 물품 빼드려요):\n-수동 높이조절가능 평베드 + 시술의자\n-미용의자(수동으로 270도 각도조절 가능)\n-2인용 사물함\n-수납장\n-4단 스탠드선반\n-스탠드 옷걸이\n-보스스피커\n-인테리어전자시계\n-반달조명\n-미니온장고\n-uv소독기\n-모션센서 벽걸이선풍기\n-왁싱 부자재들(방수침대시트 포함한 왁싱용 각종 1회용품, 왁싱가림막,허리베개 포함)\n​\n​\n&#x3D; 개인 물품/트레이만 구비하면 당일에 바로 손님 맞이 가능!\n​\n•📍2인용 식탁의자가 방안에 있어 개인공간에서 손님상담가능!!!(방이 비좁다 생각하시면 빼드릴게요)\n​\n​\n​\n​\n📍📍숍 위치 및 인프라\n​\n• 주소:5호선 미사역 도보3분거리, 굉장히 찾기쉽고, 접근성이 매우 좋은 위치에 자리함\n​\n• 기존 고객님들 예약이 활발하여 입점 초기에도 샵인 다른 기존 고객 연계 유리\n​\n•사업자등록 가능\n​\n•고객님/원장님 주차등록 5시간 10분까지 가능: 원장님 고객 주차권은 원장님이 직접 개인구매\n(원장님 개인차량은 등록불가: 상담을 통해 가능할수도 있으나, 매월7만원 건물에 내야함)\n​\n•휴게실(탕비실)이 작지만 충분히 꾸며져있는편. 누구의 눈치도 보시지 않고 누워서 쉬실수 있음. 주무셔도됨!\n​\n​\n​\n​\n​\n우선 직접보시면 아주 마음에 드실거에요☺!\n편하게 연락주시고 방문해주세요!\n​\n​\n010-5칠0공-1이삼6\n010-이5삼사-구구6육\n​\n​",
