    "summary": "📍 파주 야당역 중심상가 / 22평 샵인샵 구합니다 ​ 야당역 바로 앞, 운정신도시에서도 유동인구가 많고 상권이 활발한 중심상가에 위치한 22평 매장입니다. ​ 현재 내부에 관리룸이 총 3개 있어 피부관리, 속눈썹, 왁싱, 네일, 반영구, 마사지, 두피관리 등 뷰티업종 샵인샵으로 들어오",
    "body": "📍 파주 야당역 중심상가 / 22평 샵인샵 구합니다\n​\n야당역 바로 앞, 운정신도시에서도 유동인구가 많고 상권이 활발한 중심상가에 위치한 22평 매장입니다.\n​\n현재 내부에 관리룸이 총 3개 있어\n피부관리, 속눈썹, 왁싱, 네일, 반영구, 마사지, 두피관리 등 뷰티업종 샵인샵으로 들어오실 분을 구하고 있습니다.\n​\n매장 전체적인 분위기가 따뜻하고 아늑하게 꾸며져 있어, 고객분들이 들어오셨을 때 편안하고 고급스러운 느낌을 받을 수 있는 공간입니다.\n뷰티·힐링 업종과 특히 잘 어울리는 분위기라 큰 인테리어 부담 없이 바로 운영하기 좋습니다.\n​\n또 하나의 가장 큰 장점은 위치와 주차예요.\n​\n야당역에서 걸어서 바로 올 수 있는 거리이고, 주변에 식당·카페·상가가 밀집되어 있어 평일과 주말 모두 유동인구가 많은 편입니다.\n​\n특히 야당역 주변에서 샵을 운영하다 보면 고객분들이 가장 불편해하시는 부분이 주차인데, 이곳은 주차장이 굉장히 넓고 고객 주차까지 가능해서 차량 이용 고객을 받기 정말 편합니다.\n​\n✔️ 넓은 관리룸 2곳\n​\n* 베드 2개까지 들어가는 넉넉한 크기\n* 보증금 300만원 / 월 65만원\n* 관리비 + 고객 주차 포함\n​\n두 공간 중\n한 곳은 조명이 조금 차분하고 굉장히 아늑한 분위기라 마사지·두피·힐링 관리처럼 프라이빗하게 운영하는 업종과 잘 어울리고,\n다른 한 곳은 밝고 개방감 있는 공간이라 피부·반영구,속눈썹 등등 뷰티 관리샵으로 활용하기 좋습니다.\n​\n✔️ 1인 관리룸 1곳\n​\n* 베드 1개 들어가는 아담한 공간\n* 보증금 200만원 / 월 45만원\n* 관리비 + 고객 주차 포함\n​\n그리고 저희가 바로 옆에서 별도의 샵을 운영하고 있고 기존 고객님들도 많이 보유하고 있습니다.\n​\n업종이 겹치지 않는 선에서는 저희 고객님들께 자연스럽게 소개하거나 연결해드릴 수 있다는 점도 샵인샵으로 들어오시는 분들에게 큰 장점입니다.\n​\n혼자 처음 샵을 시작하시거나, 큰 보증금과 월세 부담 없이 야당역 좋은 상권에서 내 공간을 만들어보고 싶은 분께 특히 추천드립니다.\n​\n현재는 우선 샵인샵 입점하실 분을 구하고 있습니다.\n​\n다만 전체 매장이 22평이며 무권리로 인수도 가능하기 때문에, 샵인샵이 아닌 매장 전체 인수에 관심 있으신 분도 편하게 연락 주세요.\n​\n위치, 주차, 상권, 공간 분위기까지 직접 보시면 더 마음에 드실 거예요 :)\n진지하게 알아보시는 분은 댓글 또는 쪽지 주세요.\n​\n방은 관심있으셔서 ",
