    "body": "서울 성동구 용답동 로데오거리 중심 에 위치한 토탈뷰티샵에서\n함께 오래하실 원장님 한 분 을 모십니다. 🤍\n​\n📍 매장 정보\n업종: 스킨 · 바디 · 붙임머리 · 반영구 등 뷰티 관련 업종\n위치: 서울 성동구 용답동\n층수: 2층\n보증금 / 월세: 100 / 50\n관리비: 없음\n권리금: 없음\n입주: 즉시 가능\n사업자: 별도 운영 가능\n​\n🚇 좋은 입지\n5호선 답십리역 도보 약 3분\n2호선 용답역 도보 약 3분\n용답동 로데오거리 중심에 위치\n주변 아파트 단지 다수\n인근 3분거리 1,670세대 규모 아파트 내년2월 입주 예정\n답십리역 인근 청년주택 신규 입주 예정으로 향후 유동인구 증가 기대\n​\n💅 현재 운영 중인 업종\n​\n네일\n패디\n속눈썹 펌·연장\n왁싱\n등의 뷰티 서비스를 운영하고 있습니다.\n원장님께서 원하시는 스킨·바디·붙임머리·반영구 등 뷰티 관련 업종으로 입점 가능 합니다.\n​\n📱 네이버 플레이스 홍보 지원\n​\n샵 내 네이버 플레이스 예약 운영이 가능 하며,\n원하시는 경우 매장 홍보도 함께 도와드립니다.\n서로 믿고 단기간이 아닌 오래 함께하실 원장님 을 찾고 있습니다.\n신중하게 고민해보신 후, 실제 입점 의사가 있으신 분들의 연락을 기다립니다. ◡̈\n가능하면 방문 상담을 우선 으로 진행하고 있습니다.\n문의하실 때는\n**「원하시는 업종 + 간단한 소개」**를 문자로 먼저 보내주세요.\n​\n📞 문의: 010-5558-7454\n​\n감사합니다. 🤍",
