    "summary": "선릉역 뷰티크나인 네일 샵인샵 구합니다. ​ 현재는 네일샵 운영 중이시고 9/1일 들어오실 수 있습니다. 확장이전으로 나가게 되어 새로 샵인샵을 구하게 되었습니다. ​ 이 전 네일원장님도 2년 넘게 함께하시고 확장이전, 이번 원장님도 2년 정도 함께하시고 확장이전 하셨습니다. 기존 고객",
    "body": "선릉역 뷰티크나인 네일 샵인샵 구합니다.\n​\n현재는 네일샵 운영 중이시고\n9/1일 들어오실 수 있습니다.\n확장이전으로 나가게 되어 새로 샵인샵을 구하게 되었습니다.\n​\n이 전 네일원장님도 2년 넘게 함께하시고 확장이전,\n이번 원장님도 2년 정도 함께하시고 확장이전 하셨습니다.\n기존 고객님들도 네일 샵인샵이 있는 것을 다 알고 계셔서\n많이들 물어보시고 연결해드리고 있습니다.\n​\n개별 룸 공간으로 출퇴근 터치 절대 없습니다!\n​\n종목은 네일샵만 가능하며 다른 종목은 불가합니다.\n( 패디플래닝등 손, 발 관련된 시술은 모두 가능 )\n​\n처음 인테리어 때부터 네일 샵인샵을 염두해두고\n만든 룸이기 때문에 샵 내부에서 빛이 가장 잘 들어오는 공간이며\n테이블, 선반, 하부장 미리 만들어져있습니다.\n( 패디 의자 등은 물론 직접 가지고 오셔야합니다! 기본만 세팅 )\n​\n저희샵은 주말도 오픈 하기 때문에 토,일 모두 영업하셔도 됩니다.\n​\n-사진은 입주전 사진이며 현재 네일샵인 있습니다.\n지금 네일샵으로 꾸며져있으신데 오셔서 언제든 보셔도 된다고 하시나\n저희도 예약제이기 때문에 시간 조율 후 방문 가능합니다 !\n(사진 왼쪽이 패디의자 올릴 하부장, 오른쪽은 네일 테이블 , 가장 오른쪽에 서랍할 곳들있고 벽쪽에도 네일이나 이달의 아트 진열가능하게 해두었습니다. 365일 일정하게 불켜지고 꺼지도록 자동 센서 있어서 출퇴근 걱정 오히려 덜하실거에요)\n​\n보증금300 월세 60 /관리비 5\n전대차 가능\n​\n바로입주 가능\n​\n010-6682-이육육사 시술 중 통화가 어려울 수 있으니, 문자로 연락주세요!\n​",
