    "body": "[속눈썹샵인샵] 부천 샵인샵 원장님 모십니다\n​\n대형 아파트단지 스타필드쪽 옥길동에 위치한 왁싱샵\n​\n입니다,A,B,C동까지 있는 상가 CGV ,싸우나,스벅\n​\n병원,휘트니스까지 없는게 없어 유동인구 많구요\n​\n샵오픈전 미리 경력이나 경험 쌇고 싶으신 원장님들\n​\n부담없이 샵인으로 시작하셔요\n​\n​\n​\n주종목은 현재 왁싱이랑 네일 같이하고 있구요\n​\n​\n속눈썹 하시다 잘 되셔서 개인샵 하신다고\n​\n또 다시 으샤으샤 함께 하실 원장님을 구합니다\n​\n​\n바로 입주 가능하시구요\n​\n​\n메이크업등 다양하게 가능하십니다.\n​\n​\n전동베드나 기본적인건 다 있구요 필요하신 종목 재료만 가지구 오심 바로가능\n​\n​\n나이나 경력유무는 상관 없구요\n​\n​\n함께 윈윈 하실분 환영해요🤗\n​\n​\n​\n✅️계약기간 1년\n​\n​\n​\n✅️출퇴근 자유 터치×\n​\n​\n​\n✅️보증금100 월세30 관리비 N/3\n​\n월40도 안나옴\n​\n✅️무료주차4시간\n​\n​\n​\n✅️사업자 가능\n​\n​\n​\n⬇️부담 없이 문의 주세용\n​\n​\n​\n010 오삼삼팔 3663\n​",
