    "body": "안녕하세요 :)\n​\n제가 월~목에는 샵에 없어서, 그 요일에 샵을 편하게 쓰실 분을 구합니다.\n​\n위치\n죽전동 내대지마을 메인대로변 위치\n주차 가능하나 만차로 불가시 대로변 공영주차장 이용해야함\n주변 대단지 아파트 다수\n​\n금액\n보증금 25 / 월세 25 (관리비 1/2)\n1달 단위 계약\n단기 이용도 가능: 3시간 4만원 / 1일 7만원\n사업자는 불가해요.\n​\n이용 시간\n월·화·수·목: 샵 단독 사용 가능\n금·토·일: 원칙적으로 사용 불가하지만, 제 예약이 없는 시간은 미리 조율해서 사용 가능\n​\n샵 소개\n약 7평의 화이트톤 인테리어의 깔끔한 1:1 프라이빗 샵입니다.\n냉난방 가능\n혼자 조용히 연습하기 좋은 공간입니다.\n주력은 말 못할 종목+속눈썹펌이지만, 종목이 겹치셔도 괜찮습니다.\n베드, 시술용의자, 트롤리, 조명, 상담책상, 신발정리함, 옷걸이행거 등 제공\n​\n이런 분 환영합니다\n내 공간처럼 깨끗하게 사용해주실 분\n시설과 기본 물품을 아껴서 사용해주실 분\n성함 / 연령대 / 업종 / 희망 입주일을 보내주시면 확인 후 연락드리겠습니다.\n​\n문의: https://open.kakao.com/o/s0uhWUPi\n죽전동 샵인쉐어\nopen.kakao.com\n​",
