    "body": "기존 같이 하시던 속눈썹 원장님이 그만두시게 되어서,\n샵인샵이나 베드쉐어 하실 분 구하고 있습니다.\n베드 쉐어 먼저 해보시고 나중에 샵인샵 하셔도 되시고,\n샵인샵으로 들어오시게 되면 최대한 홍보 도와드리고 있습니다!\n​\n​\n​\n위치 :청량리역 4분거리\n주차 : 60분 2천원 추가요금 30분당 천원 ( 무료주차지원 불가 )\n엘레베이터 O ,층마다 화장실 O\n종목 :속눈썹,반영구 가능 / 왁싱은 불가 (샵 내부에 수도x)\n​\n* 건물내에 속눈썹연장샵은 따로 없습니다.\n* 시술 재료 지참 해주시고, 접이식 베드,담요,의자,책상,트롤리,수납장 있습니다.\n* 와이파이 사용 가능\n* 완벽한 단독룸은 아니지만, 가벽으로 구분되어있습니다.\n* 각종 소모품은 무상지원 물,화장지,물티슈\n​\n[베드쉐어]\n- 월~토 11시~21시 일요일 휴무\n- 이용 시간 : 11:00~21:00\n- 이용 요금 시간당 15,000원\n- 반일권: 4만원\n- 종일권: 7만원\n- 장기 이용 별도 협의\n- 시술 재료 지참 / 의자,책상,트롤리,수납장,조명,베게 있습니다.\n​\n​\n[샵인샵] 6개월 계약\n- 보증금 80만원 월세 35만원(관리비포함)\n- 사업자등록 불가\n- 입간판, 배너, 포스터 가능 따로 세워두셔도 됩니다\n- 네이버 플레이스 예약상품 추가 등록 가능 또는 단독플레이스 따로 만드셔도 됩니다.\n- 네이버 플레이스 같이 사용시 권한 부여해드리고, 같이 쓰는 프로그램도 사용가능\n(네이버 광고메세지도 보내실 수 있게 해드리고, 최대한 홍보도와드립니다! 네이버플레이스 1페이지유지중)\n네일이랑 눈썹 같이 하고 싶은 분들이 많아요..\n- 예약터치일절x , 24시 경비원 상주\n​\n직접 보시고 싶은 분들은 따로 문의 주세요\n010-2706-9367\n​\n​",
