    "body": "서울대입구역 역세권 샵인쉐어 사용하실 분 구합니다!\n​\n깔끔한 화이트 인테리어로 밝은 조명의 인테리어입니다.\n제가 오랫동안 애지중지 사용한 깨끗한 공간입니다!\n함께 예쁜 곳에서 저와 함께 성장하실 원장님 구합니다 ^^! (까칠하지 않은 분이었으면 좋겠습니다)\n​\n총 20평 중 공용공간 제외하고 개인 베드공간 3-4평정도 됩니다! (작업공간 생각보다 정말 넓습니다. 직접 보시면 공간 넓다고 다들 좋아하셨어요)\n​\n⭐️100/40입니다!\n​\n출퇴근 자유롭게 하시고 언제든 편하게 24시간 눈치보지 말고 사용하세요 😉\n​\n⭐️인포메이션, 컴퓨터 (인터넷사용가능), 정수기, 티테이블, 작업자휴식공간 , 화장대 ,소독기 ,개인락카룸 , 상담테이블, 고객서비스물품 , 소독용제품, 다과서비스, 종이컵, 개인사용 파티션 , 공용 부분조명, 디자인체어 , 포토존 등\n⭐️마이 베드 시스템 (1인 1베드 지정베드)으로 이용기간 동안 방해 없이 내 공간 예쁘게 꾸미고 사용하세요!\n⭐️CCTV 내, 외부 설치 되어있음\n⭐️무료 인터넷 / WIFI 이용 가능\n⭐️개인 트롤리 (트레이) ,손거울,워터클렌저 및 개인사용 앞치마 제공\n⭐️그 외에 위생용품, 일회용품, 공용물품 풍족하고 다양한 서비스 제공\n​\n🔥* 작업하실 도구만 직접 가지고 오시면 됩니다 ^^! *🔥.\n​\n​\n-종목: 반0구, SMP, 속눈썹펌, 속눈썹연장, 미니 ㅌ투 등\n​\n​\n제가 작업중에는 답변이 느릴 수 있습니다 -!\n보는즉시 바로 답장드릴게요 ^^!\n010-팔육팔육-1852 반드시 지원양식에 맞춰 연락부탁드립니다 -!\n​\nㅁ 지원양식\n-성함, 연락처, 연령대:\n- 종목 :\n-인스타그램 아이디 (실제 사용하는 샵 계정):",
