    "body": "(대신 올립니다)\nPrevious image\nNext image\n​\n2026.09 기존에 계시던 샵인 원장님 독립하셔서 다시 구합니다!\n​\n​\n💕 수원역 뷰티 샵인샵 원장님 모십니다 💕\n​\n수원역 인근 신축상가 내\n샵인샵으로 함께하실 원장님을 기다리고 있어요 :)\n​\n현재 말못할종목 + 속눈썹 위주 / 네일 로 운영 중이며\n​\n붙임머리, SMP, 왁싱, 피부, 타투, 메이크업, 속눈썹, ㅂㅇㄱ 등\n다양한 뷰티 업종과의 시너지를 기대하고 있습니다!\n(네일 제외 ㅂㅇㄱ 속눈썹 종목 겹쳐도 무방)\n​\n​\n📍 위치\n​\n수원역 도보 7분 거리(바로 앞 버스정류장있음)\n고등동 중심 상가 건물 내 위치 (수원역과 가장 가까운 신축상가)\n신축 아파트 단지 밀집 지역\n상가 바로 앞/옆 재개발 진행 중 → 앞으로 더 좋아질 입지\n고객 접근성 및 장기 운영에 유리한 안정된 상권\n​\n​\n🏠 공간 정보\n​\n총 13평 넓은 공간\n베드 1개 단독 대여 가능\n신축상가로 시설 깔끔하고 상가내 화장실있음(문열자마자 바로앞)\n​\n24시간 사용 가능 / 출퇴근 자유(터치 절대없음!!) / 무료주차제공 / 즉시입주가능\n​\n​\n🛠 집기 및 설비 제공\n베드, 트롤리, 조명, 미용의자, 실내화\n상담용 테이블, 고객용 쇼파, 냉장고, 커피, 스피커\n시스템 냉난방기 완비\n카드단말기 대여 가능\n​\n* 샤워 시설은 없으며 싱크대 있습니다.\n​\n​\n💰 이용 조건\n[샵인샵] 200 / 40 (6개월단위)\n[베드쉐어] 100 / 30 (1개월단위)\n[타임제] 12,000원 / 1시간\n50,000원 / 1일\n관리비 없음\n사업자 등록 및 네이버플레이스 불가\n* 전대차계약서 작성 필수 (양측 권리 보호 목적)\n​\n​\n🤝 모집 업종\n붙임머리 / SMP / 왁싱 / 피부관리 / 타투 / 메이크업 / 속눈썹 / ㅂㅇㄱ\n종목 겹쳐도 무방합니다 (예약제 위주로 운영 중)\n혼자하기 두렵고 어려운 초보 원장님, 독립 준비 중인 분도 환영\n함께 성장하고 배려하며 시너지를 낼 수 있는 분이면 좋겠습니다 :)\n​\n​\n궁금하신 분은 부담 없이 연락 주세요!\n​\n공간 투어나 상담도 가능해요 💌\n​\n​\n010-구649-369육\nhttps://open.kakao.com/o/sqxvavxh",
