    "body": "유동인구 많은 부산역 인근 베드쉐어, 샵인샵 원장님 모십니다~!!\n*연습하실분/ 샵 오픈 전 연습목적 / 포트폴리용 목적 / 오래 쉬다가 손 푸시는분 /\n자격증 취득전 연습 베드가 없어서 불편하신분들 베드쉐어 해드립니다/\n​\n💼 입점 가능 업종\n​\n(속눈썹,피부,왁싱,메이크업,smp,ㅂㅇㄱ)\n네일은 따로 연락주시면 더넓은 공간 있어요!\n🪞 시설 안내\n​\n-단독 룸 제공 (프라이빗하게 운영 가능)\n​\n-베드 / 의자 / 베드커버 / 라이트 / 서랍장 / 행거 / 개인 사물함 / 룸안에 에어컨(냉난방)\n베드쉐어 공간은 공동사용이며, 내것처럼 깨끗하게 이용해주세요!\n*사업자는 안되세요ㅠㅠ\n베드쉐어 (시간 1만원) 하루종일( 5만원) 한달이상 문의 주세용\n*베드쉐어 여러 룸 베드 사용 가능\n각 룸마다 베드 달라용\n*대기 공간 있음\n*내부 화장실\n🚪기타\n​\n-출퇴근 자유 (터치 없음)\n​\n-건물 3층 전체 사용으로 조용하고 쾌적한 환경\n​\n-인근 유료주차장 다수\n​\n​\n💰 임대 조건\n​\n보증금50 / 월세30 (관리비 포함)\n​\n🏠 현재 총 3개 룸 모집 중입니다.\n​\n(선착순 계약 / 룸별 크기 약간 상이)\n​\n📞 문의\n​\n010-팔삼칠칠 -사사팔오\n​",
