    "body": "​\n✨ 속눈썹 / ㅂㅇㄱ 샵인샵 원장님 한 분 모십니다 ✨\n​\n봉담 동화중심상가에서 함께하실\n샵인샵 원장님 한 분 구합니다 :)\n​\n📍 위치\n봉담 동화중심상가 / 아파트 상가\n→ 상권 내 유동인구 있는 편이라 접근성 좋아요!\n​\n💰 보증금 100 월 35만원 / 관리비 포함\n​\n🚗 주차 편리\n아파트 상가라 주차 이용 편하게 가능합니다.\n​\n🪑 대기공간 완비\n고객님들이 편하게 기다리실 수 있는 대기공간도 마련되어 있어요.\n​\n📋 사업자 등록 가능\n​\n👁️ 속눈썹 원장님\n재료 트롤리까지 필요하신 경우\n월 5만원 추가로 함께 사용 가능합니다.\n​\n깔끔하고 편하게 오래 함께하실 원장님을 찾고 있어요 🤍\n관심 있으신 분은 편하게 문의 주세요!\n01076450904\n​\n​",
