    "summary": "​ 이 자리에서 5년했구요 대단지 아파트 상권이라 고객분들 단골 유치하기 좋아요. ​ 그리고 동네 특성상 고객분들도 되게 좋으세요ㅠ 해보시면 아시겠지만.. 그동안 진상 경험 없었습니다. ​ 상가 주변 사장님들도 다들 좋으세요! ​ 제가 개인적인 일로 아쉽지만 잠시 쉬게 되어서 글 올려요",
    "body": "​\n이 자리에서 5년했구요\n대단지 아파트 상권이라\n고객분들 단골 유치하기 좋아요.\n​\n그리고 동네 특성상 고객분들도 되게 좋으세요ㅠ\n해보시면 아시겠지만..\n그동안 진상 경험 없었습니다.\n​\n상가 주변 사장님들도 다들 좋으세요!\n​\n제가 개인적인 일로\n아쉽지만 잠시 쉬게 되어서 글 올려요\n​\n​\n✔️ 주차 가능 (무료,시간제한없음)\n✔️ 보증금 1,000만원\n✔️ 월세 55만원 (부가세 포함)\n✔️ 관리비 사용량만큼 별도\n✔️ 권리금 600만원\n​\n​\n​\n​\n​\n현재 저는 피부,속눈썹.패디플래닝,반09 하고 있구요\n샤워실은 없어서 왁싱샵 제외하고는 다 가능해요\n(간단한 왁싱은 가능)\n​\n​\n창업 준비하시는 예비 원장님들은\n좋은 상권, 저렴한 월세로 시작하기 좋으실거에요.\n원하시면 제가 기술 전수도 해드립니다.\n​\n경력자 원장님들은\n아파트 단지가 많아서 단골 잡기 최적입니다.\n홍보도 하시면 다른 동네에서 신규 분들도 많이오세요.\n​\n​\n중구이기 때문에\n동구,서구에서도 오시고 유성구에서도 간혹 오십니다.\n​\n​\n​\n​\n애정 많은 샵이라 정말 좋은 분께 이어드리고 싶어요\n​\n​\n에어컨/베드2개/웨건/온장고/의자/테이블 등등\n샵에 있는 기기 모두 놓고갑니다.\n오시는 원장님께 제 고객님들 모두 연결해드려요.\n​\n​\n​\n​\n​\n관심 있으신 분은 편하게 문의 부탁드립니다.\n​\n​\n​\n문의 01공 52육일 사73칠\n(시술중 전화불가라 문자 남겨주시면 감사하겠습니다.)\n​\n​\n​\n​\n​\n​\n​\n​\n​\n​\n​\n​",
