    "summary": "확장이전으로 인한 홍대입구역 뷰티샵 양도(매매) 합니다. ​ 임대 정보 ​ - 보증금 : 2000만원 - 월세 : 200만원 - 관리비 : 20만원 - 해당 층 : 5층 (엘레베이터 유) - 시설권리금 : 500으로 낮췄어요 ​ (베드3개+의자3개,락커2개,거울,3단선반 테이블+테이블의",
    "body": "확장이전으로 인한 홍대입구역 뷰티샵 양도(매매) 합니다.\n​\n임대 정보\n​\n- 보증금 : 2000만원\n- 월세 : 200만원\n- 관리비 : 20만원\n- 해당 층 : 5층 (엘레베이터 유)\n- 시설권리금 : 500으로 낮췄어요\n​\n(베드3개+의자3개,락커2개,거울,3단선반\n테이블+테이블의자6개,카운터+카운터의자\n3단 수납장,벽난로콘솔,행거,미니냉장고 )\n​\n인테리어 하실 필요도 없고 바로 시술 하실 수 있게 대부분 놓고 가려고해요 안쓰신다고하면 더 낮은금액으로도 협의 가능해요 ^^\n​\n​\n🖤건물 정보🖤\n​\n- 건물 내 주차가능(무료)\n- 건물 청소담당자 유\n- 신축건물에 깔끔함\n- 엘레베이터 유,내부 화장실 유\n- 베란다있고 통창이라 채광 좋음\n-냉난방 겸용 에어컨 유\n-깔끔한 화이톤 인테리어\n-베드3개 정도 들어갑니다\n​\n홍대입구역 도보 2~3분 초 역세권 상가입니다\n손님들이 오기 쉽다며 너무 편하다고 하셔요\n또한 외국인도 많고 유동인구가 많아서 플레이스나 홍보만 잘 하시면 매출 무조건 좋으실 거에요\n두분이서 운영하시거나 베드쉐어하시면 월세는 금방 뽑으실 수 있을정도로 상권이 너무 좋아요\n​\n저도 이 샵에서 매출 잘나와서 애착가는 샵인데 이전해야되서 어쩔 수 없이 내놓습니다🥲저의 기운도 받아가시고 입지좋은곳에서 높은매출 원하시는분들 연락주세요💛\n​\n​\n문의 연락처 : 010-5514-2712 (통화 어려우니 문자부탁드립니다)",
