    "body": "​\n안녕하세요 :)\n​\n​\n​\n이사로 인해 지역이동으로\n​\n샵 양도양수 하실 분 찾고 있습니다.\n​\n​\n​\n인천 남동구 논현동 논현역 도보2분이내 ​\n​\n현재 피부/뷰티샵으로 운영 중인 공간입니다.\n​\n​\n​\n전용 약 8평대 규모로\n​\n혼자 운영하시기에도 좋고 2인 운영도 가능한 구조입니다.\n​\n​\n​\n기본 인테리어가 되어 있어\n​\n재료와 개인 장비만 준비하시면 바로 운영 가능하며,\n​\n초기 창업 비용 부담을 줄이고 시작하시기 좋은 공간입니다.\n​\n​\n​\n현재는 룸 1개 구조이나\n​\n창고 공간을 정리 및 활용하시면\n​\n샵인샵 형태로 추가 공간 활용도 가능합니다.\n​\n​\n​\n✔ 보증금 1000만원\n​\n✔ 월세 45만원 (부가세 별도)\n​\n✔ 권리금 1000만원(협의 가능)\n​\n✔ 주차 편함\n​\n​\n​\n주변 상권 및 주차 편의 괜찮은 편이며\n​\n조용하게 1인샵 운영하시기 좋은 분위기입니다.\n​\n관심 있으신 분은 편하게 문의 주세요 :)\n​\n​\n​\n스탠드형 에어컨, 세면대, 온수기, 정수기 기타집기류 있습니다\n​\n​\n​\n010-구이이팔-2115로 문자주세요~\n​",
