    "body": "◇ 모집분야\n​\n(슈가링왁싱,ㅂㅇㄱ눈썹 모집 X)\n• SMP\n• 퍼스널컬러\n• 붙임머리\n• 피부관리\n• 네일\n• 메이크업\n• 하드왁싱,소프트왁싱\n• ㅂㅇㄱ(입술/아이라인 가능)\n​\n• 보증금/월세 : 보증금 200 월세45(관리비 포함)\n​\n충남 천안시 서북구에 위치/ 샵인샵 원장님 모집합니다!\n성정동 초역세권 오피스텔 밀집구역에 있어 접근성이 매우 좋으며 11년째 운영중인 샵이에요:)\n​\n개별 1인 공간((천장 완전 분리,독립 베드 제공))으로\n내 공간처럼 편안하게 운영 가능하며\n샵 내부 화장실, 샤워실 있으며 세탁기,건조기,창고도 따로 있어서 원장님들 재료 수납 가능해요:)\n지하1층-2층 주차장으로 주차 편하게 가능합니다! (주차시간 제한 없음)\n대기실은 공용으로 사용 가능하며 (샵 실평수30평입니다. 고객님 대기공간 커요) 베드 불필요하시면 베드 빼드려요!\n​\n영업시간 : 오전 10:00 마감 22:00 (일요일 오전10시~20시까지)\n​\n- 뷰티 경력자 모두 환영\n- 개인 영업 자유 / 스케줄 전적으로 본인 자율\n- 퇴근 시 본인 방 소등 및 자리 정리만 해주시면 됩니다\n​\n내 공간처럼 편안하게 운영하실 분\n그 외 본인만의 시술 브랜드 운영 희망하시는 모든 분야 가능\n👉 누구나 본인만의 스타일, 고객층, 브랜딩 존중합니다.\n​\n✅ 베드쉐어 : 단독으로 사용하실 수 있습니다\n바로 사용 가능 개인물품만 가져오셔서 바로 시작하세요!\n​\n💬 이런 분에게 추천드려요\n🙋🏻‍♀️ 수강 후 바로 개인 샵 차리기 어려운 초보 원장님!\n🙋🏻‍♀️ 비용 부담 없이 시작하고 싶은 원장님!\n🙋🏻‍♀️ 독립적 공간에서 자유롭게 일하고 싶으신 원장님!\n🙋🏻‍♀️ 포폴 준비하시는 예비 원장님 !\n​\n​\n• 문의 (문자/전화/카톡) 010-9958-9112\n​\n궁금하신 점이나 방문 상담 원하시면 편하게 전화/문자 주세요!\n전화연결 안될시 문자남겨주시면 연락 드리겠습니다.😊\n​\nPrevious image\nNext image\n​",
