    "ts": 1788163320107,
    "summary": "안녕하세요~ 9호선 급행역 염창역 도보 6분거리 피부관리실내 샵인샵 구합니다. 근처 1인샵을 시작으로 현재 영업점까지 7년된 샵이라 안정적으로 자리잡혀 실력있는 분이면 금방 고객을 확보할수 있습니다. 전 샵인샵과는 계약종료로 새로운 분 구합니다. 그전 원장님들도 기본 1년반이상 영업하셨",
    "body": "안녕하세요~\n9호선 급행역 염창역 도보 6분거리 피부관리실내 샵인샵 구합니다.\n근처 1인샵을 시작으로 현재 영업점까지 7년된 샵이라 안정적으로 자리잡혀 실력있는 분이면 금방 고객을 확보할수 있습니다.\n전 샵인샵과는 계약종료로 새로운 분 구합니다.\n그전 원장님들도 기본 1년반이상 영업하셨으며, 입지나 시설 모두 깨끗하며 쾌적합니다.\n샵인샵 단독룸은 5평정도입니다.\n​\n*종목 속눈썹연장및 펌, 왁싱(여성전용 원함)\n경력 1년이상 실력있는 분 원하며 샵인샵이나 샵 운영하신 분 선호합니다.\n*영업시간내 출퇴근 터치없음(토요일 매주 영업가능)\n*화장실은 단독사용하며 샵 내부에 있습니다.(간단한 샤워시설있슴)\n*주차가능\n*비사업자(네이버플레이스 조건 승인후 가능)\n*단독룸이 커서 배드2개, 옷장, 수납장, 웨건 ,이불 구비되어 있으며 개인재료만 가져오심 됩니다.\n*와이파이 설치완료라 바로 인터넷 연결\n*매너 있는분이면 좋겠으며 공용공간 기간 정하여 돌아가며 청소합니다.\n​\n*염창역 4번출구 도보 6분거리(찾기쉽고 유동인구많음)\n7층건물중 3층 메이제이스킨내 샵인샵\n엘리베이터 있슴\n​\n*보증금200/월세 60(관리비포함)\n탕비실및 고객대기실 공용비품 모두 사용가능\n(개인 쓰레기만 따로 관리)\n*6개월단위 연장\n9월부터 함께 하실분 구합니다.\n* 홍보용 1층 배너 1개 지원해드립니다.\n그밖의 문의는 연락주세요^^\n010-5162-2528\n​\n​",
