    "ts": 1788156098613,
    "summary": "✨ 이사만 오시면 바로 영업 가능합니다. ​ 시설 투자 없이 시작하는 36평 프리미엄 토탈뷰티샵 양도 뷰티샵을 준비해 보신 분들은 아실 겁니다. 좋은 상권을 찾고, 인테리어 업체를 알아보고, 공사를 하고, 동선을 다시 수정하고, 가구를 들이고, 룸을 만들고, 수납을 짜고, 주차까지 되는",
    "body": "✨ 이사만 오시면 바로 영업 가능합니다.\n​\n시설 투자 없이 시작하는 36평 프리미엄 토탈뷰티샵 양도\n뷰티샵을 준비해 보신 분들은 아실 겁니다.\n좋은 상권을 찾고,\n인테리어 업체를 알아보고,\n공사를 하고,\n동선을 다시 수정하고,\n가구를 들이고,\n룸을 만들고,\n수납을 짜고,\n주차까지 되는 곳을 찾는 일.\n생각보다 시간도, 비용도 정말 많이 듭니다.\n저 역시 수많은 시행착오 끝에 4번째로 확장한 이 공간을 완성했습니다.\n현재 저는 이전을 결정하게 되어, 이 공간을 이어받으실 좋은 원장님께 시설을 양도하려 합니다.\n​\n🏡 공간만 보셔도 왜 좋은지 아실 겁니다.\n✔ 약 40평 규모\n✔ 1인 프라이빗 시술룸 2개\n✔ 2인 동시 시술룸 1개\n✔ 상담실\n✔ 2인네일바\n✔ 카운터\n✔ 3인 리클라이너존(페디 및 문제성발톱)\n✔ 원장실 겸 1:1 교육실\n✔ 넓은 고객 대기 공간\n✔ 제품 진열 및 판매 공간\n✔ 세탁실\n탕비실\n✔ 넉넉한 수납공간\n✔ 우리 매장만 사용하는 넓은 단독 옥상과 텃밭\n✔ 애견동반가능\n하루 종일 실내에서 일하는 뷰티업 특성상, 잠시 숨을 돌릴 수 있는 옥상은 생각보다 큰 만족을 줍니다. 그 외 세탁실 쓰레기 재활용부터 빨래 말리는 곳 어닝까지 달아서 카페존으로도 씁니다.\n저희는 애견동반 가능하게 해서 강아지들이랑 와서 놀다 가시는 분들도 많습니다.\nAI 활용 설정\n사진 설명을 입력하세요.\n💎 어떤 업종이든 바로 시작 가능합니다.\n현재는 토탈뷰티샵으로 운영 중이며,\n✔ 속눈썹\n✔ 네일\n✔ 피부관리\n✔ 왁싱\n✔ 반영구\n✔ 붙임머리\n✔ 샵인샵\n모두 운영 가능한 구조입니다.\n속눈썹 전문샵으로 운영하셔도 좋고,\n토탈뷰티샵으로 확장하셔도 좋고,\n직원을 채용해 규모를 키우시거나 교육을 병행하시는 분께도 적합합니다.\n​\n​\n💅 네일 시설도 완비\n✔ 2인 손·발 동시 시술 가능한 네일바\n✔ 리클라이너 페디 소파 3대\n✔ 최대 3명 동시 페디 시술 가능\n별도의 추가 공사 없이 바로 운영하실 수 있습니다.\n​\n​\n🚗 석계역에서는 보기 드문 장점\n주차 때문에 예약을 포기하는 고객이 적지 않습니다.\n이곳은\n✔ 건물 내 주차 포함 총 7대 주차 가능\n✔ 인근 공영주차장 이용 가능\n고객과 직원 모두 편하게 방문할 수 있는 환경입니다.\n​\n​\n📍 앞으로가 더 기대되는 입지\n장위뉴타운 입주가 이어지면서 새로운 고객층이 꾸준히 유입되고 있습니다.\n앞으로도 성장 가능성을 기대할 수 있는 지역입니다.\n📈 안정적으로 운영해 온 공간\n최근 경기가",
