    "summary": "경기도 시흥입니다^^ 배곧신도시에 위치하고 있는 토탈 뷰티샵 샵인샵 베드쉐어 구하고 있습니다^^ 베드와 웨건/조명 등 기본적인 것들은 준비가 되어 있고 사용하실 제품만 가지고 오시면 바로 이용가능하세요! ​ 현재 속눈썹 샵인원장님 계약종료를 앞두고 있어 9월20일부터 가능합니다! (날짜",
    "body": "경기도 시흥입니다^^\n배곧신도시에 위치하고 있는 토탈 뷰티샵 샵인샵 베드쉐어 구하고 있습니다^^\n베드와 웨건/조명 등 기본적인 것들은 준비가 되어 있고 사용하실 제품만 가지고 오시면\n바로 이용가능하세요!\n​\n현재 속눈썹 샵인원장님 계약종료를 앞두고 있어 9월20일부터 가능합니다!\n(날짜조율 가능)\n단독룸은 아니며 베드 3개 나란히 있는 1인샵입니다~\n​\n※지정베드로 한자리 드립니다(자동 높낮이 베드 X)\n※사업자 불가(원하신다면 엘베광고 등 홍보 가능)\n​\n현재 피부/09/속눈썹펌 종목은 샵에서 하고 있는 종목들이라 겹치지 않는 종목이면 더 좋겠습니다^^\n​\n연습공간이 필요하신분, 창업전 실무 경험을 쌓고 싶으신분, 다양한 분야를 접해보고 싶으신 분 등\n15년 이상의 경력 원장님께서 계시기 때문에 초보이신 분들은 도와드릴 수 있는 부분\n많이 도와드릴테니 편하게 문의주세요^^\n겹치는 종목으로 들어오셔도 마음 맞으면 오래 도록 같이 할 수도 있다고 생각해요 ㅎㅎ♥\n샵인이 부담스러우신 분들은 베드쉐어로 첫 시작을 하셔도 좋을 것 같네요!\n​\n❤️시간제 이용가능/최소 2시간 이상\n(시간당 15000원)\n❤️샵인 쉐어계약 최소 3개월부터 협의\n(보증금X, 선불 월 35+관리비 1/n)\n❤️출/퇴근 자유\n❤️주차등록 및 금액협의 가능\n​\n문의 : 01079408534\n​\n​\n​",
