    "summary": "📍 삼성중앙역 도보권｜인테리어 완료된 프라이빗 에스테틱·속눈썹샵 양도 ​ 권리금 무권리입니다. 시설과 집기가 대부분 갖춰져 있어 큰 초기비용 없이 바로 운영 가능한 샵입니다. ​ 올해 초(2~3월경) 이전하면서 인테리어를 새롭게 진행했고, 실제로 에스테틱과 속눈썹을 함께 운영했던 공간입",
    "body": "📍 삼성중앙역 도보권｜인테리어 완료된 프라이빗 에스테틱·속눈썹샵 양도\n​\n권리금 무권리입니다.\n시설과 집기가 대부분 갖춰져 있어 큰 초기비용 없이 바로 운영 가능한 샵입니다.\n​\n올해 초(2~3월경) 이전하면서 인테리어를 새롭게 진행했고, 실제로 에스테틱과 속눈썹을 함께 운영했던 공간입니다.\n​\n정성 들여 예쁘게 꾸며놓은 곳이라 아쉽지만 개인적인 사정으로 양도합니다.\n​\n빠른 입주 가능하신 분은 협의 가능합니다.\n정말 필요한 것들 대부분 두고 갑니다 :)\n​\n⸻\n​\n✨ 이런 분께 특히 추천드려요\n​\n✔ 에스테틱·피부관리실 오픈 예정이신 분\n✔ 속눈썹 1인샵 찾으시는 분\n✔ 피부 + 속눈썹 함께 운영하실 분\n✔ 큰 인테리어 비용 없이 바로 시작하고 싶으신 분\n✔ 조용하고 프라이빗한 예약제 샵을 찾으시는 분\n​\n현재 구조에서도 바로 운영 가능하며,\n가구 위치를 조정하면 베드 2대도 충분히 배치 가능합니다.\n​\n⸻\n​\n🏠 공간의 가장 큰 장점\n​\n엘리베이터가 있는 4층 건물이며\n한 층에 1개 사업장만 있는 구조라 조용하고 프라이빗합니다.\n​\n특히 혼자 운영하시는 여성 원장님께 좋은 부분이 보안입니다.\n​\n✔ 각 층 CCTV 설치\n✔ 출입문 안면인식 시스템\n✔ 비밀번호 출입 가능\n✔ 인터넷 설치되어 있어 별도 설치 필요 없음\n​\n예약제 1인샵으로 운영하기 편한 구조입니다.\n​\n⸻\n​\n📍 입지\n​\n✔ 삼성중앙역 도보권\n✔ 주변 직장인 수요가 많은 지역\n✔ 길 건너 대단지 아파트 위치\n✔ 예약제 운영에 적합한 조용한 환경\n✔ 네이버 플레이스·블로그·인스타그램 등 온라인 홍보 활용하기 좋은 위치\n​\n근처에 네일샵은 있지만 피부관리·에스테틱·속눈썹 전문샵은 상대적으로 많지 않은 편입니다.\n​\n⸻\n​\n🚗 주차\n​\n✔ 도보 7분 이내 공영주차장\n✔ 도보 4분 거리 주차장 이용 가능\n✔ 해당 주차장 오후 5시 이후 무료 이용 가능\n✔ 주말·공휴일 건물 주차 가능\n✔ 고객 방문 시 잠시 주차 가능\n​\n⸻\n​\n💰 임대 조건\n​\n보증금 2,000만원\n월세 160만원\n관리비 없음\n권리금 0만원 (인하 가격)\n​\n관리비가 별도로 없어 매달 고정비 관리에도 장점이 있습니다.\n​\n빠른 입주 시 협의 가능합니다.\n​\n⸻\n​\n🛋 시설 및 집기\n​\n실평수 10평 이상\n​\n✔ 샵 내부 단독 화장실\n✔ 샤워 가능\n✔ 화장실 리모델링 완료\n✔ 비데 설치\n✔ 라디에이터 설치\n✔ 천장형 냉난방기\n✔ 전신거울\n✔ 냉장고\n✔ 싱크대 및 미니바\n✔ 소파\n✔ 가구",
